{
  "name": "Compass Pong AI",
  "description": "Um jogo de Pong futurista onde você controla a raquete girando seu dispositivo (bússola/giroscópio) contra uma IA sarcástica.",
  "requestFramePermissions": [
    "gyroscope",
    "accelerometer"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum GameState {
  MENU = 'MENU',
  PLAYING = 'PLAYING',
  GAME_OVER = 'GAME_OVER'
}

export interface Ball {
  x: number;
  y: number;
  dx: number;
  dy: number;
  speed: number;
  radius: number;
}

export interface Paddle {
  x: number;
  y: number;
  width: number;
  height: number;
  score: number;
}

export interface GameDimensions {
  width: number;
  height: number;
}

export type CommentaryType = 'start' | 'player_score' | 'cpu_score' | 'win' | 'lose';

import { GoogleGenAI } from "@google/genai";
import { CommentaryType } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const MODEL_NAME = "gemini-2.5-flash";

const SYSTEM_INSTRUCTION = `
Você é a IA de um jogo de Pong retro-futurista. 
Sua personalidade é competitiva, levemente sarcástica e robótica.
Fale sempre em Português do Brasil.
Seja breve (máximo 15 palavras).
Não use emojis.
`;

export const generateCommentary = async (type: CommentaryType, playerScore: number, cpuScore: number): Promise<string> => {
  let prompt = "";

  switch (type) {
    case 'start':
      prompt = "O jogo começou. O humano está desafiando você. Dê uma saudação intimidadora.";
      break;
    case 'player_score':
      prompt = `O humano marcou ponto. Placar: Humano ${playerScore} - ${cpuScore} CPU. Dê uma desculpa esfarrapada ou ameace virar o jogo.`;
      break;
    case 'cpu_score':
      prompt = `Você (CPU) marcou ponto. Placar: Humano ${playerScore} - ${cpuScore} CPU. Zombe da habilidade do humano.`;
      break;
    case 'win':
      prompt = "Você (CPU) venceu o jogo. Humilhe o jogador de forma engraçada.";
      break;
    case 'lose':
      prompt = "O humano venceu o jogo. Mostre incredulidade e exija uma revanche.";
      break;
  }

  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: prompt,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        maxOutputTokens: 60,
        thinkingConfig: { thinkingBudget: 0 } // Low latency preferred for game commentary
      }
    });

    return response.text || "...";
  } catch (error) {
    console.error("Gemini Commentary Error:", error);
    return "Erro nos circuitos de comunicação...";
  }
};

import React, { useRef, useEffect, useState, useCallback } from 'react';
import { Ball, Paddle, GameDimensions, GameState, CommentaryType } from '../types';

interface GameCanvasProps {
  gameState: GameState;
  onScoreUpdate: (playerScore: number, cpuScore: number, scorer: 'player' | 'cpu') => void;
  onGameOver: (winner: 'player' | 'cpu') => void;
}

const GameCanvas: React.FC<GameCanvasProps> = ({ gameState, onScoreUpdate, onGameOver }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();

  // Game Logic State (Refs for performance to avoid re-renders during loop)
  const dimensions = useRef<GameDimensions>({ width: window.innerWidth, height: window.innerHeight });
  const ball = useRef<Ball>({ x: 0, y: 0, dx: 0, dy: 0, speed: 0, radius: 8 });
  const player = useRef<Paddle>({ x: 0, y: 0, width: 15, height: 100, score: 0 });
  const cpu = useRef<Paddle>({ x: 0, y: 0, width: 15, height: 100, score: 0 });
  const initialAlpha = useRef<number | null>(null); // For compass calibration

  // Configuration
  const PADDLE_OFFSET = 30;
  const WINNING_SCORE = 5;

  // Initialize Game Objects
  const initGame = useCallback(() => {
    if (!canvasRef.current) return;
    const { width, height } = canvasRef.current;

    dimensions.current = { width, height };

    // Player on Left, CPU on Right
    player.current = { ...player.current, x: PADDLE_OFFSET, y: height / 2 - 50, score: 0 };
    cpu.current = { ...cpu.current, x: width - PADDLE_OFFSET - 15, y: height / 2 - 50, score: 0 };

    resetBall();
  }, []);

  const resetBall = () => {
    const { width, height } = dimensions.current;
    const speed = 7;
    // Random direction
    const direction = Math.random() > 0.5 ? 1 : -1;
    const angle = (Math.random() * Math.PI) / 3 - Math.PI / 6; // +/- 30 degrees

    ball.current = {
      x: width / 2,
      y: height / 2,
      dx: speed * Math.cos(angle) * direction,
      dy: speed * Math.sin(angle),
      speed: speed,
      radius: 8
    };
  };

  // Sensor Handling
  const handleOrientation = useCallback((event: DeviceOrientationEvent) => {
    if (gameState !== GameState.PLAYING) return;

    // Using Alpha (Compass/Rotation around Z axis) as requested, 
    // but mixing in Beta (tilt) as fallback/hybrid for better playability.
    // If user rotates phone like a steering wheel (Gamma) or pivots body (Alpha).

    // Let's implement a relative system based on initial calibration.
    let currentAngle = 0;

    // Priority: Alpha (Compass) if available and distinct, else Beta/Gamma depending on orientation.
    // Most reliable for "Pong" holding phone: Gamma (Landscape) or Beta (Portrait).
    // The prompt specifically asked for "Bússola" (Compass/Alpha).

    if (event.alpha !== null) {
      if (initialAlpha.current === null) {
        initialAlpha.current = event.alpha;
      }

      // Calculate delta angle handling the 0-360 wrap around
      let delta = event.alpha - initialAlpha.current;
      if (delta > 180) delta -= 360;
      if (delta < -180) delta += 360;

      currentAngle = delta;
    } else if (event.gamma !== null) {
      // Fallback to tilt if compass not available
      currentAngle = event.gamma; 
    }

    const { height } = dimensions.current;
    const paddleHeight = player.current.height;

    // Sensitivity map: -30 degrees to +30 degrees maps to full screen height
    const SENSITIVITY = 4; 
    const centerY = height / 2;
    const targetY = centerY + (currentAngle * SENSITIVITY * (height / 100));

    // Clamping
    player.current.y = Math.max(0, Math.min(height - paddleHeight, targetY - paddleHeight / 2));

  }, [gameState]);

  useEffect(() => {
    window.addEventListener('deviceorientation', handleOrientation);
    window.addEventListener('resize', handleResize);

    // Setup Canvas
    if (canvasRef.current) {
      canvasRef.current.width = window.innerWidth;
      canvasRef.current.height = window.innerHeight;
      initGame();
    }

    return () => {
      window.removeEventListener('deviceorientation', handleOrientation);
      window.removeEventListener('resize', handleResize);
      cancelAnimationFrame(requestRef.current!);
    };
  }, [handleOrientation, initGame]);

  const handleResize = () => {
    if (canvasRef.current) {
      canvasRef.current.width = window.innerWidth;
      canvasRef.current.height = window.innerHeight;
      dimensions.current = { width: window.innerWidth, height: window.innerHeight };
      // Reposition paddles relative to new height
      player.current.y = Math.min(player.current.y, window.innerHeight - player.current.height);
      cpu.current.x = window.innerWidth - PADDLE_OFFSET - 15;
    }
  };

  // Game Loop
  const update = () => {
    if (gameState !== GameState.PLAYING) return;

    const b = ball.current;
    const p = player.current;
    const c = cpu.current;
    const { width, height } = dimensions.current;

    // Ball Movement
    b.x += b.dx;
    b.y += b.dy;

    // Wall Collision (Top/Bottom)
    if (b.y + b.radius > height || b.y - b.radius < 0) {
      b.dy *= -1;
      // Prevent sticking
      b.y = Math.max(b.radius, Math.min(height - b.radius, b.y));
    }

    // Paddle Collision - Player
    if (
      b.x - b.radius < p.x + p.width &&
      b.y > p.y &&
      b.y < p.y + p.height &&
      b.dx < 0
    ) {
      // Hit logic
      let collidePoint = b.y - (p.y + p.height / 2);
      collidePoint = collidePoint / (p.height / 2);

      const angleRad = (Math.PI / 4) * collidePoint;

      const direction = 1; // move right
      b.dx = direction * b.speed * Math.cos(angleRad);
      b.dy = b.speed * Math.sin(angleRad);

      b.speed += 0.2; // Increase speed slightly
    }

    // Paddle Collision - CPU
    if (
      b.x + b.radius > c.x &&
      b.y > c.y &&
      b.y < c.y + c.height &&
      b.dx > 0
    ) {
       // Hit logic
       let collidePoint = b.y - (c.y + c.height / 2);
       collidePoint = collidePoint / (c.height / 2);

       const angleRad = (Math.PI / 4) * collidePoint;

       const direction = -1; // move left
       b.dx = direction * b.speed * Math.cos(angleRad);
       b.dy = b.speed * Math.sin(angleRad);

       b.speed += 0.2;
    }

    // Scoring
    if (b.x - b.radius < 0) {
      // CPU Scores
      c.score++;
      onScoreUpdate(p.score, c.score, 'cpu');
      if (c.score >= WINNING_SCORE) {
        onGameOver('cpu');
      } else {
        resetBall();
      }
    } else if (b.x + b.radius > width) {
      // Player Scores
      p.score++;
      onScoreUpdate(p.score, c.score, 'player');
      if (p.score >= WINNING_SCORE) {
        onGameOver('player');
      } else {
        resetBall();
      }
    }

    // AI Logic (Simple tracking with delay/error)
    const aiTargetY = b.y - c.height / 2;
    const aiSpeed = 6 + (b.speed * 0.5); // AI gets faster as ball gets faster

    // Simple Lerp for smooth but beatable movement
    if (c.y < aiTargetY) {
      c.y += Math.min(aiSpeed, aiTargetY - c.y);
    } else {
      c.y -= Math.min(aiSpeed, c.y - aiTargetY);
    }

    // Clamp AI
    c.y = Math.max(0, Math.min(height - c.height, c.y));
  };

  const draw = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Clear
    ctx.fillStyle = '#050505';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // Draw Net
    ctx.strokeStyle = '#334155';
    ctx.setLineDash([10, 15]);
    ctx.beginPath();
    ctx.moveTo(canvas.width / 2, 0);
    ctx.lineTo(canvas.width / 2, canvas.height);
    ctx.stroke();
    ctx.setLineDash([]);

    // Draw Player
    ctx.fillStyle = '#0ea5e9'; // Sky blue
    ctx.shadowBlur = 15;
    ctx.shadowColor = '#0ea5e9';
    ctx.fillRect(player.current.x, player.current.y, player.current.width, player.current.height);

    // Draw CPU
    ctx.fillStyle = '#ef4444'; // Red
    ctx.shadowBlur = 15;
    ctx.shadowColor = '#ef4444';
    ctx.fillRect(cpu.current.x, cpu.current.y, cpu.current.width, cpu.current.height);

    // Draw Ball
    ctx.fillStyle = '#ffffff';
    ctx.shadowBlur = 10;
    ctx.shadowColor = '#ffffff';
    ctx.beginPath();
    ctx.arc(ball.current.x, ball.current.y, ball.current.radius, 0, Math.PI * 2);
    ctx.fill();

    // Reset Shadow
    ctx.shadowBlur = 0;
  };

  const loop = () => {
    update();
    draw();
    requestRef.current = requestAnimationFrame(loop);
  };

  useEffect(() => {
    requestRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(requestRef.current!);
  }); // Run loop on every render commit (controlled by requestAnimationFrame internally)

  // Reset calibration when game starts
  useEffect(() => {
    if (gameState === GameState.PLAYING) {
       // Reset initial alpha next event
       initialAlpha.current = null;
    }
  }, [gameState]);

  return (
    <canvas
      ref={canvasRef}
      className="block touch-none"
    />
  );
};

export default GameCanvas;

import React, { useState, useEffect, useRef } from 'react';
import GameCanvas from './components/GameCanvas';
import { GameState, CommentaryType } from './types';
import { generateCommentary } from './services/geminiService';
import { Compass, Rotate3d, Play, RotateCcw } from 'lucide-react';

export default function App() {
  const [gameState, setGameState] = useState<GameState>(GameState.MENU);
  const [scores, setScores] = useState({ player: 0, cpu: 0 });
  const [commentary, setCommentary] = useState<string>("Iniciando sistemas...");
  const [permissionGranted, setPermissionGranted] = useState<boolean>(false);
  const [loadingCommentary, setLoadingCommentary] = useState(false);

  const requestPermission = async () => {
    if (typeof (DeviceOrientationEvent as any).requestPermission === 'function') {
      try {
        const response = await (DeviceOrientationEvent as any).requestPermission();
        if (response === 'granted') {
          setPermissionGranted(true);
          startGame();
        } else {
          alert('Permissão para sensores negada. O jogo precisa da bússola/giroscópio.');
        }
      } catch (e) {
        console.error(e);
        // Sometimes non-secure contexts throw error, but standard Android doesn't need request
        setPermissionGranted(true);
        startGame();
      }
    } else {
      // Non-iOS 13+ devices
      setPermissionGranted(true);
      startGame();
    }
  };

  const startGame = () => {
    setScores({ player: 0, cpu: 0 });
    setGameState(GameState.PLAYING);
    updateCommentary('start', 0, 0);
  };

  const updateCommentary = async (type: CommentaryType, pScore: number, cScore: number) => {
    setLoadingCommentary(true);
    const text = await generateCommentary(type, pScore, cScore);
    setCommentary(text);
    setLoadingCommentary(false);
  };

  const handleScoreUpdate = (pScore: number, cScore: number, scorer: 'player' | 'cpu') => {
    setScores({ player: pScore, cpu: cScore });
    updateCommentary(scorer === 'player' ? 'player_score' : 'cpu_score', pScore, cScore);
  };

  const handleGameOver = (winner: 'player' | 'cpu') => {
    setGameState(GameState.GAME_OVER);
    updateCommentary(winner === 'player' ? 'lose' : 'win', scores.player, scores.cpu);
  };

  return (
    <div className="relative w-full h-full">
      {/* Game Layer */}
      <div className="absolute inset-0 z-0">
        <GameCanvas 
          gameState={gameState} 
          onScoreUpdate={handleScoreUpdate}
          onGameOver={handleGameOver}
        />
      </div>

      {/* UI Overlay */}
      <div className="absolute inset-0 z-10 pointer-events-none flex flex-col justify-between p-4 md:p-8">

        {/* Score Board */}
        <div className="flex justify-between items-start w-full max-w-4xl mx-auto">
          <div className="flex flex-col items-center">
            <span className="text-sm md:text-lg text-sky-400 font-bold brand-font tracking-widest">HUMANO</span>
            <span className="text-4xl md:text-6xl text-white font-mono drop-shadow-[0_0_10px_rgba(14,165,233,0.8)]">
              {scores.player}
            </span>
          </div>

          {/* AI Commentary Box */}
          <div className="flex-1 mx-4 md:mx-12 mt-2">
             <div className="bg-black/80 border border-slate-700 p-3 md:p-4 rounded-lg backdrop-blur-sm relative overflow-hidden min-h-[80px] flex items-center justify-center text-center">
                <div className={`absolute top-0 left-0 w-1 h-full ${loadingCommentary ? 'bg-yellow-500 animate-pulse' : 'bg-green-500'}`}></div>
                <p className="text-xs md:text-sm text-green-400 font-mono leading-relaxed">
                  <span className="mr-2 text-slate-500">[AI_LOG]:</span>
                  {commentary}
                  <span className="animate-pulse inline-block w-2 h-4 bg-green-500 ml-1 align-middle"></span>
                </p>
             </div>
          </div>

          <div className="flex flex-col items-center">
            <span className="text-sm md:text-lg text-red-500 font-bold brand-font tracking-widest">CPU</span>
            <span className="text-4xl md:text-6xl text-white font-mono drop-shadow-[0_0_10px_rgba(239,68,68,0.8)]">
              {scores.cpu}
            </span>
          </div>
        </div>

        {/* Start Screen / Menu */}
        {gameState === GameState.MENU && (
          <div className="absolute inset-0 z-20 flex items-center justify-center bg-black/90 pointer-events-auto backdrop-blur-md">
            <div className="text-center max-w-md px-6">
              <h1 className="text-5xl md:text-7xl font-black text-transparent bg-clip-text bg-gradient-to-r from-sky-400 to-indigo-500 brand-font mb-2">
                PONG AI
              </h1>
              <p className="text-slate-400 mb-8 font-mono text-sm">SENSOR EDITION</p>

              <div className="bg-slate-900/50 p-6 rounded-xl border border-slate-800 mb-8 text-left space-y-4">
                <div className="flex items-start space-x-3">
                  <Compass className="w-6 h-6 text-sky-400 shrink-0 mt-1" />
                  <div>
                    <h3 className="text-white font-bold">Controle via Bússola/Giroscópio</h3>
                    <p className="text-slate-400 text-xs mt-1">
                      Gire seu corpo ou incline o celular para mover a raquete. 
                      O jogo calibrará o "centro" assim que começar.
                    </p>
                  </div>
                </div>
                <div className="flex items-start space-x-3">
                   <Rotate3d className="w-6 h-6 text-red-400 shrink-0 mt-1" />
                   <div>
                     <h3 className="text-white font-bold">Orientações</h3>
                     <p className="text-slate-400 text-xs mt-1">Segure o celular firmemente. Gire para Direita/Esquerda (Eixo Z) ou Incline (Eixo Y).</p>
                   </div>
                </div>
              </div>

              <button 
                onClick={requestPermission}
                className="group relative px-8 py-4 bg-white text-black font-bold text-lg rounded-full hover:bg-sky-400 hover:text-white transition-all duration-300 flex items-center justify-center mx-auto space-x-2"
              >
                <Play className="w-5 h-5 group-hover:scale-110 transition-transform" />
                <span>INICIAR JOGO</span>
                <div className="absolute -inset-1 rounded-full bg-white/20 blur opacity-0 group-hover:opacity-100 transition-opacity"></div>
              </button>
            </div>
          </div>
        )}

        {/* Game Over Screen */}
        {gameState === GameState.GAME_OVER && (
          <div className="absolute inset-0 z-20 flex items-center justify-center bg-black/85 pointer-events-auto backdrop-blur-sm">
            <div className="text-center">
              <h2 className={`text-6xl font-black brand-font mb-4 ${scores.player > scores.cpu ? 'text-sky-400' : 'text-red-500'}`}>
                {scores.player > scores.cpu ? 'VITÓRIA' : 'DERROTA'}
              </h2>
              <p className="text-white font-mono text-xl mb-8">
                {scores.player} - {scores.cpu}
              </p>
              <button 
                onClick={startGame}
                className="px-8 py-3 bg-transparent border-2 border-white text-white font-bold rounded-full hover:bg-white hover:text-black transition-colors flex items-center justify-center mx-auto space-x-2"
              >
                <RotateCcw className="w-5 h-5" />
                <span>JOGAR NOVAMENTE</span>
              </button>
            </div>
          </div>
        )}

        {/* Footer info */}
         <div className="w-full text-center pb-4 opacity-50 text-[10px] font-mono">
            POWERED BY GOOGLE GEMINI
         </div>
      </div>
    </div>
  );
}

{
  "name": "Polygon Chaos",
  "description": "Um simulador de física onde bolas se multiplicam ao colidir com um polígono giratório.",
  "requestFramePermissions": []
}

export interface Ball {
  id: string;
  x: number;
  y: number;
  vx: number;
  vy: number;
  radius: number;
  color: string;
  lastCollisionTime: number;
}

export interface PolygonConfig {
  sides: number;
  radius: number;
  rotationSpeed: number;
  gravity: number;
  friction: number;
  wallBounce: number;
}

// Service removido para focar na física pura.
// Este arquivo é mantido vazio para evitar erros de importação legados se houver, 
// mas não é utilizado no novo app.
export const generateCommentary = async () => { return ""; };

export interface Ball {
  id: string;
  x: number;
  y: number;
  vx: number;
  vy: number;
  radius: number;
  color: string;
  cooldown: number; // To prevent instant double collisions
}

export interface PolygonConfig {
  sides: number;
  radius: number;
  rotationSpeed: number;
  gravity: number;
  friction: number;
  wallBounce: number;
}

import React, { useState, useCallback } from 'react';
import PolygonPhysics from './components/PolygonPhysics';
import { PolygonConfig } from './types';
import { RefreshCw, Settings, Play, Pause } from 'lucide-react';

export default function App() {
  const [isRunning, setIsRunning] = useState(true);
  const [ballCount, setBallCount] = useState(1);
  const [config, setConfig] = useState<PolygonConfig>({
    sides: 8,
    radius: 150, // Will be scaled by screen size in component
    rotationSpeed: 0.02,
    gravity: 0.15,
    friction: 0.999,
    wallBounce: 1.2, // Adds energy on bounce
  });

  // Force reset key
  const [resetKey, setResetKey] = useState(0);

  const handleReset = () => {
    setBallCount(1);
    setResetKey(prev => prev + 1);
    setIsRunning(true);
  };

  return (
    <div className="relative w-full h-full bg-[#050505] overflow-hidden text-white font-mono select-none">

      {/* Background Ambience */}
      <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-slate-900 via-[#050505] to-[#000000] z-0" />

      {/* Physics Canvas */}
      <div className="absolute inset-0 z-10">
        <PolygonPhysics 
          key={resetKey}
          config={config} 
          onBallCountChange={setBallCount}
          isRunning={isRunning}
        />
      </div>

      {/* UI Overlay */}
      <div className="absolute inset-0 z-20 pointer-events-none p-6 flex flex-col justify-between">

        {/* Header */}
        <div className="flex justify-between items-start pointer-events-auto">
          <div>
            <h1 className="text-4xl md:text-6xl font-black text-transparent bg-clip-text bg-gradient-to-r from-cyan-400 to-purple-500 font-sans tracking-tighter">
              POLY<span className="text-white">CHAOS</span>
            </h1>
            <p className="text-slate-500 text-xs md:text-sm tracking-widest mt-1">SIMULADOR DE FÍSICA EXPONENCIAL</p>
          </div>

          <div className="flex space-x-2">
             <button 
              onClick={() => setIsRunning(!isRunning)}
              className="p-3 bg-slate-800/50 backdrop-blur border border-slate-700 rounded-full hover:bg-slate-700 hover:text-cyan-400 transition-all active:scale-95"
            >
              {isRunning ? <Pause size={20} /> : <Play size={20} />}
            </button>
            <button 
              onClick={handleReset}
              className="p-3 bg-slate-800/50 backdrop-blur border border-slate-700 rounded-full hover:bg-slate-700 hover:text-cyan-400 transition-all active:scale-95"
            >
              <RefreshCw size={20} />
            </button>
          </div>
        </div>

        {/* Stats */}
        <div className="self-center text-center pointer-events-auto">
          <div className="mb-2 text-slate-400 text-xs uppercase tracking-widest">Contagem de Bolas</div>
          <div className={`text-6xl md:text-8xl font-black tabular-nums transition-colors duration-300 ${ballCount >= 1000 ? 'text-red-500' : 'text-white'}`} 
               style={{textShadow: ballCount >= 1000 ? '0 0 30px rgba(239,68,68,0.5)' : '0 0 20px rgba(255,255,255,0.2)'}}>
            {ballCount}
          </div>
          {ballCount >= 1500 && (
             <div className="text-red-500 text-xs mt-2 animate-pulse font-bold">LIMITE DE SEGURANÇA ATINGIDO</div>
          )}
        </div>

        {/* Footer / Controls Hint */}
        <div className="pointer-events-auto w-full max-w-md self-center bg-slate-900/40 backdrop-blur border border-slate-800/50 rounded-xl p-4">
           <div className="flex justify-between items-center text-xs text-slate-400 mb-2">
              <span>Velocidade de Rotação</span>
              <span>{(config.rotationSpeed * 100).toFixed(0)}%</span>
           </div>
           <input 
              type="range" 
              min="0" 
              max="0.1" 
              step="0.001" 
              value={config.rotationSpeed} 
              onChange={(e) => setConfig({...config, rotationSpeed: parseFloat(e.target.value)})}
              className="w-full h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer [&::-webkit-slider-thumb]:appearance-none [&::-webkit-slider-thumb]:w-4 [&::-webkit-slider-thumb]:h-4 [&::-webkit-slider-thumb]:bg-cyan-500 [&::-webkit-slider-thumb]:rounded-full hover:[&::-webkit-slider-thumb]:scale-125 transition-all"
           />
           <div className="mt-4 flex justify-between items-center text-xs text-slate-400 mb-2">
              <span>Gravidade</span>
              <span>{(config.gravity * 100).toFixed(0)}%</span>
           </div>
           <input 
              type="range" 
              min="0" 
              max="0.5" 
              step="0.01" 
              value={config.gravity} 
              onChange={(e) => setConfig({...config, gravity: parseFloat(e.target.value)})}
              className="w-full h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer [&::-webkit-slider-thumb]:appearance-none [&::-webkit-slider-thumb]:w-4 [&::-webkit-slider-thumb]:h-4 [&::-webkit-slider-thumb]:bg-purple-500 [&::-webkit-slider-thumb]:rounded-full hover:[&::-webkit-slider-thumb]:scale-125 transition-all"
           />
        </div>
      </div>
    </div>
  );
}

import React, { useRef, useEffect } from 'react';
import { Ball, PolygonConfig } from '../types';

interface PolygonPhysicsProps {
  config: PolygonConfig;
  onBallCountChange: (count: number) => void;
  isRunning: boolean;
}

const PolygonPhysics: React.FC<PolygonPhysicsProps> = ({ config, onBallCountChange, isRunning }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();

  // Physics state stored in refs to avoid React render cycle overhead
  const ballsRef = useRef<Ball[]>([]);
  const rotationRef = useRef<number>(0);
  const centerRef = useRef({ x: 0, y: 0 });
  const polygonRadiusRef = useRef(0);

  // Constants
  const MAX_BALLS = 1500;
  const BALL_RADIUS = 6;
  const SUB_STEPS = 8; // Higher = more precise physics

  // Initialization
  useEffect(() => {
    // Reset balls
    ballsRef.current = [{
      id: 'initial',
      x: 0, // Will be centered in resize
      y: -50,
      vx: (Math.random() - 0.5) * 10,
      vy: 0,
      radius: BALL_RADIUS,
      color: '#ffffff',
      cooldown: 0
    }];
    rotationRef.current = 0;
    onBallCountChange(1);

    // Initial resize to set center
    handleResize();
  }, []); // Only on mount/remount (key change in App.tsx handles reset)

  const handleResize = () => {
    if (canvasRef.current) {
      const { innerWidth, innerHeight } = window;
      canvasRef.current.width = innerWidth;
      canvasRef.current.height = innerHeight;

      centerRef.current = { x: innerWidth / 2, y: innerHeight / 2 };

      // Responsive radius
      const minDim = Math.min(innerWidth, innerHeight);
      polygonRadiusRef.current = Math.min(config.radius, minDim * 0.4);

      // If balls are empty (first run), center the first one
      if (ballsRef.current.length === 1 && ballsRef.current[0].x === 0) {
        ballsRef.current[0].x = innerWidth / 2;
        ballsRef.current[0].y = innerHeight / 2 - 50;
      }
    }
  };

  useEffect(() => {
    window.addEventListener('resize', handleResize);
    handleResize();
    return () => window.removeEventListener('resize', handleResize);
  }, [config.radius]);

  // Physics Loop
  const update = () => {
    if (!isRunning) return;

    const { width, height } = canvasRef.current || { width: 0, height: 0 };
    if (width === 0) return;

    const cx = centerRef.current.x;
    const cy = centerRef.current.y;
    const r = polygonRadiusRef.current;

    // Update Rotation
    rotationRef.current += config.rotationSpeed;

    // Calculate Polygon Vertices
    const vertices: {x: number, y: number}[] = [];
    const angleStep = (Math.PI * 2) / config.sides;
    for (let i = 0; i < config.sides; i++) {
      const ang = rotationRef.current + i * angleStep;
      vertices.push({
        x: cx + Math.cos(ang) * r,
        y: cy + Math.sin(ang) * r
      });
    }

    // Sub-stepping for stability
    const dt = 1 / SUB_STEPS;

    for (let step = 0; step < SUB_STEPS; step++) {
      ballsRef.current.forEach(ball => {
        // Gravity
        ball.vy += config.gravity * dt;

        // Friction
        ball.vx *= Math.pow(config.friction, dt);
        ball.vy *= Math.pow(config.friction, dt);

        // Move
        ball.x += ball.vx * dt;
        ball.y += ball.vy * dt;

        // Cooldown tick
        if (ball.cooldown > 0) ball.cooldown--;

        // Collision with Polygon Walls
        let collided = false;

        for (let i = 0; i < config.sides; i++) {
          const p1 = vertices[i];
          const p2 = vertices[(i + 1) % config.sides];

          // Vector P1 -> P2 (Wall vector)
          const dx = p2.x - p1.x;
          const dy = p2.y - p1.y;

          // Normal vector (perpendicular to wall, pointing inward)
          // Since vertices are CW or CCW, we need to ensure normal points to center.
          // Center is (cx, cy).
          // Let's use standard line distance formula.

          const len = Math.sqrt(dx * dx + dy * dy);
          const nx = -dy / len; // Normal x
          const ny = dx / len;  // Normal y

          // Check if this normal points towards center, if not flip it
          // Vector from P1 to Center
          const cdx = cx - p1.x;
          const cdy = cy - p1.y;
          if (nx * cdx + ny * cdy < 0) {
             // Invert normal
             // Actually for a convex polygon, if we order vertices correctly, it's consistent.
             // But simpler: just use distance from infinite line.
          }

          // Project ball center relative to P1 onto normal
          const ballDx = ball.x - p1.x;
          const ballDy = ball.y - p1.y;

          // Dot product with normal gives distance
          // We need the normal that points OUT of the shape to detect exit, 
          // OR points IN to detect containment.
          // Let's assume standard containment:
          // A point is inside if it is on the same side of all lines.

          // Easier approach for collision response:
          // Distance from line segment.

          const t = ((ball.x - p1.x) * dx + (ball.y - p1.y) * dy) / (len * len);
          const closestX = p1.x + t * dx;
          const closestY = p1.y + t * dy;

          // Check if closest point is on segment (approximate is fine for closed loop)
          // We only care if t is roughly 0..1, but corners are tricky.
          // Simplification: Check distance to infinite line, if close AND within bounding box of segment.

          // Robust approach: Dot product with inward normal.
          // Inward Normal:
          const midX = (p1.x + p2.x) / 2;
          const midY = (p1.y + p2.y) / 2;
          let inNx = cx - midX;
          let inNy = cy - midY;
          const inLen = Math.sqrt(inNx * inNx + inNy * inNy);
          inNx /= inLen;
          inNy /= inLen;

          const distToWall = (ball.x - p1.x) * inNx + (ball.y - p1.y) * inNy;

          // Since inNx points IN, positive distance means inside.
          // If distance < radius, we are touching or outside.

          if (distToWall < ball.radius && ball.cooldown <= 0) {
             // COLLISION DETECTED

             // 1. Position Correction (push out)
             const overlap = ball.radius - distToWall;
             ball.x += inNx * overlap;
             ball.y += inNy * overlap;

             // 2. Velocity Reflection
             // V_new = V_old - 2 * (V_old . N) * N
             const dot = ball.vx * inNx + ball.vy * inNy;

             // Only reflect if moving towards wall
             if (dot < 0) {
               ball.vx = (ball.vx - 2 * dot * inNx) * config.wallBounce;
               ball.vy = (ball.vy - 2 * dot * inNy) * config.wallBounce;

               // Add some tangential rotation boost from wall? 
               // (Optional, keeps it energetic)
               const tanX = -inNy;
               const tanY = inNx;
               const wallVelAtHit = config.rotationSpeed * r; // Approx
               ball.vx += tanX * wallVelAtHit * 0.1;
               ball.vy += tanY * wallVelAtHit * 0.1;

               collided = true;
               ball.cooldown = 10; // Frames to wait
             }
          }
        }

        // DUPLICATION LOGIC
        if (collided && ballsRef.current.length < MAX_BALLS) {
           const speed = Math.sqrt(ball.vx*ball.vx + ball.vy*ball.vy);
           const angle = Math.atan2(ball.vy, ball.vx);
           const spread = 0.5; // Radians spread

           // Create clone
           ballsRef.current.push({
             id: Math.random().toString(36),
             x: ball.x,
             y: ball.y,
             vx: Math.cos(angle + (Math.random()-0.5)*spread) * speed,
             vy: Math.sin(angle + (Math.random()-0.5)*spread) * speed,
             radius: Math.max(2, ball.radius * 0.95), // Slightly smaller?
             color: `hsl(${Math.random() * 360}, 70%, 60%)`,
             cooldown: 15
           });

           // Change original slightly too
           ball.vx = Math.cos(angle - (Math.random()-0.5)*spread) * speed;
           ball.vy = Math.sin(angle - (Math.random()-0.5)*spread) * speed;

           // Update count UI
           onBallCountChange(ballsRef.current.length);
        }
      });

      // Cleanup balls that fell out (tunneling safeguard)
      const distSqLimit = (r * 2) * (r * 2);
      ballsRef.current = ballsRef.current.filter(b => {
        const dx = b.x - cx;
        const dy = b.y - cy;
        return (dx*dx + dy*dy) < distSqLimit;
      });
    }
  };

  const draw = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Fade effect for trails
    ctx.fillStyle = 'rgba(5, 5, 5, 0.3)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    const cx = centerRef.current.x;
    const cy = centerRef.current.y;
    const r = polygonRadiusRef.current;

    // Draw Polygon
    ctx.beginPath();
    const angleStep = (Math.PI * 2) / config.sides;
    for (let i = 0; i <= config.sides; i++) {
      const ang = rotationRef.current + i * angleStep;
      const x = cx + Math.cos(ang) * r;
      const y = cy + Math.sin(ang) * r;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.closePath();
    ctx.lineWidth = 8;
    ctx.strokeStyle = '#22d3ee'; // Cyan
    ctx.shadowBlur = 20;
    ctx.shadowColor = '#22d3ee';
    ctx.stroke();
    ctx.shadowBlur = 0;

    // Draw Balls
    ballsRef.current.forEach(ball => {
      ctx.beginPath();
      ctx.arc(ball.x, ball.y, ball.radius, 0, Math.PI * 2);
      ctx.fillStyle = ball.color;
      ctx.fill();
    });
  };

  const loop = () => {
    update();
    draw();
    requestRef.current = requestAnimationFrame(loop);
  };

  useEffect(() => {
    requestRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(requestRef.current!);
  });

  return (
    <canvas ref={canvasRef} className="block w-full h-full" />
  );
};

export default PolygonPhysics;

{
  "name": "Marble Royale",
  "description": "Um jogo de corrida de bolinhas com eliminação, apostas e física realista.",
  "requestFramePermissions": []
}

export interface Marble {
  id: number;
  color: string;
  name: string;
  x: number;
  y: number;
  vx: number;
  vy: number;
  radius: number;
  finished: boolean;
  finishTime: number;
  rank: number; // 0 if not finished
}

export interface LineSegment {
  x1: number;
  y1: number;
  x2: number;
  y2: number;
  type: 'wall' | 'floor' | 'bouncer';
}

export interface CircleObstacle {
  x: number;
  y: number;
  radius: number;
  type: 'pin' | 'bumper';
}

export interface PhysicsConfig {
  gravity: number;
  restitution: number; // Bounciness 0.1 to 0.9
  friction: number;
}

export interface GameState {
  phase: 'betting' | 'racing' | 'round_result' | 'champion';
  round: number; // Starts at 1
  marbles: Marble[]; // All marbles
  activeMarbleIds: number[]; // IDs of marbles still in tournament
  betMarbleId: number | null;
  lastEliminatedId: number | null;
}

import React, { useRef, useEffect, useState } from 'react';
import { Marble, PhysicsConfig, LineSegment, CircleObstacle } from '../types';

interface RaceEngineProps {
  activeMarbles: Marble[];
  config: PhysicsConfig;
  onRaceFinish: (results: Marble[]) => void;
  betMarbleId: number | null;
}

const RaceEngine: React.FC<RaceEngineProps> = ({ activeMarbles, config, onRaceFinish, betMarbleId }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();

  // Physics State (Mutable refs for performance)
  const marblesRef = useRef<Marble[]>([]);
  const linesRef = useRef<LineSegment[]>([]);
  const pinsRef = useRef<CircleObstacle[]>([]);

  const cameraY = useRef(0);
  const raceFinished = useRef(false);
  const finishLineY = useRef(0);
  const startTime = useRef(0);

  // Constants
  const COURSE_WIDTH = 600; // Virtual coordinate width
  const BALL_RADIUS = 12;

  // --- Level Generation ---
  const generateLevel = () => {
    const lines: LineSegment[] = [];
    const pins: CircleObstacle[] = [];

    // Config
    const segments = 5 + Math.floor(Math.random() * 3); // Length of course
    const segmentHeight = 400;
    let currentY = 0;

    // 1. Start Funnel
    lines.push({ x1: 0, y1: 0, x2: COURSE_WIDTH * 0.4, y2: 150, type: 'wall' });
    lines.push({ x1: COURSE_WIDTH, y1: 0, x2: COURSE_WIDTH * 0.6, y2: 150, type: 'wall' });
    // Drop hole
    lines.push({ x1: COURSE_WIDTH * 0.4, y1: 150, x2: COURSE_WIDTH * 0.4, y2: 200, type: 'wall' });
    lines.push({ x1: COURSE_WIDTH * 0.6, y1: 150, x2: COURSE_WIDTH * 0.6, y2: 200, type: 'wall' });

    currentY = 250;

    // 2. Procedural Segments
    for (let i = 0; i < segments; i++) {
      const type = Math.random();

      // Outer Walls (keep them in bounds)
      lines.push({ x1: 0, y1: currentY, x2: 0, y2: currentY + segmentHeight, type: 'wall' });
      lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH, y2: currentY + segmentHeight, type: 'wall' });

      if (type < 0.33) {
        // --- Slopes (Zig Zag) ---
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.7, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 200, x2: COURSE_WIDTH * 0.3, y2: currentY + 300, type: 'floor' });
      } else if (type < 0.66) {
        // --- Peggle Field (Pins) ---
        const rows = 5;
        const cols = 6;
        for (let r = 0; r < rows; r++) {
          for (let c = 0; c < cols; c++) {
            const offsetX = (r % 2 === 0) ? 30 : 0;
            pins.push({
              x: (c * (COURSE_WIDTH / cols)) + 50 + offsetX,
              y: currentY + 50 + (r * 60),
              radius: 6,
              type: 'pin'
            });
          }
        }
      } else {
        // --- Center Spinner/Splitter ---
        lines.push({ x1: COURSE_WIDTH/2, y1: currentY + 50, x2: 0, y2: currentY + 250, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH/2, y1: currentY + 50, x2: COURSE_WIDTH, y2: currentY + 250, type: 'wall' });

        pins.push({ x: COURSE_WIDTH/2, y1: currentY + 50, radius: 15, type: 'bumper' });
      }

      currentY += segmentHeight;
    }

    // 3. Finish Funnel
    lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.4, y2: currentY + 200, type: 'wall' });
    lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.6, y2: currentY + 200, type: 'wall' });

    // Finish Line
    finishLineY.current = currentY + 250;

    linesRef.current = lines;
    pinsRef.current = pins;
  };

  // --- Physics Logic ---
  const update = () => {
    if (raceFinished.current) return;

    // Sub-stepping for stability
    const STEPS = 4;
    const dt = 1 / STEPS;

    let finishedCount = 0;
    const marbles = marblesRef.current;

    for (let step = 0; step < STEPS; step++) {
      for (let i = 0; i < marbles.length; i++) {
        const m = marbles[i];
        if (m.finished) {
          finishedCount++;
          continue;
        }

        // 1. Gravity & Movement
        m.vy += config.gravity * dt;
        m.x += m.vx * dt;
        m.y += m.vy * dt;

        // Friction / Air Resistance
        m.vx *= Math.pow(config.friction, dt);
        m.vy *= Math.pow(config.friction, dt);

        // 2. Wall/Line Collisions
        for (const line of linesRef.current) {
          checkLineCollision(m, line);
        }

        // 3. Pin Collisions
        for (const pin of pinsRef.current) {
          checkPinCollision(m, pin);
        }

        // 4. Marble-Marble Collisions
        for (let j = i + 1; j < marbles.length; j++) {
           const m2 = marbles[j];
           if (m2.finished) continue;
           checkMarbleCollision(m, m2);
        }

        // 5. Finish Line Check
        if (m.y > finishLineY.current) {
          m.finished = true;
          m.finishTime = Date.now() - startTime.current;
          // Determine temporary rank based on how many finished before
          const finishedSoFar = marbles.filter(b => b.finished).length;
          m.rank = finishedSoFar;
        }
      }
    }

    // Camera follow (Average of unfinished marbles)
    const activeY = marbles.filter(m => !m.finished).map(m => m.y);
    if (activeY.length > 0) {
      const avgY = activeY.reduce((a, b) => a + b, 0) / activeY.length;
      // Smooth lerp
      cameraY.current += (avgY - cameraY.current - 250) * 0.1;
    } else {
      // All finished
      if (!raceFinished.current) {
        raceFinished.current = true;
        // Sort by rank/time
        const sorted = [...marbles].sort((a, b) => a.rank - b.rank);
        setTimeout(() => onRaceFinish(sorted), 1000);
      }
    }
  };

  const checkLineCollision = (ball: Marble, line: LineSegment) => {
    // Vector Line
    const dx = line.x2 - line.x1;
    const dy = line.y2 - line.y1;
    const lenSq = dx*dx + dy*dy;

    // Project point onto line segment clamped
    const t = Math.max(0, Math.min(1, ((ball.x - line.x1) * dx + (ball.y - line.y1) * dy) / lenSq));

    const closeX = line.x1 + t * dx;
    const closeY = line.y1 + t * dy;

    const distX = ball.x - closeX;
    const distY = ball.y - closeY;
    const distSq = distX*distX + distY*distY;

    if (distSq < ball.radius * ball.radius) {
      const dist = Math.sqrt(distSq);
      const nx = distX / dist;
      const ny = distY / dist;

      // Push out
      const overlap = ball.radius - dist;
      ball.x += nx * overlap;
      ball.y += ny * overlap;

      // Reflect velocity
      const dot = ball.vx * nx + ball.vy * ny;
      if (dot < 0) {
        ball.vx = (ball.vx - 2 * dot * nx) * config.restitution;
        ball.vy = (ball.vy - 2 * dot * ny) * config.restitution;

        // Add random jitter to prevent stacking
        ball.vx += (Math.random() - 0.5) * 0.5;
      }
    }
  };

  const checkPinCollision = (ball: Marble, pin: CircleObstacle) => {
    const dx = ball.x - pin.x;
    const dy = ball.y - pin.y;
    const distSq = dx*dx + dy*dy;
    const minDist = ball.radius + pin.radius;

    if (distSq < minDist * minDist) {
      const dist = Math.sqrt(distSq);
      const nx = dx / dist;
      const ny = dy / dist;

      const overlap = minDist - dist;
      ball.x += nx * overlap;
      ball.y += ny * overlap;

      const dot = ball.vx * nx + ball.vy * ny;
      const bounciness = pin.type === 'bumper' ? 1.5 : config.restitution;

      if (dot < 0) {
        ball.vx = (ball.vx - 2 * dot * nx) * bounciness;
        ball.vy = (ball.vy - 2 * dot * ny) * bounciness;
      }
    }
  };

  const checkMarbleCollision = (m1: Marble, m2: Marble) => {
    const dx = m2.x - m1.x;
    const dy = m2.y - m1.y;
    const distSq = dx*dx + dy*dy;
    const minDist = m1.radius + m2.radius;

    if (distSq < minDist * minDist) {
      const dist = Math.sqrt(distSq);
      const nx = dx / dist;
      const ny = dy / dist;

      const overlap = (minDist - dist) * 0.5;

      m1.x -= nx * overlap;
      m1.y -= ny * overlap;
      m2.x += nx * overlap;
      m2.y += ny * overlap;

      // Simple elastic collision (assuming equal mass)
      const dvx = m1.vx - m2.vx;
      const dvy = m1.vy - m2.vy;
      const dot = dvx * nx + dvy * ny;

      if (dot > 0) {
         const impulse = dot * 0.9; // some energy loss
         m1.vx -= impulse * nx;
         m1.vy -= impulse * ny;
         m2.vx += impulse * nx;
         m2.vy += impulse * ny;
      }
    }
  };

  // --- Initialization ---
  useEffect(() => {
    generateLevel();
    raceFinished.current = false;
    startTime.current = Date.now();
    cameraY.current = 0;

    // Reset marbles to top
    marblesRef.current = activeMarbles.map((m, index) => ({
      ...m,
      x: COURSE_WIDTH * 0.4 + (Math.random() * COURSE_WIDTH * 0.2),
      y: -50 - (index * 40), // Stagger start
      vx: (Math.random() - 0.5) * 5,
      vy: 0,
      finished: false,
      rank: 0
    }));

  }, [activeMarbles]); // Re-run when round changes

  // --- Render Loop ---
  const draw = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Canvas Resize (Responsive)
    const { offsetWidth, offsetHeight } = canvas;
    if (canvas.width !== offsetWidth || canvas.height !== offsetHeight) {
      canvas.width = offsetWidth;
      canvas.height = offsetHeight;
    }

    // Clear
    ctx.fillStyle = '#1f2937';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.save();

    // Scale View to fit COURSE_WIDTH into screen width
    const scale = canvas.width / COURSE_WIDTH;
    ctx.scale(scale, scale);

    // Translate Camera
    // Keep camera bounded
    const camY = Math.max(0, Math.min(cameraY.current, finishLineY.current - canvas.height/scale + 100));
    ctx.translate(0, -camY);

    // Draw Lines
    ctx.lineWidth = 4;
    ctx.lineCap = 'round';

    linesRef.current.forEach(l => {
      ctx.strokeStyle = l.type === 'wall' ? '#4b5563' : '#60a5fa';
      if (l.type === 'wall') ctx.lineWidth = 6;
      else ctx.lineWidth = 4;

      ctx.beginPath();
      ctx.moveTo(l.x1, l.y1);
      ctx.lineTo(l.x2, l.y2);
      ctx.stroke();
    });

    // Draw Pins
    pinsRef.current.forEach(p => {
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.radius, 0, Math.PI * 2);
      ctx.fillStyle = p.type === 'bumper' ? '#f472b6' : '#9ca3af';
      ctx.fill();
    });

    // Draw Finish Line
    ctx.fillStyle = '#10b981';
    ctx.fillRect(0, finishLineY.current, COURSE_WIDTH, 10);
    // Chequered pattern
    for(let i=0; i<20; i++) {
        ctx.fillStyle = i%2===0 ? '#fff' : '#000';
        ctx.fillRect(i * (COURSE_WIDTH/20), finishLineY.current, COURSE_WIDTH/20, 10);
    }

    // Draw Marbles
    marblesRef.current.forEach(m => {
      ctx.beginPath();
      ctx.arc(m.x, m.y, m.radius, 0, Math.PI * 2);
      ctx.fillStyle = m.color;
      // Shadow
      ctx.shadowColor = 'rgba(0,0,0,0.5)';
      ctx.shadowBlur = 5;
      ctx.fill();
      ctx.shadowBlur = 0;

      // Shine
      ctx.beginPath();
      ctx.arc(m.x - 3, m.y - 3, 3, 0, Math.PI * 2);
      ctx.fillStyle = 'rgba(255,255,255,0.4)';
      ctx.fill();

      // Marker for Bet
      if (m.id === betMarbleId) {
        ctx.strokeStyle = '#fbbf24'; // Amber
        ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.arc(m.x, m.y, m.radius + 4, 0, Math.PI * 2);
        ctx.stroke();
      }

      // Name (Optional, only for leader or active)
      if (!m.finished) {
        ctx.fillStyle = '#fff';
        ctx.font = '10px Arial';
        ctx.textAlign = 'center';
        ctx.fillText(m.name, m.x, m.y - 15);
      }
    });

    ctx.restore();
  };

  useEffect(() => {
    const loop = () => {
      update();
      draw();
      requestRef.current = requestAnimationFrame(loop);
    };
    requestRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(requestRef.current!);
  });

  return (
    <canvas ref={canvasRef} className="w-full h-full block" />
  );
};

export default RaceEngine;

import React, { useState, useEffect } from 'react';
import RaceEngine from './components/RaceEngine';
import { Marble, GameState, PhysicsConfig } from './types';
import { Trophy, Settings, Skull, Play, Timer, ArrowDown } from 'lucide-react';

const NAMES = [
  "Thunder", "Lightning", "Comet", "Shadow", 
  "Blaze", "Frost", "Viper", "Titan", "Nova", "Ghost"
];

const COLORS = [
  "#ef4444", "#3b82f6", "#10b981", "#f59e0b",
  "#8b5cf6", "#ec4899", "#6366f1", "#14b8a6", "#f97316", "#64748b"
];

const INITIAL_MARBLES: Marble[] = NAMES.map((name, i) => ({
  id: i,
  name,
  color: COLORS[i],
  x: 0, y: 0, vx: 0, vy: 0, radius: 12,
  finished: false, finishTime: 0, rank: 0
}));

export default function App() {
  const [gameState, setGameState] = useState<GameState>({
    phase: 'betting',
    round: 1,
    marbles: INITIAL_MARBLES,
    activeMarbleIds: INITIAL_MARBLES.map(m => m.id),
    betMarbleId: null,
    lastEliminatedId: null,
  });

  const [physicsConfig, setPhysicsConfig] = useState<PhysicsConfig>({
    gravity: 0.25,
    restitution: 0.6,
    friction: 0.99
  });

  const activeMarblesList = gameState.marbles.filter(m => gameState.activeMarbleIds.includes(m.id));

  // --- Handlers ---

  const handleStartTournament = () => {
    if (gameState.betMarbleId === null) return;
    setGameState(prev => ({ ...prev, phase: 'racing' }));
  };

  const handleRaceFinish = (results: Marble[]) => {
    // The RaceEngine returns marbles sorted by rank (finish order)
    // The LAST marble in this sorted list is the one to eliminate
    const loser = results[results.length - 1];

    setGameState(prev => ({
      ...prev,
      phase: 'round_result',
      lastEliminatedId: loser.id
    }));
  };

  const handleNextRound = () => {
    // Remove the loser
    const nextActiveIds = gameState.activeMarbleIds.filter(id => id !== gameState.lastEliminatedId);

    if (nextActiveIds.length === 1) {
      setGameState(prev => ({
        ...prev,
        activeMarbleIds: nextActiveIds,
        phase: 'champion'
      }));
    } else {
      setGameState(prev => ({
        ...prev,
        activeMarbleIds: nextActiveIds,
        phase: 'racing',
        round: prev.round + 1,
        lastEliminatedId: null
      }));
    }
  };

  const resetGame = () => {
    setGameState({
      phase: 'betting',
      round: 1,
      marbles: INITIAL_MARBLES,
      activeMarbleIds: INITIAL_MARBLES.map(m => m.id),
      betMarbleId: null,
      lastEliminatedId: null,
    });
  };

  // --- Render Components ---

  // 1. Betting / Config Screen
  if (gameState.phase === 'betting') {
