import React, { useRef, useEffect } from 'react';
import { Marble, PhysicsConfig, LineSegment, CircleObstacle, DynamicObstacle } from '../types';

interface RaceEngineProps {
  activeMarbles: Marble[];
  config: PhysicsConfig;
  onRaceFinish: (results: Marble[]) => void;
  betMarbleId: number | null;
}

const RaceEngine: React.FC<RaceEngineProps> = ({ activeMarbles, config, onRaceFinish, betMarbleId }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();

  // Physics State (Mutable refs for performance)
  const marblesRef = useRef<Marble[]>([]);
  const linesRef = useRef<LineSegment[]>([]);
  const pinsRef = useRef<CircleObstacle[]>([]);
  const dynamicRef = useRef<DynamicObstacle[]>([]);

  const cameraY = useRef(0);
  const raceFinished = useRef(false);
  const finishLineY = useRef(0);
  const startTime = useRef(0);
  const timeRef = useRef(0);

  // Constants
  const COURSE_WIDTH = 600;
  const BALL_RADIUS = 12;

  // --- Level Generation ---
  const generateLevel = () => {
    const lines: LineSegment[] = [];
    const pins: CircleObstacle[] = [];
    const dynamics: DynamicObstacle[] = [];

    // Config
    const segments = 6 + Math.floor(Math.random() * 3);
    const segmentHeight = 450;
    let currentY = 0;

    // 1. Start Funnel
    lines.push({ x1: 0, y1: 0, x2: COURSE_WIDTH * 0.4, y2: 150, type: 'wall' });
    lines.push({ x1: COURSE_WIDTH, y1: 0, x2: COURSE_WIDTH * 0.6, y2: 150, type: 'wall' });
    lines.push({ x1: COURSE_WIDTH * 0.4, y1: 150, x2: COURSE_WIDTH * 0.4, y2: 180, type: 'wall' });
    lines.push({ x1: COURSE_WIDTH * 0.6, y1: 150, x2: COURSE_WIDTH * 0.6, y2: 180, type: 'wall' });

    currentY = 220;

    // 2. Procedural Segments
    for (let i = 0; i < segments; i++) {
      const type = Math.random();

      // Outer Walls
      lines.push({ x1: 0, y1: currentY - 50, x2: 0, y2: currentY + segmentHeight, type: 'wall' });
      lines.push({ x1: COURSE_WIDTH, y1: currentY - 50, x2: COURSE_WIDTH, y2: currentY + segmentHeight, type: 'wall' });

      if (type < 0.25) {
        // --- PROPELLERS (Spinners) ---
        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 100, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 100, type: 'floor' });

        dynamics.push({
          id: `spin_${i}_1`,
          type: 'spinner',
          x: COURSE_WIDTH * 0.35,
          y: currentY + 250,
          width: 140,
          angle: 0,
          speed: 0.1,
        });
        dynamics.push({
          id: `spin_${i}_2`,
          type: 'spinner',
          x: COURSE_WIDTH * 0.65,
          y: currentY + 350,
          width: 140,
          angle: Math.PI / 2,
          speed: -0.1,
        });

      } else if (type < 0.5) {
        // --- MOVING ELEVATORS (Vertical or Horizontal) ---
        const isVertical = Math.random() > 0.5;

        // Feeders
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.2, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.8, y2: currentY + 150, type: 'floor' });

        if (isVertical) {
           // Vertical Elevator Platform
           dynamics.push({
             id: `slide_v_${i}`,
             type: 'slider_v',
             x: COURSE_WIDTH / 2,
             y: currentY + 200,
             width: 200,
             angle: 0,
             speed: 1, // freq
             range: 100,
             initialX: COURSE_WIDTH / 2,
             initialY: currentY + 250
           });
        } else {
           // Horizontal Slider
           dynamics.push({
            id: `slide_h_${i}`,
            type: 'slider_h',
            x: COURSE_WIDTH / 2,
            y: currentY + 250,
            width: 250,
            angle: 0,
            speed: 2,
            range: 150,
            initialX: COURSE_WIDTH / 2,
            initialY: currentY + 250
          });
        }

      } else if (type < 0.75) {
        // --- CLASSIC SLALOM ---
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.6, y2: currentY + 180, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 250, x2: COURSE_WIDTH * 0.4, y2: currentY + 380, type: 'floor' });
        pins.push({ x: COURSE_WIDTH * 0.8, y: currentY + 200, radius: 15, type: 'bumper' });
        pins.push({ x: COURSE_WIDTH * 0.2, y: currentY + 400, radius: 15, type: 'bumper' });

      } else {
         // --- MIXER ---
        lines.push({ x1: COURSE_WIDTH/2, y1: currentY + 50, x2: COURSE_WIDTH * 0.3, y2: currentY + 120, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH/2, y1: currentY + 50, x2: COURSE_WIDTH * 0.7, y2: currentY + 120, type: 'wall' });
        lines.push({ x1: 0, y1: currentY + 250, x2: COURSE_WIDTH * 0.35, y2: currentY + 350, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 250, x2: COURSE_WIDTH * 0.65, y2: currentY + 350, type: 'floor' });
        pins.push({ x: COURSE_WIDTH/2, y: currentY + 400, radius: 25, type: 'bumper' });
      }

      currentY += segmentHeight;
    }

    // 3. Finish Area
    lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 200, type: 'floor' });
    lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 200, type: 'floor' });

    finishLineY.current = currentY + 250;

    linesRef.current = lines;
    pinsRef.current = pins;
    dynamicRef.current = dynamics;
  };

  // --- Physics Logic ---
  const update = () => {
    if (raceFinished.current) return;

    const STEPS = 4;
    const dt = 1 / STEPS;
    timeRef.current += 1;

    let finishedCount = 0;
    const marbles = marblesRef.current;
    const dynamicObjs = dynamicRef.current;

    // Update Dynamics
    const dynamicLines: LineSegment[] = [];
    dynamicObjs.forEach(obj => {
      if (obj.type === 'spinner') {
        obj.angle += obj.speed;
      } else if (obj.type === 'slider_h') {
        obj.x = obj.initialX! + Math.sin(timeRef.current * 0.02) * (obj.range || 100);
      } else if (obj.type === 'slider_v') {
        obj.y = obj.initialY! + Math.sin(timeRef.current * 0.015) * (obj.range || 80);
      }

      const halfW = obj.width / 2;
      const dx = Math.cos(obj.angle) * halfW;
      const dy = Math.sin(obj.angle) * halfW;

      dynamicLines.push({
        x1: obj.x - dx, y1: obj.y - dy,
        x2: obj.x + dx, y2: obj.y + dy,
        type: obj.type === 'spinner' ? 'bouncer' : 'floor'
      });
    });

    for (let step = 0; step < STEPS; step++) {
      for (let i = 0; i < marbles.length; i++) {
        const m = marbles[i];
        if (m.finished) {
          finishedCount++;
          continue;
        }

        // 1. Gravity & Movement
        m.vy += config.gravity * dt;
        m.x += m.vx * dt;
        m.y += m.vy * dt;

        // Update Angle based on Angular Velocity (Realistic)
        m.angle += m.omega * dt;

        // Air resistance on rotation
        m.omega *= 0.999; 

        // Linear Air resistance
        m.vx *= Math.pow(config.friction, dt);
        m.vy *= Math.pow(config.friction, dt);

        // Anti-stuck (weaker now that we have real physics, but good backup)
        if (m.vx*m.vx + m.vy*m.vy < 0.2) {
             m.vx += (Math.random() - 0.5); 
             m.vy += 0.5; 
        }

        // 2. Collisions
        for (const line of linesRef.current) checkLineCollision(m, line);
        for (const dLine of dynamicLines) checkLineCollision(m, dLine, true);
        for (const pin of pinsRef.current) checkPinCollision(m, pin);

        for (let j = i + 1; j < marbles.length; j++) {
           if (!marbles[j].finished) checkMarbleCollision(m, marbles[j]);
        }

        // 3. Finish Line
        if (m.y > finishLineY.current) {
          m.finished = true;
          m.finishTime = Date.now() - startTime.current;
          const finishedSoFar = marbles.filter(b => b.finished).length;
          m.rank = finishedSoFar;
        }
      }
    }

    // Camera
    const activeMarblesList = marbles.filter(m => !m.finished);
    if (activeMarblesList.length > 0) {
      activeMarblesList.sort((a, b) => b.y - a.y);
      const leaders = activeMarblesList.slice(0, 3); 
      const avgY = leaders.reduce((a, b) => a + b.y, 0) / leaders.length;
      cameraY.current += (avgY - cameraY.current - 300) * 0.08;
    } else {
      if (!raceFinished.current) {
        raceFinished.current = true;
        const sorted = [...marbles].sort((a, b) => a.rank - b.rank);
        setTimeout(() => onRaceFinish(sorted), 1000);
      }
    }
  };

  // Helper for applying physics impulse (Bounce + Friction/Rotation)
  const resolveCollisionPhysics = (ball: Marble, nx: number, ny: number, isBouncy: boolean) => {
    // Relative velocity along normal
    const vDotN = ball.vx * nx + ball.vy * ny;
    if (vDotN > 0) return; // Moving away

    // --- 1. Normal Impulse (Bounce) ---
    const restitution = isBouncy ? 1.5 : config.restitution;
    const jN = -(1 + restitution) * vDotN;
    ball.vx += jN * nx;
    ball.vy += jN * ny;

    // --- 2. Tangent Impulse (Rolling Friction) ---
    // Tangent vector
    const tx = -ny;
    const ty = nx;

    // Surface velocity at contact point = V_cm + (omega x r)
    // V_surf_tangent = V_dot_T + omega * r
    const vDotT = ball.vx * tx + ball.vy * ty;
    const vSurf = vDotT + ball.omega * ball.radius;

    // Impulse to stop sliding (static friction equivalent)
    // For sphere (I = 0.4mr^2), Factor = 3.5/m
    // Jt_ideal = -vSurf / 3.5
    const mass = 1.0;
    const jT_ideal = -vSurf / (3.5 / mass);

    // Coulomb Friction Clamp
    // We allow high friction to simulate good grip for rolling
    const mu = 0.5; // Friction Coeff
    const maxJt = mu * Math.abs(jN);

    let jT = jT_ideal;
    if (Math.abs(jT) > maxJt) {
       jT = Math.sign(jT) * maxJt;
    }

    // Apply Friction Impulse
    // dV = Jt / m
    ball.vx += jT * tx;
    ball.vy += jT * ty;

    // dOmega = (Jt * r) / I = (Jt * r) / (0.4 * m * r^2) = 2.5 * Jt / (m * r)
    ball.omega += (2.5 * jT) / (mass * ball.radius);
  };

  const checkLineCollision = (ball: Marble, line: LineSegment, isDynamic = false) => {
    const dx = line.x2 - line.x1;
    const dy = line.y2 - line.y1;
    const lenSq = dx*dx + dy*dy;
    const t = Math.max(0, Math.min(1, ((ball.x - line.x1) * dx + (ball.y - line.y1) * dy) / lenSq));
    const closeX = line.x1 + t * dx;
    const closeY = line.y1 + t * dy;

    const distX = ball.x - closeX;
    const distY = ball.y - closeY;
    const distSq = distX*distX + distY*distY;

    if (distSq < ball.radius * ball.radius) {
      const dist = Math.sqrt(distSq);
      const nx = distX / dist;
      const ny = distY / dist;

      // Position Correction
      const overlap = ball.radius - dist;
      ball.x += nx * overlap;
      ball.y += ny * overlap;

      const isBouncy = isDynamic && line.type === 'bouncer';
      resolveCollisionPhysics(ball, nx, ny, isBouncy);

      if (isDynamic) {
        // Add random chaos for moving parts
        ball.vx += (Math.random() - 0.5) * 2;
        ball.vy += (Math.random() - 0.5) * 2;
      }
    }
  };

  const checkPinCollision = (ball: Marble, pin: CircleObstacle) => {
    const dx = ball.x - pin.x;
    const dy = ball.y - pin.y;
    const distSq = dx*dx + dy*dy;
    const minDist = ball.radius + pin.radius;

    if (distSq < minDist * minDist) {
      const dist = Math.sqrt(distSq);
      const nx = dx / dist;
      const ny = dy / dist;

      const overlap = minDist - dist;
      ball.x += nx * overlap;
      ball.y += ny * overlap;

      const isBumper = pin.type === 'bumper';
      resolveCollisionPhysics(ball, nx, ny, isBumper);
    }
  };

  const checkMarbleCollision = (m1: Marble, m2: Marble) => {
    const dx = m2.x - m1.x;
    const dy = m2.y - m1.y;
    const distSq = dx*dx + dy*dy;
    const minDist = m1.radius + m2.radius;

    if (distSq < minDist * minDist) {
      const dist = Math.sqrt(distSq);
      const nx = dx / dist;
      const ny = dy / dist;
      const overlap = (minDist - dist) * 0.5;

      m1.x -= nx * overlap;
      m1.y -= ny * overlap;
      m2.x += nx * overlap;
      m2.y += ny * overlap;

      // Simple elastic collision for linear momentum
      const dvx = m1.vx - m2.vx;
      const dvy = m1.vy - m2.vy;
      const dot = dvx * nx + dvy * ny;

      if (dot > 0) {
         const impulse = dot * 0.9; // 0.9 restitution
         m1.vx -= impulse * nx;
         m1.vy -= impulse * ny;
         m2.vx += impulse * nx;
         m2.vy += impulse * ny;

         // Transfer some angular momentum?
         // For now, let's keep it simple: Friction between marbles is negligible compared to ground
      }
    }
  };

  // --- Initialization ---
  useEffect(() => {
    generateLevel();
    raceFinished.current = false;
    startTime.current = Date.now();
    cameraY.current = 0;
    timeRef.current = 0;

    marblesRef.current = activeMarbles.map((m, index) => ({
      ...m,
      x: COURSE_WIDTH * 0.4 + (Math.random() * COURSE_WIDTH * 0.2),
      y: -50 - (index * 40),
      vx: (Math.random() - 0.5) * 5,
      vy: 0,
      angle: 0,
      omega: 0,
      finished: false,
      rank: 0
    }));

  }, [activeMarbles]); 

  // --- Render Loop ---
  const draw = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const { offsetWidth, offsetHeight } = canvas;
    if (canvas.width !== offsetWidth || canvas.height !== offsetHeight) {
      canvas.width = offsetWidth;
      canvas.height = offsetHeight;
    }

    ctx.fillStyle = '#1f2937';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.save();
    const scale = canvas.width / COURSE_WIDTH;
    ctx.scale(scale, scale);
    const camY = Math.max(0, Math.min(cameraY.current, finishLineY.current - canvas.height/scale + 100));
    ctx.translate(0, -camY);

    // Draw Static Lines
    ctx.lineWidth = 4;
    ctx.lineCap = 'round';
    linesRef.current.forEach(l => {
      ctx.strokeStyle = l.type === 'wall' ? '#4b5563' : '#60a5fa';
      if (l.type === 'wall') ctx.lineWidth = 6;
      else ctx.lineWidth = 4;
      ctx.beginPath();
      ctx.moveTo(l.x1, l.y1);
      ctx.lineTo(l.x2, l.y2);
      ctx.stroke();
    });

    // Draw Dynamic Obstacles
    dynamicRef.current.forEach(obj => {
       ctx.save();
       ctx.translate(obj.x, obj.y);
       if (obj.type === 'spinner') ctx.rotate(obj.angle);
       // Sliders are pre-calculated lines, but we draw the platform body here

       ctx.strokeStyle = obj.type === 'spinner' ? '#ef4444' : '#f59e0b';
       ctx.lineWidth = 8;
       ctx.beginPath();
       ctx.moveTo(-obj.width/2, 0);
       ctx.lineTo(obj.width/2, 0);
       ctx.stroke();

       if (obj.type === 'spinner') {
         ctx.beginPath();
         ctx.arc(0, 0, 5, 0, Math.PI * 2);
         ctx.fillStyle = '#fff';
         ctx.fill();
       }
       ctx.restore();
    });

    // Draw Pins
    pinsRef.current.forEach(p => {
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.radius, 0, Math.PI * 2);
      ctx.fillStyle = p.type === 'bumper' ? '#f472b6' : '#9ca3af';
      ctx.fill();
    });

    // Draw Finish Line
    ctx.fillStyle = '#10b981';
    ctx.fillRect(0, finishLineY.current, COURSE_WIDTH, 10);
    for(let i=0; i<20; i++) {
        ctx.fillStyle = i%2===0 ? '#fff' : '#000';
        ctx.fillRect(i * (COURSE_WIDTH/20), finishLineY.current, COURSE_WIDTH/20, 10);
    }

    // Draw Marbles
    marblesRef.current.forEach(m => {
      ctx.save();
      ctx.translate(m.x, m.y);
      ctx.rotate(m.angle); 

      // Ball Body
      ctx.beginPath();
      ctx.arc(0, 0, m.radius, 0, Math.PI * 2);
      ctx.fillStyle = m.color;
      ctx.shadowColor = 'rgba(0,0,0,0.5)';
      ctx.shadowBlur = 5;
      ctx.fill();
      ctx.shadowBlur = 0;

      // Texture
      ctx.beginPath();
      ctx.moveTo(-m.radius, 0);
      ctx.lineTo(m.radius, 0);
      ctx.strokeStyle = 'rgba(255,255,255,0.5)';
      ctx.lineWidth = 3;
      ctx.stroke();

      ctx.beginPath();
      ctx.moveTo(0, -m.radius);
      ctx.lineTo(0, m.radius);
      ctx.strokeStyle = 'rgba(0,0,0,0.3)';
      ctx.lineWidth = 2;
      ctx.stroke();

      // Shine
      ctx.beginPath();
      ctx.arc(-4, -4, 3, 0, Math.PI * 2);
      ctx.fillStyle = 'rgba(255,255,255,0.7)';
      ctx.fill();

      ctx.restore(); 

      // Bet Marker
      if (m.id === betMarbleId) {
        ctx.strokeStyle = '#fbbf24';
        ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.arc(m.x, m.y, m.radius + 5, 0, Math.PI * 2);
        ctx.stroke();
      }

      if (!m.finished) {
        ctx.fillStyle = '#fff';
        ctx.font = '10px Arial';
        ctx.textAlign = 'center';
        ctx.fillText(m.name, m.x, m.y - 18);
      }
    });

    ctx.restore();
  };

  useEffect(() => {
    const loop = () => {
      update();
      draw();
      requestRef.current = requestAnimationFrame(loop);
    };
    requestRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(requestRef.current!);
  });

  return (
    <canvas ref={canvasRef} className="w-full h-full block" />
  );
};

export default RaceEngine;

class AudioService {
  private ctx: AudioContext | null = null;
  private rollingNode: AudioBufferSourceNode | null = null;
  private rollingGain: GainNode | null = null;
  private initialized: boolean = false;
  private lastBumpTime: number = 0;

  init() {
    if (this.initialized) return;

    const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
    this.ctx = new AudioContextClass();

    // --- Create Rolling Noise (Brown Noise for rumble) ---
    const bufferSize = this.ctx.sampleRate * 2; // 2 seconds loop
    const buffer = this.ctx.createBuffer(1, bufferSize, this.ctx.sampleRate);
    const data = buffer.getChannelData(0);

    let lastOut = 0;
    for (let i = 0; i < bufferSize; i++) {
      const white = Math.random() * 2 - 1;
      data[i] = (lastOut + (0.02 * white)) / 1.02;
      lastOut = data[i];
      data[i] *= 3.5; // Auto-gain compensation
    }

    this.rollingGain = this.ctx.createGain();
    this.rollingGain.gain.value = 0;

    // Lowpass filter to make it sound like stone/wood rolling
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 300;

    this.rollingNode = this.ctx.createBufferSource();
    this.rollingNode.buffer = buffer;
    this.rollingNode.loop = true;

    this.rollingNode.connect(filter);
    filter.connect(this.rollingGain);
    this.rollingGain.connect(this.ctx.destination);

    this.rollingNode.start();
    this.initialized = true;
  }

  resume() {
    if (this.ctx?.state === 'suspended') {
      this.ctx.resume();
    }
  }

  // Called every frame with total velocity of all marbles
  updateRolling(totalSpeed: number) {
    if (!this.ctx || !this.rollingGain) return;

    // Smooth transition
    const targetGain = Math.min(totalSpeed * 0.005, 0.4);
    const currentGain = this.rollingGain.gain.value;
    this.rollingGain.gain.value = currentGain + (targetGain - currentGain) * 0.1;
  }

  playBump(intensity: number) {
    if (!this.ctx) return;

    // Throttle bumps to avoid audio glitching on piles
    const now = this.ctx.currentTime;
    if (now - this.lastBumpTime < 0.05) return; 
    this.lastBumpTime = now;

    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();

    osc.type = 'triangle';

    // Pitch varies with intensity (harder = higher) + random jitter
    const baseFreq = 100 + (intensity * 20);
    osc.frequency.setValueAtTime(baseFreq + Math.random() * 50, now);
    osc.frequency.exponentialRampToValueAtTime(50, now + 0.1);

    // Volume envelope
    const vol = Math.min(intensity * 0.1, 0.8);
    gain.gain.setValueAtTime(vol, now);
    gain.gain.exponentialRampToValueAtTime(0.01, now + 0.1);

    osc.connect(gain);
    gain.connect(this.ctx.destination);

    osc.start(now);
    osc.stop(now + 0.15);
  }

  playPinHit(intensity: number) {
    if (!this.ctx) return;
    const now = this.ctx.currentTime;

    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();

    osc.type = 'sine';
    osc.frequency.setValueAtTime(800 + Math.random() * 200, now); // Ping sound

    const vol = Math.min(intensity * 0.05, 0.5);
    gain.gain.setValueAtTime(vol, now);
    gain.gain.exponentialRampToValueAtTime(0.01, now + 0.2);

    osc.connect(gain);
    gain.connect(this.ctx.destination);

    osc.start(now);
    osc.stop(now + 0.2);
  }

  playFinish() {
    if (!this.ctx) return;
    const now = this.ctx.currentTime;

    // Major Chord Arpeggio
    [523.25, 659.25, 783.99, 1046.50].forEach((freq, i) => {
      const osc = this.ctx!.createOscillator();
      const gain = this.ctx!.createGain();

      osc.type = 'square';
      osc.frequency.value = freq;

      const time = now + (i * 0.05);
      gain.gain.setValueAtTime(0, time);
      gain.gain.linearRampToValueAtTime(0.1, time + 0.02);
      gain.gain.exponentialRampToValueAtTime(0.001, time + 0.4);

      osc.connect(gain);
      gain.connect(this.ctx!.destination);
      osc.start(time);
      osc.stop(time + 0.5);
    });
  }

  playEliminated() {
    if (!this.ctx) return;
    const now = this.ctx.currentTime;

    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();

    osc.type = 'sawtooth';
    osc.frequency.setValueAtTime(150, now);
    osc.frequency.linearRampToValueAtTime(50, now + 0.5);

    gain.gain.setValueAtTime(0.3, now);
    gain.gain.linearRampToValueAtTime(0, now + 0.5);

    osc.connect(gain);
    gain.connect(this.ctx.destination);

    osc.start(now);
    osc.stop(now + 0.5);
  }
}

export const audio = new AudioService();

import React, { useRef, useEffect } from 'react';
import { Marble, PhysicsConfig, LineSegment, CircleObstacle, DynamicObstacle } from '../types';
import { audio } from '../services/audioService';

interface RaceEngineProps {
  activeMarbles: Marble[];
  config: PhysicsConfig;
  onRaceFinish: (results: Marble[]) => void;
  betMarbleId: number | null;
}

const RaceEngine: React.FC<RaceEngineProps> = ({ activeMarbles, config, onRaceFinish, betMarbleId }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();

  // Physics State (Mutable refs for performance)
  const marblesRef = useRef<Marble[]>([]);
  const linesRef = useRef<LineSegment[]>([]);
  const pinsRef = useRef<CircleObstacle[]>([]);
  const dynamicRef = useRef<DynamicObstacle[]>([]);

  const cameraY = useRef(0);
  const raceFinished = useRef(false);
  const finishLineY = useRef(0);
  const startTime = useRef(0);
  const timeRef = useRef(0);

  // Constants
  const COURSE_WIDTH = 600;
  const BALL_RADIUS = 12;

  // --- Level Generation ---
  const generateLevel = () => {
    const lines: LineSegment[] = [];
    const pins: CircleObstacle[] = [];
    const dynamics: DynamicObstacle[] = [];

    // Config
    const segments = 6 + Math.floor(Math.random() * 3);
    const segmentHeight = 450;
    let currentY = 0;

    // 1. Start Funnel
    lines.push({ x1: 0, y1: 0, x2: COURSE_WIDTH * 0.4, y2: 150, type: 'wall' });
    lines.push({ x1: COURSE_WIDTH, y1: 0, x2: COURSE_WIDTH * 0.6, y2: 150, type: 'wall' });
    lines.push({ x1: COURSE_WIDTH * 0.4, y1: 150, x2: COURSE_WIDTH * 0.4, y2: 180, type: 'wall' });
    lines.push({ x1: COURSE_WIDTH * 0.6, y1: 150, x2: COURSE_WIDTH * 0.6, y2: 180, type: 'wall' });

    currentY = 220;

    // 2. Procedural Segments
    for (let i = 0; i < segments; i++) {
      const type = Math.random();

      // Outer Walls
      lines.push({ x1: 0, y1: currentY - 50, x2: 0, y2: currentY + segmentHeight, type: 'wall' });
      lines.push({ x1: COURSE_WIDTH, y1: currentY - 50, x2: COURSE_WIDTH, y2: currentY + segmentHeight, type: 'wall' });

      if (type < 0.25) {
        // --- PROPELLERS (Spinners) ---
        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 100, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 100, type: 'floor' });

        dynamics.push({
          id: `spin_${i}_1`,
          type: 'spinner',
          x: COURSE_WIDTH * 0.35,
          y: currentY + 250,
          width: 140,
          angle: 0,
          speed: 0.1,
        });
        dynamics.push({
          id: `spin_${i}_2`,
          type: 'spinner',
          x: COURSE_WIDTH * 0.65,
          y: currentY + 350,
          width: 140,
          angle: Math.PI / 2,
          speed: -0.1,
        });

      } else if (type < 0.5) {
        // --- MOVING ELEVATORS (Vertical or Horizontal) ---
        const isVertical = Math.random() > 0.5;

        // Feeders
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.2, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.8, y2: currentY + 150, type: 'floor' });

        if (isVertical) {
           // Vertical Elevator Platform
           dynamics.push({
             id: `slide_v_${i}`,
             type: 'slider_v',
             x: COURSE_WIDTH / 2,
             y: currentY + 200,
             width: 200,
             angle: 0,
             speed: 1, // freq
             range: 100,
             initialX: COURSE_WIDTH / 2,
             initialY: currentY + 250
           });
        } else {
           // Horizontal Slider
           dynamics.push({
            id: `slide_h_${i}`,
            type: 'slider_h',
            x: COURSE_WIDTH / 2,
            y: currentY + 250,
            width: 250,
            angle: 0,
            speed: 2,
            range: 150,
            initialX: COURSE_WIDTH / 2,
            initialY: currentY + 250
          });
        }

      } else if (type < 0.75) {
        // --- CLASSIC SLALOM ---
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.6, y2: currentY + 180, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 250, x2: COURSE_WIDTH * 0.4, y2: currentY + 380, type: 'floor' });
        pins.push({ x: COURSE_WIDTH * 0.8, y: currentY + 200, radius: 15, type: 'bumper' });
        pins.push({ x: COURSE_WIDTH * 0.2, y: currentY + 400, radius: 15, type: 'bumper' });

      } else {
         // --- MIXER ---
        lines.push({ x1: COURSE_WIDTH/2, y1: currentY + 50, x2: COURSE_WIDTH * 0.3, y2: currentY + 120, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH/2, y1: currentY + 50, x2: COURSE_WIDTH * 0.7, y2: currentY + 120, type: 'wall' });
        lines.push({ x1: 0, y1: currentY + 250, x2: COURSE_WIDTH * 0.35, y2: currentY + 350, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 250, x2: COURSE_WIDTH * 0.65, y2: currentY + 350, type: 'floor' });
        pins.push({ x: COURSE_WIDTH/2, y: currentY + 400, radius: 25, type: 'bumper' });
      }

      currentY += segmentHeight;
    }

    // 3. Finish Area
    lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 200, type: 'floor' });
    lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 200, type: 'floor' });

    finishLineY.current = currentY + 250;

    linesRef.current = lines;
    pinsRef.current = pins;
    dynamicRef.current = dynamics;
  };

  // --- Physics Logic ---
  const update = () => {
    if (raceFinished.current) {
        audio.updateRolling(0); // Stop rolling sound
        return;
    }

    const STEPS = 4;
    const dt = 1 / STEPS;
    timeRef.current += 1;

    const marbles = marblesRef.current;
    const dynamicObjs = dynamicRef.current;

    let totalSpeed = 0;

    // Update Dynamics
    const dynamicLines: LineSegment[] = [];
    dynamicObjs.forEach(obj => {
      if (obj.type === 'spinner') {
        obj.angle += obj.speed;
      } else if (obj.type === 'slider_h') {
        obj.x = obj.initialX! + Math.sin(timeRef.current * 0.02) * (obj.range || 100);
      } else if (obj.type === 'slider_v') {
        obj.y = obj.initialY! + Math.sin(timeRef.current * 0.015) * (obj.range || 80);
      }

      const halfW = obj.width / 2;
      const dx = Math.cos(obj.angle) * halfW;
      const dy = Math.sin(obj.angle) * halfW;

      dynamicLines.push({
        x1: obj.x - dx, y1: obj.y - dy,
        x2: obj.x + dx, y2: obj.y + dy,
        type: obj.type === 'spinner' ? 'bouncer' : 'floor'
      });
    });

    for (let step = 0; step < STEPS; step++) {
      for (let i = 0; i < marbles.length; i++) {
        const m = marbles[i];
        if (m.finished) continue;

        // 1. Gravity & Movement
        m.vy += config.gravity * dt;
        m.x += m.vx * dt;
        m.y += m.vy * dt;

        m.angle += m.omega * dt;
        m.omega *= 0.999; 

        m.vx *= Math.pow(config.friction, dt);
        m.vy *= Math.pow(config.friction, dt);

        // Anti-stuck
        if (m.vx*m.vx + m.vy*m.vy < 0.2) {
             m.vx += (Math.random() - 0.5); 
             m.vy += 0.5; 
        }

        // 2. Collisions
        for (const line of linesRef.current) checkLineCollision(m, line);
        for (const dLine of dynamicLines) checkLineCollision(m, dLine, true);
        for (const pin of pinsRef.current) checkPinCollision(m, pin);

        for (let j = i + 1; j < marbles.length; j++) {
           if (!marbles[j].finished) checkMarbleCollision(m, marbles[j]);
        }

        // 3. Finish Line
        if (m.y > finishLineY.current) {
          m.finished = true;
          m.finishTime = Date.now() - startTime.current;
          const finishedSoFar = marbles.filter(b => b.finished).length;
          m.rank = finishedSoFar;

          audio.playFinish(); // Play sound per marble finish? Maybe too noisy.
          // Let's only play for the first few or just distinct sounds. 
          // Actually, playFinish is a nice chord, maybe just once for winner? 
          // Re-using pinHit for generic finish to avoid spamming the chord.
          audio.playPinHit(10);
        }

        // Sum speed for audio
        if (!m.finished) {
            totalSpeed += Math.sqrt(m.vx*m.vx + m.vy*m.vy + m.omega*m.radius*m.omega*m.radius);
        }
      }
    }

    // Update Rolling Sound
    audio.updateRolling(totalSpeed);

    // Camera
    const activeMarblesList = marbles.filter(m => !m.finished);
    if (activeMarblesList.length > 0) {
      activeMarblesList.sort((a, b) => b.y - a.y);
      const leaders = activeMarblesList.slice(0, 3); 
      const avgY = leaders.reduce((a, b) => a + b.y, 0) / leaders.length;
      cameraY.current += (avgY - cameraY.current - 300) * 0.08;
    } else {
      if (!raceFinished.current) {
        raceFinished.current = true;
        const sorted = [...marbles].sort((a, b) => a.rank - b.rank);
        // Play big fanfare
        audio.playFinish(); 
        setTimeout(() => onRaceFinish(sorted), 1000);
      }
    }
  };

  const resolveCollisionPhysics = (ball: Marble, nx: number, ny: number, isBouncy: boolean) => {
    const vDotN = ball.vx * nx + ball.vy * ny;
    if (vDotN > 0) return; 

    // Sound Trigger
    const intensity = Math.abs(vDotN);
    if (intensity > 1.0) {
        audio.playBump(intensity);
    }

    const restitution = isBouncy ? 1.5 : config.restitution;
    const jN = -(1 + restitution) * vDotN;
    ball.vx += jN * nx;
    ball.vy += jN * ny;

    const tx = -ny;
    const ty = nx;
    const vDotT = ball.vx * tx + ball.vy * ty;
    const vSurf = vDotT + ball.omega * ball.radius;

    const mass = 1.0;
    const jT_ideal = -vSurf / (3.5 / mass);

    const mu = 0.5;
    const maxJt = mu * Math.abs(jN);

    let jT = jT_ideal;
    if (Math.abs(jT) > maxJt) {
       jT = Math.sign(jT) * maxJt;
    }

    ball.vx += jT * tx;
    ball.vy += jT * ty;
    ball.omega += (2.5 * jT) / (mass * ball.radius);
  };

  const checkLineCollision = (ball: Marble, line: LineSegment, isDynamic = false) => {
    const dx = line.x2 - line.x1;
    const dy = line.y2 - line.y1;
    const lenSq = dx*dx + dy*dy;
    const t = Math.max(0, Math.min(1, ((ball.x - line.x1) * dx + (ball.y - line.y1) * dy) / lenSq));
    const closeX = line.x1 + t * dx;
    const closeY = line.y1 + t * dy;

    const distX = ball.x - closeX;
    const distY = ball.y - closeY;
    const distSq = distX*distX + distY*distY;

    if (distSq < ball.radius * ball.radius) {
      const dist = Math.sqrt(distSq);
      const nx = distX / dist;
      const ny = distY / dist;

      const overlap = ball.radius - dist;
      ball.x += nx * overlap;
      ball.y += ny * overlap;

      const isBouncy = isDynamic && line.type === 'bouncer';
      resolveCollisionPhysics(ball, nx, ny, isBouncy);

      if (isDynamic) {
        ball.vx += (Math.random() - 0.5) * 2;
        ball.vy += (Math.random() - 0.5) * 2;
      }
    }
  };

  const checkPinCollision = (ball: Marble, pin: CircleObstacle) => {
    const dx = ball.x - pin.x;
    const dy = ball.y - pin.y;
    const distSq = dx*dx + dy*dy;
    const minDist = ball.radius + pin.radius;

    if (distSq < minDist * minDist) {
      const dist = Math.sqrt(distSq);
      const nx = dx / dist;
      const ny = dy / dist;

      const overlap = minDist - dist;
      ball.x += nx * overlap;
      ball.y += ny * overlap;

      const isBumper = pin.type === 'bumper';

      // Sound for pins
      const intensity = Math.sqrt(ball.vx*ball.vx + ball.vy*ball.vy);
      if (intensity > 1) {
          audio.playPinHit(intensity);
      }

      resolveCollisionPhysics(ball, nx, ny, isBumper);
    }
  };

  const checkMarbleCollision = (m1: Marble, m2: Marble) => {
    const dx = m2.x - m1.x;
    const dy = m2.y - m1.y;
    const distSq = dx*dx + dy*dy;
    const minDist = m1.radius + m2.radius;

    if (distSq < minDist * minDist) {
      const dist = Math.sqrt(distSq);
      const nx = dx / dist;
      const ny = dy / dist;
      const overlap = (minDist - dist) * 0.5;

      m1.x -= nx * overlap;
      m1.y -= ny * overlap;
      m2.x += nx * overlap;
      m2.y += ny * overlap;

      const dvx = m1.vx - m2.vx;
      const dvy = m1.vy - m2.vy;
      const dot = dvx * nx + dvy * ny;

      if (dot > 0) {
         // Marble clack sound
         if (dot > 2) audio.playPinHit(dot * 0.5);

         const impulse = dot * 0.9; 
         m1.vx -= impulse * nx;
         m1.vy -= impulse * ny;
         m2.vx += impulse * nx;
         m2.vy += impulse * ny;
      }
    }
  };

  // --- Initialization ---
  useEffect(() => {
    generateLevel();
    raceFinished.current = false;
    startTime.current = Date.now();
    cameraY.current = 0;
    timeRef.current = 0;

    marblesRef.current = activeMarbles.map((m, index) => ({
      ...m,
      x: COURSE_WIDTH * 0.4 + (Math.random() * COURSE_WIDTH * 0.2),
      y: -50 - (index * 40),
      vx: (Math.random() - 0.5) * 5,
      vy: 0,
      angle: 0,
      omega: 0,
      finished: false,
      rank: 0
    }));

    // Ensure audio starts if active
    audio.resume();

  }, [activeMarbles]); 

  // --- Render Loop ---
  const draw = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const { offsetWidth, offsetHeight } = canvas;
    if (canvas.width !== offsetWidth || canvas.height !== offsetHeight) {
      canvas.width = offsetWidth;
      canvas.height = offsetHeight;
    }

    ctx.fillStyle = '#1f2937';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.save();
    const scale = canvas.width / COURSE_WIDTH;
    ctx.scale(scale, scale);
    const camY = Math.max(0, Math.min(cameraY.current, finishLineY.current - canvas.height/scale + 100));
    ctx.translate(0, -camY);

    // Draw Static Lines
    ctx.lineWidth = 4;
    ctx.lineCap = 'round';
    linesRef.current.forEach(l => {
      ctx.strokeStyle = l.type === 'wall' ? '#4b5563' : '#60a5fa';
      if (l.type === 'wall') ctx.lineWidth = 6;
      else ctx.lineWidth = 4;
      ctx.beginPath();
      ctx.moveTo(l.x1, l.y1);
      ctx.lineTo(l.x2, l.y2);
      ctx.stroke();
    });

    // Draw Dynamic Obstacles
    dynamicRef.current.forEach(obj => {
       ctx.save();
       ctx.translate(obj.x, obj.y);
       if (obj.type === 'spinner') ctx.rotate(obj.angle);

       ctx.strokeStyle = obj.type === 'spinner' ? '#ef4444' : '#f59e0b';
       ctx.lineWidth = 8;
       ctx.beginPath();
       ctx.moveTo(-obj.width/2, 0);
       ctx.lineTo(obj.width/2, 0);
       ctx.stroke();

       if (obj.type === 'spinner') {
         ctx.beginPath();
         ctx.arc(0, 0, 5, 0, Math.PI * 2);
         ctx.fillStyle = '#fff';
         ctx.fill();
       }
       ctx.restore();
    });

    // Draw Pins
    pinsRef.current.forEach(p => {
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.radius, 0, Math.PI * 2);
      ctx.fillStyle = p.type === 'bumper' ? '#f472b6' : '#9ca3af';
      ctx.fill();
    });

    // Draw Finish Line
    ctx.fillStyle = '#10b981';
    ctx.fillRect(0, finishLineY.current, COURSE_WIDTH, 10);
    for(let i=0; i<20; i++) {
        ctx.fillStyle = i%2===0 ? '#fff' : '#000';
        ctx.fillRect(i * (COURSE_WIDTH/20), finishLineY.current, COURSE_WIDTH/20, 10);
    }

    // Draw Marbles
    marblesRef.current.forEach(m => {
      ctx.save();
      ctx.translate(m.x, m.y);
      ctx.rotate(m.angle); 

      ctx.beginPath();
      ctx.arc(0, 0, m.radius, 0, Math.PI * 2);
      ctx.fillStyle = m.color;
      ctx.shadowColor = 'rgba(0,0,0,0.5)';
      ctx.shadowBlur = 5;
      ctx.fill();
      ctx.shadowBlur = 0;

      ctx.beginPath();
      ctx.moveTo(-m.radius, 0);
      ctx.lineTo(m.radius, 0);
      ctx.strokeStyle = 'rgba(255,255,255,0.5)';
      ctx.lineWidth = 3;
      ctx.stroke();

      ctx.beginPath();
      ctx.moveTo(0, -m.radius);
      ctx.lineTo(0, m.radius);
      ctx.strokeStyle = 'rgba(0,0,0,0.3)';
      ctx.lineWidth = 2;
      ctx.stroke();

      ctx.beginPath();
      ctx.arc(-4, -4, 3, 0, Math.PI * 2);
      ctx.fillStyle = 'rgba(255,255,255,0.7)';
      ctx.fill();

      ctx.restore(); 

      if (m.id === betMarbleId) {
        ctx.strokeStyle = '#fbbf24';
        ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.arc(m.x, m.y, m.radius + 5, 0, Math.PI * 2);
        ctx.stroke();
      }

      if (!m.finished) {
        ctx.fillStyle = '#fff';
        ctx.font = '10px Arial';
        ctx.textAlign = 'center';
        ctx.fillText(m.name, m.x, m.y - 18);
      }
    });

    ctx.restore();
  };

  useEffect(() => {
    const loop = () => {
      update();
      draw();
      requestRef.current = requestAnimationFrame(loop);
    };
    requestRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(requestRef.current!);
  });

  return (
    <canvas ref={canvasRef} className="w-full h-full block" />
  );
};

