import React, { useState, useEffect } from 'react';
import RaceEngine from './components/RaceEngine';
import { Marble, GameState, PhysicsConfig } from './types';
import { Trophy, Settings, Skull, Play, Timer, ArrowDown } from 'lucide-react';
import { audio } from './services/audioService';

const NAMES = [
  "Thunder", "Lightning", "Comet", "Shadow", 
  "Blaze", "Frost", "Viper", "Titan", "Nova", "Ghost"
];

const COLORS = [
  "#ef4444", "#3b82f6", "#10b981", "#f59e0b",
  "#8b5cf6", "#ec4899", "#6366f1", "#14b8a6", "#f97316", "#64748b"
];

const INITIAL_MARBLES: Marble[] = NAMES.map((name, i) => ({
  id: i,
  name,
  color: COLORS[i],
  x: 0, y: 0, vx: 0, vy: 0, radius: 12,
  angle: 0,
  omega: 0,
  finished: false, finishTime: 0, rank: 0
}));

export default function App() {
  const [gameState, setGameState] = useState<GameState>({
    phase: 'betting',
    round: 1,
    marbles: INITIAL_MARBLES,
    activeMarbleIds: INITIAL_MARBLES.map(m => m.id),
    betMarbleId: null,
    lastEliminatedId: null,
  });

  const [physicsConfig, setPhysicsConfig] = useState<PhysicsConfig>({
    gravity: 0.25,
    restitution: 0.6,
    friction: 0.99
  });

  const activeMarblesList = gameState.marbles.filter(m => gameState.activeMarbleIds.includes(m.id));

  // --- Handlers ---

  const handleStartTournament = () => {
    if (gameState.betMarbleId === null) return;

    // Initialize Audio Engine on user interaction
    audio.init();
    audio.resume();

    setGameState(prev => ({ ...prev, phase: 'racing' }));
  };

  const handleRaceFinish = (results: Marble[]) => {
    const loser = results[results.length - 1];

    // Play sound for result
    audio.playEliminated();

    setGameState(prev => ({
      ...prev,
      phase: 'round_result',
      lastEliminatedId: loser.id
    }));
  };

  const handleNextRound = () => {
    const nextActiveIds = gameState.activeMarbleIds.filter(id => id !== gameState.lastEliminatedId);

    if (nextActiveIds.length === 1) {
      audio.playFinish(); // Champion fanfare
      setGameState(prev => ({
        ...prev,
        activeMarbleIds: nextActiveIds,
        phase: 'champion'
      }));
    } else {
      setGameState(prev => ({
        ...prev,
        activeMarbleIds: nextActiveIds,
        phase: 'racing',
        round: prev.round + 1,
        lastEliminatedId: null
      }));
    }
  };

  const resetGame = () => {
    setGameState({
      phase: 'betting',
      round: 1,
      marbles: INITIAL_MARBLES,
      activeMarbleIds: INITIAL_MARBLES.map(m => m.id),
      betMarbleId: null,
      lastEliminatedId: null,
    });
  };

  // --- Render Components ---

  // 1. Betting / Config Screen
  if (gameState.phase === 'betting') {
    return (
      <div className="min-h-screen bg-gray-900 flex flex-col items-center justify-center p-4 text-white">
        <h1 className="text-5xl md:text-7xl mb-2 text-transparent bg-clip-text bg-gradient-to-r from-yellow-400 to-red-500 brand-font tracking-widest text-center">
          MARBLE ROYALE
        </h1>
        <p className="text-gray-400 mb-8 font-mono text-center max-w-lg">
          10 Bolinhas entram. 1 Sai campeã. A última de cada corrida é eliminada.
        </p>

        <div className="bg-gray-800 p-6 rounded-xl border border-gray-700 w-full max-w-2xl shadow-2xl">
          <div className="mb-6">
            <h2 className="text-xl font-bold mb-4 flex items-center text-yellow-400">
              <Trophy className="mr-2" /> Escolha sua Campeã
            </h2>
            <div className="grid grid-cols-2 md:grid-cols-5 gap-3">
              {gameState.marbles.map(m => (
                <button
                  key={m.id}
                  onClick={() => setGameState(prev => ({ ...prev, betMarbleId: m.id }))}
                  className={`p-3 rounded-lg flex flex-col items-center transition-all ${
                    gameState.betMarbleId === m.id 
                      ? 'bg-yellow-500/20 border-2 border-yellow-400 scale-105' 
                      : 'bg-gray-700 border border-transparent hover:bg-gray-600'
                  }`}
                >
                  <div className="w-8 h-8 rounded-full mb-2 shadow-lg" style={{ backgroundColor: m.color }}></div>
                  <span className="text-xs font-bold font-mono">{m.name}</span>
                </button>
              ))}
            </div>
          </div>

          <div className="mb-8 border-t border-gray-700 pt-6">
            <h2 className="text-xl font-bold mb-4 flex items-center text-blue-400">
              <Settings className="mr-2" /> Configuração da Física
            </h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className="text-xs text-gray-400 block mb-1">Gravidade ({(physicsConfig.gravity * 100).toFixed(0)}%)</label>
                <input 
                  type="range" min="0.1" max="0.8" step="0.05"
                  value={physicsConfig.gravity}
                  onChange={(e) => setPhysicsConfig(prev => ({...prev, gravity: parseFloat(e.target.value)}))}
                  className="w-full accent-blue-500"
                />
              </div>
              <div>
                <label className="text-xs text-gray-400 block mb-1">Elasticidade (Quique) ({(physicsConfig.restitution * 100).toFixed(0)}%)</label>
                <input 
                  type="range" min="0.1" max="0.9" step="0.1"
                  value={physicsConfig.restitution}
                  onChange={(e) => setPhysicsConfig(prev => ({...prev, restitution: parseFloat(e.target.value)}))}
                  className="w-full accent-blue-500"
                />
              </div>
            </div>
          </div>

          <button 
            disabled={gameState.betMarbleId === null}
            onClick={handleStartTournament}
            className={`w-full py-4 rounded-lg font-black text-xl tracking-widest transition-all ${
              gameState.betMarbleId !== null
                ? 'bg-gradient-to-r from-green-500 to-emerald-600 hover:from-green-400 hover:to-emerald-500 text-white shadow-lg transform hover:-translate-y-1'
                : 'bg-gray-700 text-gray-500 cursor-not-allowed'
            }`}
          >
            INICIAR TORNEIO
          </button>
        </div>
      </div>
    );
  }

  // 2. Champion Screen
  if (gameState.phase === 'champion') {
    const championId = gameState.activeMarbleIds[0];
    const champion = gameState.marbles.find(m => m.id === championId)!;
    const playerWon = gameState.betMarbleId === championId;

    return (
      <div className="min-h-screen bg-black flex flex-col items-center justify-center p-6 text-center animate-fadeIn">
        <div className="relative mb-8">
           <div className="absolute inset-0 bg-yellow-500 blur-3xl opacity-20 animate-pulse"></div>
           <Trophy className="w-32 h-32 text-yellow-400 relative z-10 mx-auto mb-4" />
           <div className="w-24 h-24 rounded-full mx-auto relative z-10 shadow-[0_0_50px_rgba(255,255,255,0.5)] border-4 border-white" style={{ backgroundColor: champion.color }}></div>
        </div>

        <h1 className="text-6xl font-black text-white mb-2 brand-font">{champion.name}</h1>
        <p className="text-2xl text-yellow-500 font-mono mb-8">CAMPEÃ DO TORNEIO</p>

        <div className={`p-6 rounded-xl border-2 mb-8 max-w-md w-full ${playerWon ? 'bg-green-900/30 border-green-500' : 'bg-red-900/30 border-red-500'}`}>
          <h3 className="text-xl font-bold mb-2">{playerWon ? "PARABÉNS!" : "NÃO FOI DESSA VEZ"}</h3>
          <p className="text-gray-300">
            {playerWon 
              ? `Sua aposta em ${champion.name} estava certa!` 
              : `Você apostou em ${gameState.marbles.find(m => m.id === gameState.betMarbleId)?.name}. Tente novamente!`}
          </p>
        </div>

        <button 
          onClick={resetGame}
          className="px-8 py-3 bg-white text-black font-bold rounded-full hover:scale-105 transition-transform"
        >
          NOVO TORNEIO
        </button>
      </div>
    );
  }

  // 3. Racing / Round Result Screen (Game Loop)
  return (
    <div className="relative w-full h-screen bg-gray-900 overflow-hidden">

      {/* Race View */}
      <div className="absolute inset-0 z-0">
        <RaceEngine 
          activeMarbles={activeMarblesList}
          config={physicsConfig}
          onRaceFinish={handleRaceFinish}
          betMarbleId={gameState.betMarbleId}
        />
      </div>

      {/* Overlay UI */}
      <div className="absolute top-0 left-0 w-full p-4 flex justify-between items-start z-10 pointer-events-none">
         <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white">
           <div className="text-xs text-gray-400 font-bold uppercase">Rodada</div>
           <div className="text-2xl font-mono text-yellow-400">{gameState.round} <span className="text-sm text-gray-500">/ 9</span></div>
         </div>

         <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white text-right">
           <div className="text-xs text-gray-400 font-bold uppercase">Sobreviventes</div>
           <div className="text-2xl font-mono text-blue-400">{activeMarblesList.length}</div>
         </div>
      </div>

      {/* Round Result Modal */}
      {gameState.phase === 'round_result' && (
        <div className="absolute inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-gray-800 rounded-2xl p-8 max-w-sm w-full text-center border border-gray-700 shadow-2xl animate-in slide-in-from-bottom-10 fade-in duration-300">
            <h2 className="text-3xl font-bold text-white mb-6 brand-font">FIM DA RODADA {gameState.round}</h2>

            <div className="bg-red-900/20 border border-red-500/50 p-4 rounded-xl mb-6">
               <Skull className="w-8 h-8 text-red-500 mx-auto mb-2" />
               <div className="text-red-400 font-bold text-sm uppercase mb-1">Eliminada</div>
               {gameState.lastEliminatedId !== null && (
                 <div className="flex items-center justify-center space-x-2">
                    <div className="w-4 h-4 rounded-full" style={{ backgroundColor: gameState.marbles.find(m => m.id === gameState.lastEliminatedId)?.color }}></div>
                    <span className="text-xl text-white font-mono">
                      {gameState.marbles.find(m => m.id === gameState.lastEliminatedId)?.name}
                    </span>
                 </div>
               )}
            </div>

            {gameState.lastEliminatedId === gameState.betMarbleId && (
              <div className="text-red-400 text-sm font-bold mb-6">
                SUA APOSTA FOI ELIMINADA! 😱
              </div>
            )}

            <button 
              onClick={handleNextRound}
              className="w-full py-3 bg-blue-600 hover:bg-blue-500 text-white font-bold rounded-lg flex items-center justify-center space-x-2 transition-colors"
            >
              <Play className="w-5 h-5" />
              <span>PRÓXIMA RODADA</span>
            </button>
          </div>
        </div>
      )}

      {/* Bet Indicator (Bottom) */}
      {gameState.phase === 'racing' && (
        <div className="absolute bottom-6 left-1/2 transform -translate-x-1/2 bg-black/60 backdrop-blur px-6 py-2 rounded-full border border-yellow-500/30 text-white font-mono text-sm flex items-center space-x-2">
           <span className="text-gray-400">Aposta:</span>
           <div className="w-3 h-3 rounded-full" style={{ backgroundColor: gameState.marbles.find(m => m.id === gameState.betMarbleId)?.color }}></div>
           <span className="font-bold text-yellow-400">{gameState.marbles.find(m => m.id === gameState.betMarbleId)?.name}</span>
        </div>
      )}

    </div>
  );
}

export interface Marble {
  id: number;
  color: string;
  name: string;
  x: number;
  y: number;
  vx: number;
  vy: number;
  radius: number;
  angle: number; // Rotation angle in radians
  omega: number; // Angular velocity in radians/tick
  finished: boolean;
  finishTime: number;
  rank: number; // 0 if not finished
}

export interface LineSegment {
  x1: number;
  y1: number;
  x2: number;
  y2: number;
  type: 'wall' | 'floor' | 'bouncer';
}

export interface CircleObstacle {
  x: number;
  y: number;
  radius: number;
  type: 'pin' | 'bumper';
}

export interface DynamicObstacle {
  id: string;
  type: 'spinner' | 'slider_h' | 'slider_v' | 'fan';
  x: number;
  y: number;
  width: number; // Length of the line/blade, or width of fan source
  height?: number; // Range of the fan wind
  angle: number;
  speed: number;
  range?: number; // For sliders
  initialX?: number;
  initialY?: number;
  force?: number; // Wind strength
}

export interface PhysicsConfig {
  gravity: number;
  restitution: number; // Bounciness 0.1 to 0.9
  friction: number;
}

export interface GameState {
  phase: 'betting' | 'racing' | 'round_result' | 'champion';
  round: number; // Starts at 1
  marbles: Marble[]; // All marbles
  activeMarbleIds: number[]; // IDs of marbles still in tournament
  betMarbleId: number | null;
  lastEliminatedId: number | null;
}

import React, { useRef, useEffect } from 'react';
import { Marble, PhysicsConfig, LineSegment, CircleObstacle, DynamicObstacle } from '../types';
import { audio } from '../services/audioService';

interface RaceEngineProps {
  activeMarbles: Marble[];
  config: PhysicsConfig;
  onRaceFinish: (results: Marble[]) => void;
  betMarbleId: number | null;
}

const RaceEngine: React.FC<RaceEngineProps> = ({ activeMarbles, config, onRaceFinish, betMarbleId }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();

  // Physics State (Mutable refs for performance)
  const marblesRef = useRef<Marble[]>([]);
  const linesRef = useRef<LineSegment[]>([]);
  const pinsRef = useRef<CircleObstacle[]>([]);
  const dynamicRef = useRef<DynamicObstacle[]>([]);

  const cameraY = useRef(0);
  const raceFinished = useRef(false);
  const finishLineY = useRef(0);
  const startTime = useRef(0);
  const timeRef = useRef(0);

  // Constants
  const COURSE_WIDTH = 600;
  const BALL_RADIUS = 12;

  // --- Level Generation ---
  const generateLevel = () => {
    const lines: LineSegment[] = [];
    const pins: CircleObstacle[] = [];
    const dynamics: DynamicObstacle[] = [];

    // Config
    const segments = 6 + Math.floor(Math.random() * 3);
    const segmentHeight = 450;
    let currentY = 0;

    // 1. Start Funnel
    lines.push({ x1: 0, y1: 0, x2: COURSE_WIDTH * 0.4, y2: 150, type: 'wall' });
    lines.push({ x1: COURSE_WIDTH, y1: 0, x2: COURSE_WIDTH * 0.6, y2: 150, type: 'wall' });
    lines.push({ x1: COURSE_WIDTH * 0.4, y1: 150, x2: COURSE_WIDTH * 0.4, y2: 180, type: 'wall' });
    lines.push({ x1: COURSE_WIDTH * 0.6, y1: 150, x2: COURSE_WIDTH * 0.6, y2: 180, type: 'wall' });

    currentY = 220;

    // 2. Procedural Segments
    for (let i = 0; i < segments; i++) {
      const type = Math.random();

      // Outer Walls
      lines.push({ x1: 0, y1: currentY - 50, x2: 0, y2: currentY + segmentHeight, type: 'wall' });
      lines.push({ x1: COURSE_WIDTH, y1: currentY - 50, x2: COURSE_WIDTH, y2: currentY + segmentHeight, type: 'wall' });

      if (type < 0.2) {
        // --- PROPELLERS (Spinners) ---
        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 100, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 100, type: 'floor' });

        dynamics.push({
          id: `spin_${i}_1`,
          type: 'spinner',
          x: COURSE_WIDTH * 0.35,
          y: currentY + 250,
          width: 140,
          angle: 0,
          speed: 0.1,
        });
        dynamics.push({
          id: `spin_${i}_2`,
          type: 'spinner',
          x: COURSE_WIDTH * 0.65,
          y: currentY + 350,
          width: 140,
          angle: Math.PI / 2,
          speed: -0.1,
        });

      } else if (type < 0.4) {
        // --- MOVING ELEVATORS (Vertical or Horizontal) ---
        const isVertical = Math.random() > 0.5;

        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.2, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.8, y2: currentY + 150, type: 'floor' });

        if (isVertical) {
           dynamics.push({
             id: `slide_v_${i}`,
             type: 'slider_v',
             x: COURSE_WIDTH / 2,
             y: currentY + 200,
             width: 200,
             angle: 0,
             speed: 1, 
             range: 100,
             initialX: COURSE_WIDTH / 2,
             initialY: currentY + 250
           });
        } else {
           dynamics.push({
            id: `slide_h_${i}`,
            type: 'slider_h',
            x: COURSE_WIDTH / 2,
            y: currentY + 250,
            width: 250,
            angle: 0,
            speed: 2,
            range: 150,
            initialX: COURSE_WIDTH / 2,
            initialY: currentY + 250
          });
        }

      } else if (type < 0.6) {
        // --- WIND CANNONS (New Obstacle) ---
        // Side walls feeding into a central area with wind pushing sideways
        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 100, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 100, type: 'floor' });

        // Fan on the left pushing right
        dynamics.push({
          id: `fan_${i}_1`,
          type: 'fan',
          x: 20, // Near left wall
          y: currentY + 250,
          width: 40, // width of the fan base
          height: 300, // Range of the wind
          angle: 0, // 0 radians = pointing right
          speed: 0,
          force: 0.6
        });

        // Some pins to make it chaotic
        pins.push({ x: COURSE_WIDTH * 0.6, y: currentY + 250, radius: 20, type: 'bumper' });

      } else if (type < 0.8) {
        // --- CLASSIC SLALOM ---
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.6, y2: currentY + 180, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 250, x2: COURSE_WIDTH * 0.4, y2: currentY + 380, type: 'floor' });
        pins.push({ x: COURSE_WIDTH * 0.8, y: currentY + 200, radius: 15, type: 'bumper' });
        pins.push({ x: COURSE_WIDTH * 0.2, y: currentY + 400, radius: 15, type: 'bumper' });

      } else {
         // --- MIXER ---
        lines.push({ x1: COURSE_WIDTH/2, y1: currentY + 50, x2: COURSE_WIDTH * 0.3, y2: currentY + 120, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH/2, y1: currentY + 50, x2: COURSE_WIDTH * 0.7, y2: currentY + 120, type: 'wall' });
        lines.push({ x1: 0, y1: currentY + 250, x2: COURSE_WIDTH * 0.35, y2: currentY + 350, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 250, x2: COURSE_WIDTH * 0.65, y2: currentY + 350, type: 'floor' });
        pins.push({ x: COURSE_WIDTH/2, y: currentY + 400, radius: 25, type: 'bumper' });
      }

      currentY += segmentHeight;
    }

    // 3. Finish Area
    lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 200, type: 'floor' });
    lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 200, type: 'floor' });

    finishLineY.current = currentY + 250;

    linesRef.current = lines;
    pinsRef.current = pins;
    dynamicRef.current = dynamics;
  };

  // --- Physics Logic ---
  const update = () => {
    if (raceFinished.current) {
        audio.updateRolling(0); 
        return;
    }

    const STEPS = 4;
    const dt = 1 / STEPS;
    timeRef.current += 1;

    const marbles = marblesRef.current;
    const dynamicObjs = dynamicRef.current;

    let totalSpeed = 0;

    // Update Dynamics
    const dynamicLines: LineSegment[] = [];

    // Separate fans from collision objects
    const fans: DynamicObstacle[] = [];
    const solidDynamics: DynamicObstacle[] = [];

    dynamicObjs.forEach(obj => {
      if (obj.type === 'fan') {
        fans.push(obj);
        return;
      }
      solidDynamics.push(obj);

      if (obj.type === 'spinner') {
        obj.angle += obj.speed;
      } else if (obj.type === 'slider_h') {
        obj.x = obj.initialX! + Math.sin(timeRef.current * 0.02) * (obj.range || 100);
      } else if (obj.type === 'slider_v') {
        obj.y = obj.initialY! + Math.sin(timeRef.current * 0.015) * (obj.range || 80);
      }

      const halfW = obj.width / 2;
      const dx = Math.cos(obj.angle) * halfW;
      const dy = Math.sin(obj.angle) * halfW;

      dynamicLines.push({
        x1: obj.x - dx, y1: obj.y - dy,
        x2: obj.x + dx, y2: obj.y + dy,
        type: obj.type === 'spinner' ? 'bouncer' : 'floor'
      });
    });

    for (let step = 0; step < STEPS; step++) {
      for (let i = 0; i < marbles.length; i++) {
        const m = marbles[i];
        if (m.finished) continue;

        // 1. Gravity & Movement
        m.vy += config.gravity * dt;
        m.x += m.vx * dt;
        m.y += m.vy * dt;

        // Fan Physics
        for (const fan of fans) {
          // Transform marble to fan's local space to check bounding box
          // Translate
          const dx = m.x - fan.x;
          const dy = m.y - fan.y;
          // Rotate by -fanAngle
          const localX = dx * Math.cos(-fan.angle) - dy * Math.sin(-fan.angle);
          const localY = dx * Math.sin(-fan.angle) + dy * Math.cos(-fan.angle);

          const halfWidth = fan.width / 2; // base width
          const range = fan.height || 200;

          // Check if marble is in the "Wind Box"
          // Assuming fan blows along local X axis or specific direction? 
          // Usually angle defines direction. 
          // Let's define: Fan is at (0,0), width is perpendicular to airflow. Height is length of airflow.
          // Air flows in direction of Angle.
          // So in local space: Y should be between -halfWidth and +halfWidth.
          // X should be between 0 and Range.

          // Actually, let's align visuals:
          // Fan angle 0 = pointing Right.
          // Local X: Distance from fan face.
          // Local Y: Side-to-side offset.

          if (localX > 0 && localX < range && Math.abs(localY) < halfWidth) {
             // Inside wind zone!
             const force = fan.force || 0.5;
             const forceX = Math.cos(fan.angle) * force;
             const forceY = Math.sin(fan.angle) * force;

             m.vx += forceX * dt;
             m.vy += forceY * dt;
          }
        }

        m.angle += m.omega * dt;
        m.omega *= 0.999; 

        m.vx *= Math.pow(config.friction, dt);
        m.vy *= Math.pow(config.friction, dt);

        if (m.vx*m.vx + m.vy*m.vy < 0.2) {
             m.vx += (Math.random() - 0.5); 
             m.vy += 0.5; 
        }

        // 2. Collisions
        for (const line of linesRef.current) checkLineCollision(m, line);
        for (const dLine of dynamicLines) checkLineCollision(m, dLine, true);
        for (const pin of pinsRef.current) checkPinCollision(m, pin);

        for (let j = i + 1; j < marbles.length; j++) {
           if (!marbles[j].finished) checkMarbleCollision(m, marbles[j]);
        }

        // 3. Finish Line
        if (m.y > finishLineY.current) {
          m.finished = true;
          m.finishTime = Date.now() - startTime.current;
          const finishedSoFar = marbles.filter(b => b.finished).length;
          m.rank = finishedSoFar;
          audio.playPinHit(10);
        }

        if (!m.finished) {
            totalSpeed += Math.sqrt(m.vx*m.vx + m.vy*m.vy + m.omega*m.radius*m.omega*m.radius);
        }
      }
    }

    audio.updateRolling(totalSpeed);

    const activeMarblesList = marbles.filter(m => !m.finished);
    if (activeMarblesList.length > 0) {
      activeMarblesList.sort((a, b) => b.y - a.y);
      const leaders = activeMarblesList.slice(0, 3); 
      const avgY = leaders.reduce((a, b) => a + b.y, 0) / leaders.length;
      cameraY.current += (avgY - cameraY.current - 300) * 0.08;
    } else {
      if (!raceFinished.current) {
        raceFinished.current = true;
        const sorted = [...marbles].sort((a, b) => a.rank - b.rank);
        audio.playFinish(); 
        setTimeout(() => onRaceFinish(sorted), 1000);
      }
    }
  };

  const resolveCollisionPhysics = (ball: Marble, nx: number, ny: number, isBouncy: boolean) => {
    const vDotN = ball.vx * nx + ball.vy * ny;
    if (vDotN > 0) return; 

    const intensity = Math.abs(vDotN);
    if (intensity > 1.0) {
        audio.playBump(intensity);
    }

    const restitution = isBouncy ? 1.5 : config.restitution;
    const jN = -(1 + restitution) * vDotN;
    ball.vx += jN * nx;
    ball.vy += jN * ny;

    const tx = -ny;
    const ty = nx;
    const vDotT = ball.vx * tx + ball.vy * ty;
    const vSurf = vDotT + ball.omega * ball.radius;

    const mass = 1.0;
    const jT_ideal = -vSurf / (3.5 / mass);
    const mu = 0.5;
    const maxJt = mu * Math.abs(jN);

    let jT = jT_ideal;
    if (Math.abs(jT) > maxJt) {
       jT = Math.sign(jT) * maxJt;
    }

    ball.vx += jT * tx;
    ball.vy += jT * ty;
    ball.omega += (2.5 * jT) / (mass * ball.radius);
  };

  const checkLineCollision = (ball: Marble, line: LineSegment, isDynamic = false) => {
    const dx = line.x2 - line.x1;
    const dy = line.y2 - line.y1;
    const lenSq = dx*dx + dy*dy;
    const t = Math.max(0, Math.min(1, ((ball.x - line.x1) * dx + (ball.y - line.y1) * dy) / lenSq));
    const closeX = line.x1 + t * dx;
    const closeY = line.y1 + t * dy;

    const distX = ball.x - closeX;
    const distY = ball.y - closeY;
    const distSq = distX*distX + distY*distY;

    if (distSq < ball.radius * ball.radius) {
      const dist = Math.sqrt(distSq);
      const nx = distX / dist;
      const ny = distY / dist;

      const overlap = ball.radius - dist;
      ball.x += nx * overlap;
      ball.y += ny * overlap;

      const isBouncy = isDynamic && line.type === 'bouncer';
      resolveCollisionPhysics(ball, nx, ny, isBouncy);

      if (isDynamic) {
        ball.vx += (Math.random() - 0.5) * 2;
        ball.vy += (Math.random() - 0.5) * 2;
      }
    }
  };

  const checkPinCollision = (ball: Marble, pin: CircleObstacle) => {
    const dx = ball.x - pin.x;
    const dy = ball.y - pin.y;
    const distSq = dx*dx + dy*dy;
    const minDist = ball.radius + pin.radius;

    if (distSq < minDist * minDist) {
      const dist = Math.sqrt(distSq);
      const nx = dx / dist;
      const ny = dy / dist;

      const overlap = minDist - dist;
      ball.x += nx * overlap;
      ball.y += ny * overlap;

      const isBumper = pin.type === 'bumper';

      const intensity = Math.sqrt(ball.vx*ball.vx + ball.vy*ball.vy);
      if (intensity > 1) {
          audio.playPinHit(intensity);
      }

      resolveCollisionPhysics(ball, nx, ny, isBumper);
    }
  };

  const checkMarbleCollision = (m1: Marble, m2: Marble) => {
    const dx = m2.x - m1.x;
    const dy = m2.y - m1.y;
    const distSq = dx*dx + dy*dy;
    const minDist = m1.radius + m2.radius;

    if (distSq < minDist * minDist) {
      const dist = Math.sqrt(distSq);
      const nx = dx / dist;
      const ny = dy / dist;
      const overlap = (minDist - dist) * 0.5;

      m1.x -= nx * overlap;
      m1.y -= ny * overlap;
      m2.x += nx * overlap;
      m2.y += ny * overlap;

      const dvx = m1.vx - m2.vx;
      const dvy = m1.vy - m2.vy;
      const dot = dvx * nx + dvy * ny;

      if (dot > 0) {
         if (dot > 2) audio.playPinHit(dot * 0.5);

         const impulse = dot * 0.9; 
         m1.vx -= impulse * nx;
         m1.vy -= impulse * ny;
         m2.vx += impulse * nx;
         m2.vy += impulse * ny;
      }
    }
  };

  // --- Initialization ---
  useEffect(() => {
    generateLevel();
    raceFinished.current = false;
    startTime.current = Date.now();
    cameraY.current = 0;
    timeRef.current = 0;

    marblesRef.current = activeMarbles.map((m, index) => ({
      ...m,
      x: COURSE_WIDTH * 0.4 + (Math.random() * COURSE_WIDTH * 0.2),
      y: -50 - (index * 40),
      vx: (Math.random() - 0.5) * 5,
      vy: 0,
      angle: 0,
      omega: 0,
      finished: false,
      rank: 0
    }));

    audio.resume();

  }, [activeMarbles]); 

  // --- Render Loop ---
  const draw = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const { offsetWidth, offsetHeight } = canvas;
    if (canvas.width !== offsetWidth || canvas.height !== offsetHeight) {
      canvas.width = offsetWidth;
      canvas.height = offsetHeight;
    }

    ctx.fillStyle = '#1f2937';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.save();
    const scale = canvas.width / COURSE_WIDTH;
    ctx.scale(scale, scale);
    const camY = Math.max(0, Math.min(cameraY.current, finishLineY.current - canvas.height/scale + 100));
    ctx.translate(0, -camY);

    // Draw Static Lines
    ctx.lineWidth = 4;
    ctx.lineCap = 'round';
    linesRef.current.forEach(l => {
      ctx.strokeStyle = l.type === 'wall' ? '#4b5563' : '#60a5fa';
      if (l.type === 'wall') ctx.lineWidth = 6;
      else ctx.lineWidth = 4;
      ctx.beginPath();
      ctx.moveTo(l.x1, l.y1);
      ctx.lineTo(l.x2, l.y2);
      ctx.stroke();
    });

    // Draw Dynamic Obstacles
    dynamicRef.current.forEach(obj => {
       ctx.save();
       ctx.translate(obj.x, obj.y);
       ctx.rotate(obj.angle);

       if (obj.type === 'fan') {
          // Draw Fan Base
          ctx.fillStyle = '#64748b';
          ctx.fillRect(-10, -obj.width/2, 20, obj.width);

          // Draw Air Flow
          const range = obj.height || 200;
          const gradient = ctx.createLinearGradient(0, 0, range, 0);
          gradient.addColorStop(0, 'rgba(255, 255, 255, 0.4)');
          gradient.addColorStop(1, 'rgba(255, 255, 255, 0)');

          ctx.fillStyle = gradient;
          ctx.fillRect(0, -obj.width/2, range, obj.width);

          // Animated Lines
          ctx.strokeStyle = 'rgba(255, 255, 255, 0.5)';
          ctx.lineWidth = 1;
          const offset = (timeRef.current * 5) % 50;
          for(let i=0; i<3; i++) {
             const yPos = -obj.width/2 + (obj.width/4) * (i+1);
             ctx.beginPath();
             ctx.moveTo(10 + offset, yPos);
             ctx.lineTo(range - 20, yPos);
             ctx.stroke();
          }

       } else {
         // Sliders & Spinners
         ctx.strokeStyle = obj.type === 'spinner' ? '#ef4444' : '#f59e0b';
         ctx.lineWidth = 8;
         ctx.beginPath();
         ctx.moveTo(-obj.width/2, 0);
         ctx.lineTo(obj.width/2, 0);
         ctx.stroke();

         if (obj.type === 'spinner') {
           ctx.beginPath();
           ctx.arc(0, 0, 5, 0, Math.PI * 2);
           ctx.fillStyle = '#fff';
           ctx.fill();
         }
       }
       ctx.restore();
    });

    // Draw Pins
    pinsRef.current.forEach(p => {
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.radius, 0, Math.PI * 2);
      ctx.fillStyle = p.type === 'bumper' ? '#f472b6' : '#9ca3af';
      ctx.fill();
    });

    // Draw Finish Line
    ctx.fillStyle = '#10b981';
    ctx.fillRect(0, finishLineY.current, COURSE_WIDTH, 10);
    for(let i=0; i<20; i++) {
        ctx.fillStyle = i%2===0 ? '#fff' : '#000';
        ctx.fillRect(i * (COURSE_WIDTH/20), finishLineY.current, COURSE_WIDTH/20, 10);
    }

    // Draw Marbles
    marblesRef.current.forEach(m => {
      ctx.save();
      ctx.translate(m.x, m.y);
      ctx.rotate(m.angle); 

      ctx.beginPath();
      ctx.arc(0, 0, m.radius, 0, Math.PI * 2);
      ctx.fillStyle = m.color;
      ctx.shadowColor = 'rgba(0,0,0,0.5)';
      ctx.shadowBlur = 5;
      ctx.fill();
      ctx.shadowBlur = 0;

      ctx.beginPath();
      ctx.moveTo(-m.radius, 0);
      ctx.lineTo(m.radius, 0);
      ctx.strokeStyle = 'rgba(255,255,255,0.5)';
      ctx.lineWidth = 3;
      ctx.stroke();

      ctx.beginPath();
      ctx.moveTo(0, -m.radius);
      ctx.lineTo(0, m.radius);
      ctx.strokeStyle = 'rgba(0,0,0,0.3)';
      ctx.lineWidth = 2;
      ctx.stroke();

      ctx.beginPath();
      ctx.arc(-4, -4, 3, 0, Math.PI * 2);
      ctx.fillStyle = 'rgba(255,255,255,0.7)';
      ctx.fill();

      ctx.restore(); 

      if (m.id === betMarbleId) {
        ctx.strokeStyle = '#fbbf24';
        ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.arc(m.x, m.y, m.radius + 5, 0, Math.PI * 2);
        ctx.stroke();
      }

      if (!m.finished) {
        ctx.fillStyle = '#fff';
        ctx.font = '10px Arial';
        ctx.textAlign = 'center';
        ctx.fillText(m.name, m.x, m.y - 18);
      }
    });

    ctx.restore();
  };

  useEffect(() => {
    const loop = () => {
      update();
      draw();
      requestRef.current = requestAnimationFrame(loop);
    };
    requestRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(requestRef.current!);
  });

  return (
    <canvas ref={canvasRef} className="w-full h-full block" />
  );
};

export default RaceEngine;

export interface Marble {
  id: number;
  color: string;
  name: string;
  x: number;
  y: number;
  vx: number;
  vy: number;
  radius: number;
  angle: number; // Rotation angle in radians
  omega: number; // Angular velocity in radians/tick
  score: number; // For Points Mode
  finished: boolean;
  finishTime: number;
  rank: number; // 0 if not finished
}

export interface LineSegment {
  x1: number;
  y1: number;
  x2: number;
  y2: number;
  type: 'wall' | 'floor' | 'bouncer';
}

export interface CircleObstacle {
  x: number;
  y: number;
  radius: number;
  type: 'pin' | 'bumper';
}

export interface DynamicObstacle {
  id: string;
  type: 'spinner' | 'slider_h' | 'slider_v' | 'fan';
  x: number;
  y: number;
  width: number; // Length of the line/blade, or width of fan source
  height?: number; // Range of the fan wind
  angle: number;
  speed: number;
  range?: number; // For sliders
  initialX?: number;
  initialY?: number;
  force?: number; // Wind strength
}

export interface PhysicsConfig {
  gravity: number;
  restitution: number; // Bounciness 0.1 to 0.9
  friction: number;
}

export type GameMode = 'elimination' | 'points';

export interface GameState {
  gameMode: GameMode;
  phase: 'betting' | 'racing' | 'round_result' | 'champion';
  round: number; // Starts at 1
  totalRounds: number; // 9 for elimination, 5 for points
  marbles: Marble[]; // All marbles
  activeMarbleIds: number[]; // IDs of marbles still in tournament
  betMarbleId: number | null;
  lastEliminatedId: number | null;
  roundPoints: Record<number, number>; // Points earned in the current round (marbleId -> points)
}

import React, { useState, useEffect } from 'react';
import RaceEngine from './components/RaceEngine';
import { Marble, GameState, PhysicsConfig, GameMode } from './types';
import { Trophy, Settings, Skull, Play, Timer, ArrowDown, Medal, CheckCircle2 } from 'lucide-react';
import { audio } from './services/audioService';

const NAMES = [
  "Thunder", "Lightning", "Comet", "Shadow", 
  "Blaze", "Frost", "Viper", "Titan", "Nova", "Ghost"
];

const COLORS = [
  "#ef4444", "#3b82f6", "#10b981", "#f59e0b",
  "#8b5cf6", "#ec4899", "#6366f1", "#14b8a6", "#f97316", "#64748b"
];

// Points distribution for Points Mode (1st to 10th)
const POINTS_SYSTEM = [10, 8, 6, 5, 4, 3, 2, 1, 0, 0];

const INITIAL_MARBLES: Marble[] = NAMES.map((name, i) => ({
  id: i,
  name,
  color: COLORS[i],
  x: 0, y: 0, vx: 0, vy: 0, radius: 12,
  angle: 0,
  omega: 0,
  score: 0,
  finished: false, finishTime: 0, rank: 0
}));

export default function App() {
  const [gameState, setGameState] = useState<GameState>({
    gameMode: 'elimination',
    phase: 'betting',
    round: 1,
    totalRounds: 9,
    marbles: INITIAL_MARBLES,
    activeMarbleIds: INITIAL_MARBLES.map(m => m.id),
    betMarbleId: null,
    lastEliminatedId: null,
    roundPoints: {}
  });

  const [physicsConfig, setPhysicsConfig] = useState<PhysicsConfig>({
    gravity: 0.25,
    restitution: 0.6,
    friction: 0.99
  });

  const activeMarblesList = gameState.marbles.filter(m => gameState.activeMarbleIds.includes(m.id));

  // --- Handlers ---

  const handleModeSelect = (mode: GameMode) => {
    setGameState(prev => ({
      ...prev,
      gameMode: mode,
      totalRounds: mode === 'elimination' ? 9 : 5 // 5 rounds for points mode
    }));
  };

  const handleStartTournament = () => {
    if (gameState.betMarbleId === null) return;

    audio.init();
    audio.resume();

    setGameState(prev => ({ ...prev, phase: 'racing' }));
  };

  const handleRaceFinish = (results: Marble[]) => {
    // results is sorted by finish order (0 is winner)

    if (gameState.gameMode === 'elimination') {
      const loser = results[results.length - 1];
      audio.playEliminated();
      setGameState(prev => ({
        ...prev,
        phase: 'round_result',
        lastEliminatedId: loser.id,
        roundPoints: {}
      }));
    } else {
      // Points Mode logic
      const currentRoundPoints: Record<number, number> = {};
      const updatedMarbles = [...gameState.marbles];

      results.forEach((m, index) => {
        const points = POINTS_SYSTEM[index] || 0;
        currentRoundPoints[m.id] = points;

        // Update total score
        const marbleIndex = updatedMarbles.findIndex(mar => mar.id === m.id);
        if (marbleIndex !== -1) {
          updatedMarbles[marbleIndex] = {
            ...updatedMarbles[marbleIndex],
            score: updatedMarbles[marbleIndex].score + points
          };
        }
      });

      audio.playFinish();

      setGameState(prev => ({
        ...prev,
        marbles: updatedMarbles,
        phase: 'round_result',
        roundPoints: currentRoundPoints
      }));
    }
  };

  const handleNextRound = () => {
    if (gameState.gameMode === 'elimination') {
      const nextActiveIds = gameState.activeMarbleIds.filter(id => id !== gameState.lastEliminatedId);

      if (nextActiveIds.length === 1) {
        audio.playFinish(); 
        setGameState(prev => ({
          ...prev,
          activeMarbleIds: nextActiveIds,
          phase: 'champion'
        }));
      } else {
        setGameState(prev => ({
          ...prev,
          activeMarbleIds: nextActiveIds,
          phase: 'racing',
          round: prev.round + 1,
          lastEliminatedId: null
        }));
      }
    } else {
      // Points Mode
      if (gameState.round >= gameState.totalRounds) {
         // End of tournament
         // Sort by total score to find winner
         const sortedByScore = [...gameState.marbles].sort((a, b) => b.score - a.score);
         // Champion is the first one
         const winnerIds = [sortedByScore[0].id]; // Could support ties later

         audio.playFinish();
         setGameState(prev => ({
           ...prev,
           activeMarbleIds: winnerIds, // Just for champion screen display
           phase: 'champion'
         }));
      } else {
        setGameState(prev => ({
          ...prev,
          phase: 'racing',
          round: prev.round + 1,
          roundPoints: {}
        }));
      }
    }
  };

  const resetGame = () => {
    setGameState({
      gameMode: gameState.gameMode,
      phase: 'betting',
      round: 1,
      totalRounds: gameState.gameMode === 'elimination' ? 9 : 5,
      marbles: INITIAL_MARBLES.map(m => ({...m, score: 0})),
      activeMarbleIds: INITIAL_MARBLES.map(m => m.id),
      betMarbleId: null,
      lastEliminatedId: null,
      roundPoints: {}
    });
  };

  // --- Render Components ---

  // 1. Betting / Config Screen
  if (gameState.phase === 'betting') {
    return (
      <div className="min-h-screen bg-gray-900 flex flex-col items-center justify-center p-4 text-white">
        <h1 className="text-5xl md:text-7xl mb-2 text-transparent bg-clip-text bg-gradient-to-r from-yellow-400 to-red-500 brand-font tracking-widest text-center">
          MARBLE ROYALE
        </h1>

        {/* Mode Selector */}
        <div className="flex space-x-4 mb-6 bg-gray-800 p-2 rounded-lg border border-gray-700">
           <button 
             onClick={() => handleModeSelect('elimination')}
             className={`px-4 py-2 rounded-md font-bold transition-all ${gameState.gameMode === 'elimination' ? 'bg-red-600 text-white' : 'text-gray-400 hover:text-white'}`}
           >
             MATA-MATA (Eliminação)
           </button>
           <button 
             onClick={() => handleModeSelect('points')}
             className={`px-4 py-2 rounded-md font-bold transition-all ${gameState.gameMode === 'points' ? 'bg-blue-600 text-white' : 'text-gray-400 hover:text-white'}`}
           >
             PONTOS CORRIDOS (5 Rodadas)
           </button>
        </div>

        <p className="text-gray-400 mb-8 font-mono text-center max-w-lg">
          {gameState.gameMode === 'elimination' 
            ? "10 Bolinhas entram. A última de cada corrida é eliminada até sobrar uma."
            : "5 Corridas. Pontos acumulados por posição (1º=10pts). Ninguém é eliminado."}
        </p>

        <div className="bg-gray-800 p-6 rounded-xl border border-gray-700 w-full max-w-2xl shadow-2xl">
          <div className="mb-6">
            <h2 className="text-xl font-bold mb-4 flex items-center text-yellow-400">
              <Trophy className="mr-2" /> Escolha sua Aposta
            </h2>
            <div className="grid grid-cols-2 md:grid-cols-5 gap-3">
              {gameState.marbles.map(m => (
                <button
                  key={m.id}
                  onClick={() => setGameState(prev => ({ ...prev, betMarbleId: m.id }))}
                  className={`p-3 rounded-lg flex flex-col items-center transition-all ${
                    gameState.betMarbleId === m.id 
                      ? 'bg-yellow-500/20 border-2 border-yellow-400 scale-105' 
                      : 'bg-gray-700 border border-transparent hover:bg-gray-600'
                  }`}
                >
                  <div className="w-8 h-8 rounded-full mb-2 shadow-lg" style={{ backgroundColor: m.color }}></div>
                  <span className="text-xs font-bold font-mono">{m.name}</span>
                </button>
              ))}
            </div>
          </div>

          <div className="mb-8 border-t border-gray-700 pt-6">
            <h2 className="text-xl font-bold mb-4 flex items-center text-blue-400">
              <Settings className="mr-2" /> Configuração da Física
            </h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className="text-xs text-gray-400 block mb-1">Gravidade ({(physicsConfig.gravity * 100).toFixed(0)}%)</label>
                <input 
                  type="range" min="0.1" max="0.8" step="0.05"
                  value={physicsConfig.gravity}
                  onChange={(e) => setPhysicsConfig(prev => ({...prev, gravity: parseFloat(e.target.value)}))}
                  className="w-full accent-blue-500"
                />
              </div>
              <div>
                <label className="text-xs text-gray-400 block mb-1">Elasticidade (Quique) ({(physicsConfig.restitution * 100).toFixed(0)}%)</label>
                <input 
                  type="range" min="0.1" max="0.9" step="0.1"
                  value={physicsConfig.restitution}
                  onChange={(e) => setPhysicsConfig(prev => ({...prev, restitution: parseFloat(e.target.value)}))}
                  className="w-full accent-blue-500"
                />
              </div>
            </div>
          </div>

          <button 
            disabled={gameState.betMarbleId === null}
            onClick={handleStartTournament}
            className={`w-full py-4 rounded-lg font-black text-xl tracking-widest transition-all ${
              gameState.betMarbleId !== null
                ? 'bg-gradient-to-r from-green-500 to-emerald-600 hover:from-green-400 hover:to-emerald-500 text-white shadow-lg transform hover:-translate-y-1'
                : 'bg-gray-700 text-gray-500 cursor-not-allowed'
            }`}
          >
            INICIAR TORNEIO
          </button>
        </div>
      </div>
    );
  }

  // 2. Champion Screen
  if (gameState.phase === 'champion') {
    // In points mode, activeMarbleIds contains only the winner(s)
    const championId = gameState.activeMarbleIds[0];
    const champion = gameState.marbles.find(m => m.id === championId)!;
    const playerWon = gameState.betMarbleId === championId;

    return (
      <div className="min-h-screen bg-black flex flex-col items-center justify-center p-6 text-center animate-fadeIn">
        <div className="relative mb-8">
           <div className="absolute inset-0 bg-yellow-500 blur-3xl opacity-20 animate-pulse"></div>
           <Trophy className="w-32 h-32 text-yellow-400 relative z-10 mx-auto mb-4" />
           <div className="w-24 h-24 rounded-full mx-auto relative z-10 shadow-[0_0_50px_rgba(255,255,255,0.5)] border-4 border-white" style={{ backgroundColor: champion.color }}></div>
        </div>

        <h1 className="text-6xl font-black text-white mb-2 brand-font">{champion.name}</h1>
        <p className="text-2xl text-yellow-500 font-mono mb-4">CAMPEÃ DO TORNEIO</p>

        {gameState.gameMode === 'points' && (
           <div className="text-xl text-blue-400 mb-8 font-mono font-bold">
              Pontuação Final: {champion.score} pts
           </div>
        )}

        <div className={`p-6 rounded-xl border-2 mb-8 max-w-md w-full ${playerWon ? 'bg-green-900/30 border-green-500' : 'bg-red-900/30 border-red-500'}`}>
          <h3 className="text-xl font-bold mb-2">{playerWon ? "PARABÉNS!" : "NÃO FOI DESSA VEZ"}</h3>
          <p className="text-gray-300">
            {playerWon 
              ? `Sua aposta em ${champion.name} estava certa!` 
              : `Você apostou em ${gameState.marbles.find(m => m.id === gameState.betMarbleId)?.name}. Tente novamente!`}
          </p>
        </div>

        {gameState.gameMode === 'points' && (
          <div className="w-full max-w-md bg-gray-800 rounded-lg p-4 mb-8 overflow-y-auto max-h-60">
             <h4 className="text-gray-400 mb-2 font-bold uppercase text-xs tracking-wider">Tabela Final</h4>
             {[...gameState.marbles].sort((a,b) => b.score - a.score).map((m, idx) => (
                <div key={m.id} className="flex justify-between items-center py-2 border-b border-gray-700 last:border-0">
                   <div className="flex items-center space-x-3">
                      <span className="text-gray-500 font-mono w-4">{idx + 1}</span>
                      <div className="w-3 h-3 rounded-full" style={{backgroundColor: m.color}}></div>
                      <span>{m.name}</span>
                   </div>
                   <span className="font-mono font-bold text-yellow-500">{m.score}</span>
                </div>
             ))}
          </div>
        )}

        <button 
          onClick={resetGame}
          className="px-8 py-3 bg-white text-black font-bold rounded-full hover:scale-105 transition-transform"
        >
          NOVO TORNEIO
        </button>
      </div>
    );
  }

  // 3. Racing / Round Result Screen (Game Loop)
  return (
    <div className="relative w-full h-screen bg-gray-900 overflow-hidden">

      {/* Race View */}
      <div className="absolute inset-0 z-0">
        <RaceEngine 
          activeMarbles={activeMarblesList}
          config={physicsConfig}
          onRaceFinish={handleRaceFinish}
          betMarbleId={gameState.betMarbleId}
        />
      </div>

      {/* Overlay UI */}
      <div className="absolute top-0 left-0 w-full p-4 flex justify-between items-start z-10 pointer-events-none">
         <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white">
           <div className="text-xs text-gray-400 font-bold uppercase">Rodada</div>
           <div className="text-2xl font-mono text-yellow-400">{gameState.round} <span className="text-sm text-gray-500">/ {gameState.totalRounds}</span></div>
         </div>

         {gameState.gameMode === 'points' && (
           <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white max-w-[150px]">
             <div className="text-xs text-gray-400 font-bold uppercase mb-1">Top Pontos</div>
             {gameState.marbles
               .sort((a,b) => b.score - a.score)
               .slice(0, 3)
               .map((m, i) => (
                 <div key={m.id} className="flex justify-between text-xs mb-1">
                   <span className={`${i===0?'text-yellow-400': 'text-gray-300'}`}>{i+1}. {m.name}</span>
                   <span className="font-mono">{m.score}</span>
                 </div>
               ))}
           </div>
         )}

         {gameState.gameMode === 'elimination' && (
            <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white text-right">
              <div className="text-xs text-gray-400 font-bold uppercase">Sobreviventes</div>
              <div className="text-2xl font-mono text-blue-400">{activeMarblesList.length}</div>
            </div>
         )}
      </div>

      {/* Round Result Modal */}
      {gameState.phase === 'round_result' && (
        <div className="absolute inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-gray-800 rounded-2xl p-8 max-w-sm w-full text-center border border-gray-700 shadow-2xl animate-in slide-in-from-bottom-10 fade-in duration-300">
            <h2 className="text-3xl font-bold text-white mb-6 brand-font">FIM DA RODADA {gameState.round}</h2>

            {gameState.gameMode === 'elimination' ? (
              <div className="bg-red-900/20 border border-red-500/50 p-4 rounded-xl mb-6">
                 <Skull className="w-8 h-8 text-red-500 mx-auto mb-2" />
                 <div className="text-red-400 font-bold text-sm uppercase mb-1">Eliminada</div>
                 {gameState.lastEliminatedId !== null && (
                   <div className="flex items-center justify-center space-x-2">
                      <div className="w-4 h-4 rounded-full" style={{ backgroundColor: gameState.marbles.find(m => m.id === gameState.lastEliminatedId)?.color }}></div>
                      <span className="text-xl text-white font-mono">
                        {gameState.marbles.find(m => m.id === gameState.lastEliminatedId)?.name}
                      </span>
                   </div>
                 )}
              </div>
            ) : (
              <div className="bg-gray-900/50 border border-gray-600 p-4 rounded-xl mb-6 max-h-[300px] overflow-y-auto">
                 <div className="flex items-center justify-center mb-4 text-yellow-400">
                    <Medal className="mr-2" /> Resultado da Rodada
                 </div>
                 {[...activeMarblesList].sort((a,b) => a.rank - b.rank).map((m, idx) => (
                   <div key={m.id} className="flex justify-between items-center py-2 border-b border-gray-700 last:border-0 text-sm">
                      <div className="flex items-center space-x-2">
                         <span className="w-4 text-gray-500">{idx + 1}</span>
                         <div className="w-3 h-3 rounded-full" style={{backgroundColor: m.color}}></div>
                         <span>{m.name}</span>
                      </div>
                      <div className="flex flex-col text-right">
                        <span className="text-green-400 font-bold">+{gameState.roundPoints[m.id]}</span>
                        <span className="text-[10px] text-gray-500">Total: {m.score}</span>
                      </div>
                   </div>
                 ))}
              </div>
            )}

            {gameState.gameMode === 'elimination' && gameState.lastEliminatedId === gameState.betMarbleId && (
              <div className="text-red-400 text-sm font-bold mb-6">
                SUA APOSTA FOI ELIMINADA! 😱
              </div>
            )}

            <button 
              onClick={handleNextRound}
              className="w-full py-3 bg-blue-600 hover:bg-blue-500 text-white font-bold rounded-lg flex items-center justify-center space-x-2 transition-colors"
            >
              <Play className="w-5 h-5" />
              <span>PRÓXIMA RODADA</span>
            </button>
          </div>
        </div>
      )}

      {/* Bet Indicator (Bottom) */}
      {gameState.phase === 'racing' && (
        <div className="absolute bottom-6 left-1/2 transform -translate-x-1/2 bg-black/60 backdrop-blur px-6 py-2 rounded-full border border-yellow-500/30 text-white font-mono text-sm flex items-center space-x-2">
           <span className="text-gray-400">Aposta:</span>
           <div className="w-3 h-3 rounded-full" style={{ backgroundColor: gameState.marbles.find(m => m.id === gameState.betMarbleId)?.color }}></div>
           <span className="font-bold text-yellow-400">{gameState.marbles.find(m => m.id === gameState.betMarbleId)?.name}</span>
           {gameState.gameMode === 'points' && (
             <span className="pl-2 border-l border-gray-600 text-blue-300">
               Score: {gameState.marbles.find(m => m.id === gameState.betMarbleId)?.score}
             </span>
           )}
        </div>
      )}

    </div>
  );
}

import React, { useRef, useEffect } from 'react';
import { Marble, PhysicsConfig, LineSegment, CircleObstacle, DynamicObstacle } from '../types';
import { audio } from '../services/audioService';

interface RaceEngineProps {
  activeMarbles: Marble[];
  config: PhysicsConfig;
  onRaceFinish: (results: Marble[]) => void;
  betMarbleId: number | null;
}

const RaceEngine: React.FC<RaceEngineProps> = ({ activeMarbles, config, onRaceFinish, betMarbleId }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();

  // Physics State (Mutable refs for performance)
  const marblesRef = useRef<Marble[]>([]);
  const linesRef = useRef<LineSegment[]>([]);
  const pinsRef = useRef<CircleObstacle[]>([]);
  const dynamicRef = useRef<DynamicObstacle[]>([]);

  const cameraY = useRef(0);
  const raceFinished = useRef(false);
  const finishLineY = useRef(0);
  const startTime = useRef(0);
  const timeRef = useRef(0);

  // Constants
  const COURSE_WIDTH = 600;
  const BALL_RADIUS = 12;

  // --- Level Generation ---
  const generateLevel = () => {
    const lines: LineSegment[] = [];
    const pins: CircleObstacle[] = [];
    const dynamics: DynamicObstacle[] = [];

    // Config
    const segments = 6 + Math.floor(Math.random() * 3);
    const segmentHeight = 450;
    let currentY = 0;

    // 1. Start Funnel
    lines.push({ x1: 0, y1: 0, x2: COURSE_WIDTH * 0.4, y2: 150, type: 'wall' });
    lines.push({ x1: COURSE_WIDTH, y1: 0, x2: COURSE_WIDTH * 0.6, y2: 150, type: 'wall' });
    lines.push({ x1: COURSE_WIDTH * 0.4, y1: 150, x2: COURSE_WIDTH * 0.4, y2: 180, type: 'wall' });
    lines.push({ x1: COURSE_WIDTH * 0.6, y1: 150, x2: COURSE_WIDTH * 0.6, y2: 180, type: 'wall' });

    currentY = 220;

    // 2. Procedural Segments
    for (let i = 0; i < segments; i++) {
      const type = Math.random();

      // Outer Walls
      lines.push({ x1: 0, y1: currentY - 50, x2: 0, y2: currentY + segmentHeight, type: 'wall' });
      lines.push({ x1: COURSE_WIDTH, y1: currentY - 50, x2: COURSE_WIDTH, y2: currentY + segmentHeight, type: 'wall' });

      if (type < 0.2) {
        // --- PROPELLERS (Spinners) ---
        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 100, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 100, type: 'floor' });

        dynamics.push({
          id: `spin_${i}_1`,
          type: 'spinner',
          x: COURSE_WIDTH * 0.35,
          y: currentY + 250,
          width: 140,
          angle: 0,
          speed: 0.1,
        });
        dynamics.push({
          id: `spin_${i}_2`,
          type: 'spinner',
          x: COURSE_WIDTH * 0.65,
          y: currentY + 350,
          width: 140,
          angle: Math.PI / 2,
          speed: -0.1,
        });

      } else if (type < 0.4) {
        // --- MOVING ELEVATORS (Vertical or Horizontal) ---
        const isVertical = Math.random() > 0.5;

        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.2, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.8, y2: currentY + 150, type: 'floor' });

        if (isVertical) {
           dynamics.push({
             id: `slide_v_${i}`,
             type: 'slider_v',
             x: COURSE_WIDTH / 2,
             y: currentY + 200,
             width: 200,
             angle: 0,
             speed: 1, 
             range: 100,
             initialX: COURSE_WIDTH / 2,
             initialY: currentY + 250
           });
        } else {
           dynamics.push({
            id: `slide_h_${i}`,
            type: 'slider_h',
            x: COURSE_WIDTH / 2,
            y: currentY + 250,
            width: 250,
            angle: 0,
            speed: 2,
            range: 150,
            initialX: COURSE_WIDTH / 2,
            initialY: currentY + 250
          });
        }

      } else if (type < 0.6) {
        // --- WIND CANNONS (New Obstacle) ---
        // Side walls feeding into a central area with wind pushing sideways
        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 100, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 100, type: 'floor' });

        // Fan on the left pushing right
        dynamics.push({
          id: `fan_${i}_1`,
          type: 'fan',
          x: 20, // Near left wall
          y: currentY + 250,
          width: 40, // width of the fan base
          height: 300, // Range of the wind
          angle: 0, // 0 radians = pointing right
          speed: 0,
          force: 0.6
        });

        // Some pins to make it chaotic
        pins.push({ x: COURSE_WIDTH * 0.6, y: currentY + 250, radius: 20, type: 'bumper' });

      } else if (type < 0.8) {
        // --- CLASSIC SLALOM ---
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.6, y2: currentY + 180, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 250, x2: COURSE_WIDTH * 0.4, y2: currentY + 380, type: 'floor' });
        pins.push({ x: COURSE_WIDTH * 0.8, y: currentY + 200, radius: 15, type: 'bumper' });
        pins.push({ x: COURSE_WIDTH * 0.2, y: currentY + 400, radius: 15, type: 'bumper' });

      } else {
         // --- MIXER ---
        lines.push({ x1: COURSE_WIDTH/2, y1: currentY + 50, x2: COURSE_WIDTH * 0.3, y2: currentY + 120, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH/2, y1: currentY + 50, x2: COURSE_WIDTH * 0.7, y2: currentY + 120, type: 'wall' });
        lines.push({ x1: 0, y1: currentY + 250, x2: COURSE_WIDTH * 0.35, y2: currentY + 350, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 250, x2: COURSE_WIDTH * 0.65, y2: currentY + 350, type: 'floor' });
        pins.push({ x: COURSE_WIDTH/2, y: currentY + 400, radius: 25, type: 'bumper' });
      }

      currentY += segmentHeight;
    }

    // 3. Finish Area
    lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 200, type: 'floor' });
    lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 200, type: 'floor' });

    finishLineY.current = currentY + 250;

    linesRef.current = lines;
    pinsRef.current = pins;
    dynamicRef.current = dynamics;
  };

  // --- Physics Logic ---
  const update = () => {
    if (raceFinished.current) {
        audio.updateRolling(0); 
        return;
    }

    const STEPS = 4;
    const dt = 1 / STEPS;
    timeRef.current += 1;

    const marbles = marblesRef.current;
    const dynamicObjs = dynamicRef.current;

    let totalSpeed = 0;

    // Update Dynamics
    const dynamicLines: LineSegment[] = [];

    // Separate fans from collision objects
    const fans: DynamicObstacle[] = [];
    const solidDynamics: DynamicObstacle[] = [];

    dynamicObjs.forEach(obj => {
      if (obj.type === 'fan') {
        fans.push(obj);
        return;
      }
      solidDynamics.push(obj);

      if (obj.type === 'spinner') {
        obj.angle += obj.speed;
      } else if (obj.type === 'slider_h') {
        obj.x = obj.initialX! + Math.sin(timeRef.current * 0.02) * (obj.range || 100);
      } else if (obj.type === 'slider_v') {
        obj.y = obj.initialY! + Math.sin(timeRef.current * 0.015) * (obj.range || 80);
      }

      const halfW = obj.width / 2;
      const dx = Math.cos(obj.angle) * halfW;
      const dy = Math.sin(obj.angle) * halfW;

      dynamicLines.push({
        x1: obj.x - dx, y1: obj.y - dy,
        x2: obj.x + dx, y2: obj.y + dy,
        type: obj.type === 'spinner' ? 'bouncer' : 'floor'
      });
    });

    for (let step = 0; step < STEPS; step++) {
      for (let i = 0; i < marbles.length; i++) {
        const m = marbles[i];
        if (m.finished) continue;

        // 1. Gravity & Movement
        m.vy += config.gravity * dt;
        m.x += m.vx * dt;
        m.y += m.vy * dt;

        // Fan Physics
        for (const fan of fans) {
          const dx = m.x - fan.x;
          const dy = m.y - fan.y;
          const localX = dx * Math.cos(-fan.angle) - dy * Math.sin(-fan.angle);
          const localY = dx * Math.sin(-fan.angle) + dy * Math.cos(-fan.angle);
          const halfWidth = fan.width / 2; 
          const range = fan.height || 200;

          if (localX > 0 && localX < range && Math.abs(localY) < halfWidth) {
             const force = fan.force || 0.5;
             const forceX = Math.cos(fan.angle) * force;
             const forceY = Math.sin(fan.angle) * force;
             m.vx += forceX * dt;
             m.vy += forceY * dt;
          }
        }

        m.angle += m.omega * dt;
        m.omega *= 0.999; 

        m.vx *= Math.pow(config.friction, dt);
        m.vy *= Math.pow(config.friction, dt);

        if (m.vx*m.vx + m.vy*m.vy < 0.2) {
             m.vx += (Math.random() - 0.5); 
             m.vy += 0.5; 
        }

        // 2. Collisions
        for (const line of linesRef.current) checkLineCollision(m, line);
        for (const dLine of dynamicLines) checkLineCollision(m, dLine, true);
        for (const pin of pinsRef.current) checkPinCollision(m, pin);

        for (let j = i + 1; j < marbles.length; j++) {
           if (!marbles[j].finished) checkMarbleCollision(m, marbles[j]);
        }

        // 3. Finish Line
        if (m.y > finishLineY.current) {
          m.finished = true;
          m.finishTime = Date.now() - startTime.current;
          const finishedSoFar = marbles.filter(b => b.finished).length;
          m.rank = finishedSoFar;
          audio.playPinHit(10);
        }

        if (!m.finished) {
            totalSpeed += Math.sqrt(m.vx*m.vx + m.vy*m.vy + m.omega*m.radius*m.omega*m.radius);
        }
      }
    }

    audio.updateRolling(totalSpeed);

    const activeMarblesList = marbles.filter(m => !m.finished);
    if (activeMarblesList.length > 0) {
      activeMarblesList.sort((a, b) => b.y - a.y);
      const leaders = activeMarblesList.slice(0, 3); 
      const avgY = leaders.reduce((a, b) => a + b.y, 0) / leaders.length;
      cameraY.current += (avgY - cameraY.current - 300) * 0.08;
    } else {
      if (!raceFinished.current) {
        raceFinished.current = true;
        const sorted = [...marbles].sort((a, b) => a.rank - b.rank);
        audio.playFinish(); 
        setTimeout(() => onRaceFinish(sorted), 1000);
      }
    }
  };

  const resolveCollisionPhysics = (ball: Marble, nx: number, ny: number, isBouncy: boolean) => {
    const vDotN = ball.vx * nx + ball.vy * ny;
    if (vDotN > 0) return; 

    const intensity = Math.abs(vDotN);
    if (intensity > 1.0) {
        audio.playBump(intensity);
    }

    const restitution = isBouncy ? 1.5 : config.restitution;
    const jN = -(1 + restitution) * vDotN;
    ball.vx += jN * nx;
    ball.vy += jN * ny;

    const tx = -ny;
    const ty = nx;
    const vDotT = ball.vx * tx + ball.vy * ty;
    const vSurf = vDotT + ball.omega * ball.radius;

    const mass = 1.0;
    const jT_ideal = -vSurf / (3.5 / mass);
    const mu = 0.5;
    const maxJt = mu * Math.abs(jN);

    let jT = jT_ideal;
    if (Math.abs(jT) > maxJt) {
       jT = Math.sign(jT) * maxJt;
    }

    ball.vx += jT * tx;
    ball.vy += jT * ty;
    ball.omega += (2.5 * jT) / (mass * ball.radius);
  };

  const checkLineCollision = (ball: Marble, line: LineSegment, isDynamic = false) => {
    const dx = line.x2 - line.x1;
    const dy = line.y2 - line.y1;
    const lenSq = dx*dx + dy*dy;
    const t = Math.max(0, Math.min(1, ((ball.x - line.x1) * dx + (ball.y - line.y1) * dy) / lenSq));
    const closeX = line.x1 + t * dx;
    const closeY = line.y1 + t * dy;

    const distX = ball.x - closeX;
    const distY = ball.y - closeY;
    const distSq = distX*distX + distY*distY;

    if (distSq < ball.radius * ball.radius) {
      const dist = Math.sqrt(distSq);
      const nx = distX / dist;
      const ny = distY / dist;

      const overlap = ball.radius - dist;
      ball.x += nx * overlap;
      ball.y += ny * overlap;

      const isBouncy = isDynamic && line.type === 'bouncer';
      resolveCollisionPhysics(ball, nx, ny, isBouncy);

      if (isDynamic) {
        ball.vx += (Math.random() - 0.5) * 2;
        ball.vy += (Math.random() - 0.5) * 2;
      }
    }
  };

  const checkPinCollision = (ball: Marble, pin: CircleObstacle) => {
    const dx = ball.x - pin.x;
    const dy = ball.y - pin.y;
    const distSq = dx*dx + dy*dy;
    const minDist = ball.radius + pin.radius;

    if (distSq < minDist * minDist) {
      const dist = Math.sqrt(distSq);
      const nx = dx / dist;
      const ny = dy / dist;

      const overlap = minDist - dist;
      ball.x += nx * overlap;
      ball.y += ny * overlap;

      const isBumper = pin.type === 'bumper';

      const intensity = Math.sqrt(ball.vx*ball.vx + ball.vy*ball.vy);
      if (intensity > 1) {
          audio.playPinHit(intensity);
      }

      resolveCollisionPhysics(ball, nx, ny, isBumper);
    }
  };

  const checkMarbleCollision = (m1: Marble, m2: Marble) => {
    const dx = m2.x - m1.x;
    const dy = m2.y - m1.y;
    const distSq = dx*dx + dy*dy;
    const minDist = m1.radius + m2.radius;

    if (distSq < minDist * minDist) {
      const dist = Math.sqrt(distSq);
      const nx = dx / dist;
      const ny = dy / dist;
      const overlap = (minDist - dist) * 0.5;

      m1.x -= nx * overlap;
      m1.y -= ny * overlap;
      m2.x += nx * overlap;
      m2.y += ny * overlap;

      const dvx = m1.vx - m2.vx;
      const dvy = m1.vy - m2.vy;
      const dot = dvx * nx + dvy * ny;

      if (dot > 0) {
         if (dot > 2) audio.playPinHit(dot * 0.5);

         const impulse = dot * 0.9; 
         m1.vx -= impulse * nx;
         m1.vy -= impulse * ny;
         m2.vx += impulse * nx;
         m2.vy += impulse * ny;
      }
    }
  };

  // --- Initialization ---
  useEffect(() => {
    generateLevel();
    raceFinished.current = false;
    startTime.current = Date.now();
    cameraY.current = 0;
    timeRef.current = 0;

    marblesRef.current = activeMarbles.map((m, index) => ({
      ...m,
      x: COURSE_WIDTH * 0.4 + (Math.random() * COURSE_WIDTH * 0.2),
      y: -50 - (index * 40),
      vx: (Math.random() - 0.5) * 5,
      vy: 0,
      angle: 0,
      omega: 0,
      finished: false,
      rank: 0
    }));

    audio.resume();

  }, [activeMarbles]); 

  // --- Render Loop ---
  const draw = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const { offsetWidth, offsetHeight } = canvas;
    if (canvas.width !== offsetWidth || canvas.height !== offsetHeight) {
      canvas.width = offsetWidth;
      canvas.height = offsetHeight;
    }

    ctx.fillStyle = '#1f2937';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.save();
    const scale = canvas.width / COURSE_WIDTH;
    ctx.scale(scale, scale);
    const camY = Math.max(0, Math.min(cameraY.current, finishLineY.current - canvas.height/scale + 100));
    ctx.translate(0, -camY);

    // Draw Static Lines
    ctx.lineWidth = 4;
    ctx.lineCap = 'round';
    linesRef.current.forEach(l => {
      ctx.strokeStyle = l.type === 'wall' ? '#4b5563' : '#60a5fa';
      if (l.type === 'wall') ctx.lineWidth = 6;
      else ctx.lineWidth = 4;
      ctx.beginPath();
      ctx.moveTo(l.x1, l.y1);
      ctx.lineTo(l.x2, l.y2);
      ctx.stroke();
    });

    // Draw Dynamic Obstacles
    dynamicRef.current.forEach(obj => {
       ctx.save();
       ctx.translate(obj.x, obj.y);
       ctx.rotate(obj.angle);

       if (obj.type === 'fan') {
          // Draw Fan Base
          ctx.fillStyle = '#64748b';
          ctx.fillRect(-10, -obj.width/2, 20, obj.width);

          // Draw Air Flow
          const range = obj.height || 200;
          const gradient = ctx.createLinearGradient(0, 0, range, 0);
          gradient.addColorStop(0, 'rgba(255, 255, 255, 0.4)');
          gradient.addColorStop(1, 'rgba(255, 255, 255, 0)');

          ctx.fillStyle = gradient;
          ctx.fillRect(0, -obj.width/2, range, obj.width);

          // Animated Lines
          ctx.strokeStyle = 'rgba(255, 255, 255, 0.5)';
          ctx.lineWidth = 1;
          const offset = (timeRef.current * 5) % 50;
          for(let i=0; i<3; i++) {
             const yPos = -obj.width/2 + (obj.width/4) * (i+1);
             ctx.beginPath();
             ctx.moveTo(10 + offset, yPos);
             ctx.lineTo(range - 20, yPos);
             ctx.stroke();
          }

       } else {
         // Sliders & Spinners
         ctx.strokeStyle = obj.type === 'spinner' ? '#ef4444' : '#f59e0b';
         ctx.lineWidth = 8;
         ctx.beginPath();
         ctx.moveTo(-obj.width/2, 0);
         ctx.lineTo(obj.width/2, 0);
         ctx.stroke();

         if (obj.type === 'spinner') {
           ctx.beginPath();
           ctx.arc(0, 0, 5, 0, Math.PI * 2);
           ctx.fillStyle = '#fff';
           ctx.fill();
         }
       }
       ctx.restore();
    });

    // Draw Pins
    pinsRef.current.forEach(p => {
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.radius, 0, Math.PI * 2);
      ctx.fillStyle = p.type === 'bumper' ? '#f472b6' : '#9ca3af';
      ctx.fill();
    });

    // Draw Finish Line
    ctx.fillStyle = '#10b981';
    ctx.fillRect(0, finishLineY.current, COURSE_WIDTH, 10);
    for(let i=0; i<20; i++) {
        ctx.fillStyle = i%2===0 ? '#fff' : '#000';
        ctx.fillRect(i * (COURSE_WIDTH/20), finishLineY.current, COURSE_WIDTH/20, 10);
    }

    // Sort marbles for live ranking (by Y position, descending)
    const liveRanking = [...marblesRef.current]
      .sort((a, b) => {
        if (a.finished && b.finished) return a.rank - b.rank; // Both finished, use final rank
        if (a.finished) return -1; // a finished first
        if (b.finished) return 1; // b finished first
        return b.y - a.y; // Further down is better
      })
      .map(m => m.id);

    // Draw Marbles
    marblesRef.current.forEach(m => {
      ctx.save();
      ctx.translate(m.x, m.y);
      // CORRECTION: Invert angle for correct visual rotation
      ctx.rotate(-m.angle); 

      ctx.beginPath();
      ctx.arc(0, 0, m.radius, 0, Math.PI * 2);
      ctx.fillStyle = m.color;
      ctx.shadowColor = 'rgba(0,0,0,0.5)';
      ctx.shadowBlur = 5;
      ctx.fill();
      ctx.shadowBlur = 0;

      ctx.beginPath();
      ctx.moveTo(-m.radius, 0);
      ctx.lineTo(m.radius, 0);
      ctx.strokeStyle = 'rgba(255,255,255,0.5)';
      ctx.lineWidth = 3;
      ctx.stroke();

      ctx.beginPath();
      ctx.moveTo(0, -m.radius);
      ctx.lineTo(0, m.radius);
      ctx.strokeStyle = 'rgba(0,0,0,0.3)';
      ctx.lineWidth = 2;
      ctx.stroke();

      ctx.beginPath();
      ctx.arc(-4, -4, 3, 0, Math.PI * 2);
      ctx.fillStyle = 'rgba(255,255,255,0.7)';
      ctx.fill();

      ctx.restore(); 

      if (m.id === betMarbleId) {
        ctx.strokeStyle = '#fbbf24';
        ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.arc(m.x, m.y, m.radius + 5, 0, Math.PI * 2);
        ctx.stroke();
      }

      if (!m.finished) {
        // Name
        ctx.fillStyle = '#fff';
        ctx.font = '10px Arial';
        ctx.textAlign = 'center';
        ctx.fillText(m.name, m.x, m.y - 18);

        // Live Rank Badge
        const currentRank = liveRanking.indexOf(m.id) + 1;
        if (currentRank <= 3) {
            ctx.fillStyle = currentRank === 1 ? '#fbbf24' : currentRank === 2 ? '#9ca3af' : '#b45309';
            ctx.beginPath();
            ctx.arc(m.x + m.radius, m.y - m.radius, 8, 0, Math.PI * 2);
            ctx.fill();
            ctx.fillStyle = '#000';
            ctx.font = 'bold 10px Arial';
            ctx.fillText(currentRank.toString(), m.x + m.radius, m.y - m.radius + 3);
        }
      }
    });

    ctx.restore();
  };

  useEffect(() => {
    const loop = () => {
      update();
      draw();
      requestRef.current = requestAnimationFrame(loop);
    };
    requestRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(requestRef.current!);
  });

  return (
    <canvas ref={canvasRef} className="w-full h-full block" />
  );
};

export default RaceEngine;

export interface Marble {
  id: number;
  color: string;
  name: string;
  x: number;
  y: number;
  vx: number;
  vy: number;
  radius: number;
  angle: number; // Rotation angle in radians
  omega: number; // Angular velocity in radians/tick
  score: number; // For Points Mode
  finished: boolean;
  finishTime: number;
  rank: number; // 0 if not finished
}

export interface LineSegment {
  x1: number;
  y1: number;
  x2: number;
  y2: number;
  type: 'wall' | 'floor' | 'bouncer';
}

export interface CircleObstacle {
  x: number;
  y: number;
  radius: number;
  type: 'pin' | 'bumper';
}

export interface DynamicObstacle {
  id: string;
  type: 'spinner' | 'slider_h' | 'slider_v' | 'fan' | 'repulsor' | 'conveyor';
  x: number;
  y: number;
  width: number; // Length of the line/blade, or width of fan source
  height?: number; // Range of the fan wind
  angle: number;
  speed: number;
  range?: number; // For sliders or repulsor pulse radius
  initialX?: number;
  initialY?: number;
  force?: number; // Wind strength or Repulsor force
}

export interface PhysicsConfig {
  gravity: number;
  restitution: number; // Bounciness 0.1 to 0.9
  friction: number;
}

export type GameMode = 'elimination' | 'points';

export interface GameState {
  gameMode: GameMode;
  phase: 'betting' | 'racing' | 'round_result' | 'champion';
  round: number; // Starts at 1
  totalRounds: number; // 9 for elimination, 5 for points
  marbles: Marble[]; // All marbles
  activeMarbleIds: number[]; // IDs of marbles still in tournament
  betMarbleId: number | null;
  lastEliminatedId: number | null;
  roundPoints: Record<number, number>; // Points earned in the current round (marbleId -> points)
}

import React, { useRef, useEffect } from 'react';
import { Marble, PhysicsConfig, LineSegment, CircleObstacle, DynamicObstacle } from '../types';
import { audio } from '../services/audioService';

interface RaceEngineProps {
  activeMarbles: Marble[];
  config: PhysicsConfig;
  onRaceFinish: (results: Marble[]) => void;
  betMarbleId: number | null;
}

const RaceEngine: React.FC<RaceEngineProps> = ({ activeMarbles, config, onRaceFinish, betMarbleId }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();

  // Physics State (Mutable refs for performance)
  const marblesRef = useRef<Marble[]>([]);
  const linesRef = useRef<LineSegment[]>([]);
  const pinsRef = useRef<CircleObstacle[]>([]);
  const dynamicRef = useRef<DynamicObstacle[]>([]);

  const cameraY = useRef(0);
  const raceFinished = useRef(false);
  const finishLineY = useRef(0);
  const startTime = useRef(0);
  const timeRef = useRef(0);

  // Constants
  const COURSE_WIDTH = 600;

  // --- Level Generation ---
  const generateLevel = () => {
    const lines: LineSegment[] = [];
    const pins: CircleObstacle[] = [];
    const dynamics: DynamicObstacle[] = [];

    // Config
    const segments = 8 + Math.floor(Math.random() * 3);
    const segmentHeight = 450;
    let currentY = 0;

    // 1. Start Funnel
    lines.push({ x1: 0, y1: 0, x2: COURSE_WIDTH * 0.4, y2: 150, type: 'wall' });
    lines.push({ x1: COURSE_WIDTH, y1: 0, x2: COURSE_WIDTH * 0.6, y2: 150, type: 'wall' });
    lines.push({ x1: COURSE_WIDTH * 0.4, y1: 150, x2: COURSE_WIDTH * 0.4, y2: 180, type: 'wall' });
    lines.push({ x1: COURSE_WIDTH * 0.6, y1: 150, x2: COURSE_WIDTH * 0.6, y2: 180, type: 'wall' });

    currentY = 220;

    // 2. Procedural Segments
    for (let i = 0; i < segments; i++) {
      const type = Math.random();

      // Outer Walls
      lines.push({ x1: 0, y1: currentY - 50, x2: 0, y2: currentY + segmentHeight, type: 'wall' });
      lines.push({ x1: COURSE_WIDTH, y1: currentY - 50, x2: COURSE_WIDTH, y2: currentY + segmentHeight, type: 'wall' });

      if (type < 0.15) {
        // --- PROPELLERS (Spinners) ---
        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 100, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 100, type: 'floor' });

        dynamics.push({
          id: `spin_${i}_1`,
          type: 'spinner',
          x: COURSE_WIDTH * 0.35,
          y: currentY + 250,
          width: 140,
          angle: 0,
          speed: 0.1,
        });
        dynamics.push({
          id: `spin_${i}_2`,
          type: 'spinner',
          x: COURSE_WIDTH * 0.65,
          y: currentY + 350,
          width: 140,
          angle: Math.PI / 2,
          speed: -0.1,
        });

      } else if (type < 0.3) {
        // --- REPULSORS (New) ---
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.3, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.7, y2: currentY + 150, type: 'floor' });

        // Central Repulsor
        dynamics.push({
          id: `repulse_${i}`,
          type: 'repulsor',
          x: COURSE_WIDTH / 2,
          y: currentY + 300,
          width: 50, // core radius
          range: 120, // pulse max radius
          angle: 0,
          speed: 0.1, // pulse speed
          force: 2.5
        });

      } else if (type < 0.45) {
        // --- CONVEYOR BELTS (New) ---
        // Funnel into a fast conveyor
        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.4, y2: currentY + 100, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.6, y2: currentY + 100, type: 'wall' });

        // Conveyor Strip
        dynamics.push({
          id: `conveyor_${i}`,
          type: 'conveyor',
          x: COURSE_WIDTH * 0.5,
          y: currentY + 250,
          width: 200, // length
          height: 100, // width of path
          angle: Math.PI / 2, // Downwards
          speed: 0.1, // Animation speed
          force: 15 // Acceleration
        });

      } else if (type < 0.6) {
        // --- MOVING ELEVATORS ---
        const isVertical = Math.random() > 0.5;

        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.2, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.8, y2: currentY + 150, type: 'floor' });

        if (isVertical) {
           dynamics.push({
             id: `slide_v_${i}`,
             type: 'slider_v',
             x: COURSE_WIDTH / 2,
             y: currentY + 200,
             width: 200,
             angle: 0,
             speed: 1, 
             range: 100,
             initialX: COURSE_WIDTH / 2,
             initialY: currentY + 250
           });
        } else {
           dynamics.push({
            id: `slide_h_${i}`,
            type: 'slider_h',
            x: COURSE_WIDTH / 2,
            y: currentY + 250,
            width: 250,
            angle: 0,
            speed: 2,
            range: 150,
            initialX: COURSE_WIDTH / 2,
            initialY: currentY + 250
          });
        }

      } else if (type < 0.75) {
        // --- WIND CANNONS ---
        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 100, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 100, type: 'floor' });

        dynamics.push({
          id: `fan_${i}_1`,
          type: 'fan',
          x: 20, 
          y: currentY + 250,
          width: 40,
          height: 300, 
          angle: 0, 
          speed: 0,
          force: 0.6
        });

        pins.push({ x: COURSE_WIDTH * 0.6, y: currentY + 250, radius: 20, type: 'bumper' });

      } else {
         // --- CLASSIC SLALOM ---
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.6, y2: currentY + 180, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 250, x2: COURSE_WIDTH * 0.4, y2: currentY + 380, type: 'floor' });
        pins.push({ x: COURSE_WIDTH * 0.8, y: currentY + 200, radius: 15, type: 'bumper' });
        pins.push({ x: COURSE_WIDTH * 0.2, y: currentY + 400, radius: 15, type: 'bumper' });
      }

      currentY += segmentHeight;
    }

    // 3. Finish Area
    lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 200, type: 'floor' });
    lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 200, type: 'floor' });

    finishLineY.current = currentY + 250;

    linesRef.current = lines;
    pinsRef.current = pins;
    dynamicRef.current = dynamics;
  };

  // --- Physics Logic ---
  const update = () => {
    if (raceFinished.current) {
        audio.updateRolling(0); 
        return;
    }

    const STEPS = 4;
    const dt = 1 / STEPS;
    timeRef.current += 1;

    const marbles = marblesRef.current;
    const dynamicObjs = dynamicRef.current;

    let totalSpeed = 0;

    // Separate dynamic types for optimized loops
    const fans: DynamicObstacle[] = [];
    const repulsors: DynamicObstacle[] = [];
    const conveyors: DynamicObstacle[] = [];
    const solidDynamics: DynamicObstacle[] = [];

    dynamicObjs.forEach(obj => {
      if (obj.type === 'fan') {
        fans.push(obj);
        return;
      }
      if (obj.type === 'repulsor') {
        repulsors.push(obj);
        return;
      }
      if (obj.type === 'conveyor') {
        conveyors.push(obj);
        return;
      }

      solidDynamics.push(obj);

      // Animation updates for solids
      if (obj.type === 'spinner') {
        obj.angle += obj.speed;
      } else if (obj.type === 'slider_h') {
        obj.x = obj.initialX! + Math.sin(timeRef.current * 0.02) * (obj.range || 100);
      } else if (obj.type === 'slider_v') {
        obj.y = obj.initialY! + Math.sin(timeRef.current * 0.015) * (obj.range || 80);
      }
    });

    // Generate collision lines for solids
    const dynamicLines: LineSegment[] = [];
    solidDynamics.forEach(obj => {
      const halfW = obj.width / 2;
      const dx = Math.cos(obj.angle) * halfW;
      const dy = Math.sin(obj.angle) * halfW;
      dynamicLines.push({
        x1: obj.x - dx, y1: obj.y - dy,
        x2: obj.x + dx, y2: obj.y + dy,
        type: obj.type === 'spinner' ? 'bouncer' : 'floor'
      });
    });

    for (let step = 0; step < STEPS; step++) {
      for (let i = 0; i < marbles.length; i++) {
        const m = marbles[i];
        if (m.finished) continue;

        // 1. Gravity & Movement
        m.vy += config.gravity * dt;
        m.x += m.vx * dt;
        m.y += m.vy * dt;

        // -- Force Fields & Zones --

        // Fan Physics
        for (const fan of fans) {
          const dx = m.x - fan.x;
          const dy = m.y - fan.y;
          const localX = dx * Math.cos(-fan.angle) - dy * Math.sin(-fan.angle);
          const localY = dx * Math.sin(-fan.angle) + dy * Math.cos(-fan.angle);
          const halfWidth = fan.width / 2; 
          const range = fan.height || 200;

          if (localX > 0 && localX < range && Math.abs(localY) < halfWidth) {
             const force = fan.force || 0.5;
             const forceX = Math.cos(fan.angle) * force;
             const forceY = Math.sin(fan.angle) * force;
             m.vx += forceX * dt;
             m.vy += forceY * dt;
          }
        }

        // Repulsor Physics
        for (const rep of repulsors) {
          const dx = m.x - rep.x;
          const dy = m.y - rep.y;
          const distSq = dx*dx + dy*dy;
          const range = rep.range || 100;

          if (distSq < range * range) {
             const dist = Math.sqrt(distSq);
             const nx = dx / dist;
             const ny = dy / dist;

             // Pulse effect logic: Stronger at center, varies with time
             const pulse = (Math.sin(timeRef.current * rep.speed) + 1) * 0.5;
             const force = (rep.force || 1) * (1 - dist/range) * (0.5 + pulse);

             m.vx += nx * force * dt * 50;
             m.vy += ny * force * dt * 50;
          }
        }

        // Conveyor Physics
        for (const conv of conveyors) {
           // Define conveyor box (center x,y, width=length, height=width)
           const dx = m.x - conv.x;
           const dy = m.y - conv.y;

           // Rotate to align with conveyor axis
           // Conveyor runs along Angle. Width is along perpendicular.
           // Let's assume Angle is direction of flow.
           // Axis parallel to flow:
           const localParallel = dx * Math.cos(-conv.angle) - dy * Math.sin(-conv.angle); // Distance along belt
           const localPerp = dx * Math.sin(-conv.angle) + dy * Math.cos(-conv.angle); // Distance from center line

           const halfLength = conv.width / 2;
           const halfWidth = (conv.height || 50) / 2;

           if (Math.abs(localParallel) < halfWidth && Math.abs(localPerp) < halfLength) {
              const force = conv.force || 10;
              const forceX = Math.cos(conv.angle) * force;
              const forceY = Math.sin(conv.angle) * force;

              m.vx += forceX * dt;
              m.vy += forceY * dt;
           }
        }

        // -- Rotation Damping --
        m.angle += m.omega * dt;
        m.omega *= 0.999; 

        m.vx *= Math.pow(config.friction, dt);
        m.vy *= Math.pow(config.friction, dt);

        if (m.vx*m.vx + m.vy*m.vy < 0.2) {
             m.vx += (Math.random() - 0.5); 
             m.vy += 0.5; 
        }

        // 2. Collisions
        for (const line of linesRef.current) checkLineCollision(m, line);
        for (const dLine of dynamicLines) checkLineCollision(m, dLine, true);
        for (const pin of pinsRef.current) checkPinCollision(m, pin);

        for (let j = i + 1; j < marbles.length; j++) {
           if (!marbles[j].finished) checkMarbleCollision(m, marbles[j]);
        }

        // 3. Finish Line
        if (m.y > finishLineY.current) {
          m.finished = true;
          m.finishTime = Date.now() - startTime.current;
          const finishedSoFar = marbles.filter(b => b.finished).length;
          m.rank = finishedSoFar;
          audio.playPinHit(10);
        }

        if (!m.finished) {
            totalSpeed += Math.sqrt(m.vx*m.vx + m.vy*m.vy + m.omega*m.radius*m.omega*m.radius);
        }
      }
    }

    audio.updateRolling(totalSpeed);

    const activeMarblesList = marbles.filter(m => !m.finished);
    if (activeMarblesList.length > 0) {
      activeMarblesList.sort((a, b) => b.y - a.y);
      const leaders = activeMarblesList.slice(0, 3); 
      const avgY = leaders.reduce((a, b) => a + b.y, 0) / leaders.length;
      cameraY.current += (avgY - cameraY.current - 300) * 0.08;
    } else {
      if (!raceFinished.current) {
        raceFinished.current = true;
        const sorted = [...marbles].sort((a, b) => a.rank - b.rank);
        audio.playFinish(); 
        setTimeout(() => onRaceFinish(sorted), 1000);
      }
    }
  };

  const resolveCollisionPhysics = (ball: Marble, nx: number, ny: number, isBouncy: boolean) => {
    const vDotN = ball.vx * nx + ball.vy * ny;
    if (vDotN > 0) return; 

    const intensity = Math.abs(vDotN);
    if (intensity > 1.0) {
        audio.playBump(intensity);
    }

    const restitution = isBouncy ? 1.5 : config.restitution;
    const jN = -(1 + restitution) * vDotN;
    ball.vx += jN * nx;
    ball.vy += jN * ny;

    const tx = -ny;
    const ty = nx;
    const vDotT = ball.vx * tx + ball.vy * ty;
    const vSurf = vDotT + ball.omega * ball.radius;

    const mass = 1.0;
    const jT_ideal = -vSurf / (3.5 / mass);
    const mu = 0.5;
    const maxJt = mu * Math.abs(jN);

    let jT = jT_ideal;
    if (Math.abs(jT) > maxJt) {
       jT = Math.sign(jT) * maxJt;
    }

    ball.vx += jT * tx;
    ball.vy += jT * ty;
    ball.omega += (2.5 * jT) / (mass * ball.radius);
  };

  const checkLineCollision = (ball: Marble, line: LineSegment, isDynamic = false) => {
    const dx = line.x2 - line.x1;
    const dy = line.y2 - line.y1;
    const lenSq = dx*dx + dy*dy;
    const t = Math.max(0, Math.min(1, ((ball.x - line.x1) * dx + (ball.y - line.y1) * dy) / lenSq));
    const closeX = line.x1 + t * dx;
    const closeY = line.y1 + t * dy;

    const distX = ball.x - closeX;
    const distY = ball.y - closeY;
    const distSq = distX*distX + distY*distY;

    if (distSq < ball.radius * ball.radius) {
      const dist = Math.sqrt(distSq);
      const nx = distX / dist;
      const ny = distY / dist;

      const overlap = ball.radius - dist;
      ball.x += nx * overlap;
      ball.y += ny * overlap;

      const isBouncy = isDynamic && line.type === 'bouncer';
      resolveCollisionPhysics(ball, nx, ny, isBouncy);

      if (isDynamic) {
        ball.vx += (Math.random() - 0.5) * 2;
        ball.vy += (Math.random() - 0.5) * 2;
      }
    }
  };

  const checkPinCollision = (ball: Marble, pin: CircleObstacle) => {
    const dx = ball.x - pin.x;
    const dy = ball.y - pin.y;
    const distSq = dx*dx + dy*dy;
    const minDist = ball.radius + pin.radius;

    if (distSq < minDist * minDist) {
      const dist = Math.sqrt(distSq);
      const nx = dx / dist;
      const ny = dy / dist;

      const overlap = minDist - dist;
      ball.x += nx * overlap;
      ball.y += ny * overlap;

      const isBumper = pin.type === 'bumper';

      const intensity = Math.sqrt(ball.vx*ball.vx + ball.vy*ball.vy);
      if (intensity > 1) {
          audio.playPinHit(intensity);
      }

      resolveCollisionPhysics(ball, nx, ny, isBumper);
    }
  };

  const checkMarbleCollision = (m1: Marble, m2: Marble) => {
    const dx = m2.x - m1.x;
    const dy = m2.y - m1.y;
    const distSq = dx*dx + dy*dy;
    const minDist = m1.radius + m2.radius;

    if (distSq < minDist * minDist) {
      const dist = Math.sqrt(distSq);
      const nx = dx / dist;
      const ny = dy / dist;
      const overlap = (minDist - dist) * 0.5;

      m1.x -= nx * overlap;
      m1.y -= ny * overlap;
      m2.x += nx * overlap;
      m2.y += ny * overlap;

      const dvx = m1.vx - m2.vx;
      const dvy = m1.vy - m2.vy;
      const dot = dvx * nx + dvy * ny;

      if (dot > 0) {
         if (dot > 2) audio.playPinHit(dot * 0.5);

         const impulse = dot * 0.9; 
         m1.vx -= impulse * nx;
         m1.vy -= impulse * ny;
         m2.vx += impulse * nx;
         m2.vy += impulse * ny;
      }
    }
  };

  // --- Initialization ---
  useEffect(() => {
    generateLevel();
    raceFinished.current = false;
    startTime.current = Date.now();
    cameraY.current = 0;
    timeRef.current = 0;

    marblesRef.current = activeMarbles.map((m, index) => ({
      ...m,
      x: COURSE_WIDTH * 0.4 + (Math.random() * COURSE_WIDTH * 0.2),
      y: -50 - (index * 40),
      vx: (Math.random() - 0.5) * 5,
      vy: 0,
      angle: 0,
      omega: 0,
      finished: false,
      rank: 0
    }));

    audio.resume();

  }, [activeMarbles]); 

  // --- Drawing Subroutines ---

  const drawRepulsor = (ctx: CanvasRenderingContext2D, obj: DynamicObstacle) => {
    const pulse = (Math.sin(timeRef.current * obj.speed) + 1) * 0.5;
    const currentRadius = obj.width/2 + pulse * (obj.range! - obj.width/2);

    // Core
    ctx.beginPath();
    ctx.arc(0, 0, obj.width/2, 0, Math.PI * 2);
    ctx.fillStyle = '#8b5cf6'; // Violet
    ctx.fill();

    // Pulse Ring
    ctx.beginPath();
    ctx.arc(0, 0, currentRadius, 0, Math.PI * 2);
    ctx.strokeStyle = `rgba(139, 92, 246, ${1 - pulse})`;
    ctx.lineWidth = 2;
    ctx.stroke();
  };

  const drawConveyor = (ctx: CanvasRenderingContext2D, obj: DynamicObstacle) => {
    const w = obj.width; // length along X (rotated)
    const h = obj.height || 50; // width across Y

    // Rotate 90 deg because logic defined width as length but visual rectangle
    // draws width along X.
    // If angle is flow direction (e.g. down = 90deg), and we want a rect:

    // Draw Base
    ctx.fillStyle = '#334155';
    // Draw centered rect. W is length of path (vertical if 90deg), H is width of path
    // We are in rotated context where X axis is direction of flow.
    // So Rect should be from (-W/2, -H/2) to (W/2, H/2)?
    // My physics logic: Parallel (along flow) < HalfWidth (which was mapped to height in drawing?)
    // Physics: parallel < halfWidth (obj.height). perp < halfLength (obj.width).
    // Let's stick to the visual: X axis is flow. 
    // Rect: x: -obj.height/2, y: -obj.width/2, w: obj.height, h: obj.width.

    // Let's re-align for simplicity: Draw along X axis.
    // Rect from 0, -h/2 to w, h/2 ? No center is x,y.
    // Rect from -w/2, -h/2 to w/2, h/2. (Where w is length of belt)

    ctx.beginPath();
    ctx.rect(-h/2, -w/2, h, w); // Swapped because conveyor angle usually down
    ctx.fillStyle = '#334155';
    ctx.fill();
    ctx.strokeStyle = '#475569';
    ctx.stroke();

    // Arrows
    const offset = (timeRef.current * obj.speed * 50) % 40;
    ctx.fillStyle = 'rgba(255, 255, 255, 0.3)';
    for(let i = -w/2; i < w/2; i+=40) {
        const y = i + offset;
        if (y > w/2) continue;

        ctx.save();
        ctx.translate(0, y); 
        ctx.beginPath();
        ctx.moveTo(-10, -5);
        ctx.lineTo(0, 5);
        ctx.lineTo(10, -5);
        ctx.fill();
        ctx.restore();
    }
  };

  const drawLeaderboard = (ctx: CanvasRenderingContext2D, canvasWidth: number, canvasHeight: number) => {
    // Sort marbles
    const sorted = [...marblesRef.current].sort((a, b) => {
      if (a.finished && b.finished) return a.rank - b.rank;
      if (a.finished) return -1;
      if (b.finished) return 1;
      return b.y - a.y;
    });

    const boxWidth = 140;
    const itemHeight = 24;
    const startX = canvasWidth - boxWidth - 10;
    const startY = 60;

    // Background
    ctx.fillStyle = 'rgba(0, 0, 0, 0.6)';
    ctx.roundRect(startX, startY, boxWidth, sorted.length * itemHeight + 10, 8);
    ctx.fill();
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.1)';
    ctx.stroke();

    ctx.font = 'bold 12px "Roboto Mono"';
    ctx.textAlign = 'left';
    ctx.textBaseline = 'middle';

    sorted.forEach((m, index) => {
       const y = startY + 15 + index * itemHeight;

       // Rank
       ctx.fillStyle = index === 0 ? '#fbbf24' : index === 1 ? '#9ca3af' : index === 2 ? '#b45309' : '#9ca3af';
       ctx.fillText(`${index + 1}º`, startX + 10, y);

       // Color Dot
       ctx.fillStyle = m.color;
       ctx.beginPath();
       ctx.arc(startX + 40, y, 5, 0, Math.PI * 2);
       ctx.fill();

       // Name
       ctx.fillStyle = m.finished ? '#10b981' : '#fff';
       ctx.fillText(m.name, startX + 55, y);

       // Highlight Bet
       if (m.id === betMarbleId) {
          ctx.strokeStyle = '#fbbf24';
          ctx.lineWidth = 1;
          ctx.strokeRect(startX + 2, y - 10, boxWidth - 4, 20);
       }
    });
  };

  // --- Render Loop ---
  const draw = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const { offsetWidth, offsetHeight } = canvas;
    if (canvas.width !== offsetWidth || canvas.height !== offsetHeight) {
      canvas.width = offsetWidth;
      canvas.height = offsetHeight;
    }

    ctx.fillStyle = '#1f2937';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.save();
    const scale = canvas.width / COURSE_WIDTH;
    ctx.scale(scale, scale);
    const camY = Math.max(0, Math.min(cameraY.current, finishLineY.current - canvas.height/scale + 100));
    ctx.translate(0, -camY);

    // Draw Static Lines
    ctx.lineWidth = 4;
    ctx.lineCap = 'round';
    linesRef.current.forEach(l => {
      ctx.strokeStyle = l.type === 'wall' ? '#4b5563' : '#60a5fa';
      if (l.type === 'wall') ctx.lineWidth = 6;
      else ctx.lineWidth = 4;
      ctx.beginPath();
      ctx.moveTo(l.x1, l.y1);
      ctx.lineTo(l.x2, l.y2);
      ctx.stroke();
    });

    // Draw Dynamic Obstacles
    dynamicRef.current.forEach(obj => {
       ctx.save();
       ctx.translate(obj.x, obj.y);
       ctx.rotate(obj.angle);

       if (obj.type === 'fan') {
          // Draw Fan Base
          ctx.fillStyle = '#64748b';
          ctx.fillRect(-10, -obj.width/2, 20, obj.width);

          // Draw Air Flow
          const range = obj.height || 200;
          const gradient = ctx.createLinearGradient(0, 0, range, 0);
          gradient.addColorStop(0, 'rgba(255, 255, 255, 0.4)');
          gradient.addColorStop(1, 'rgba(255, 255, 255, 0)');

          ctx.fillStyle = gradient;
          ctx.fillRect(0, -obj.width/2, range, obj.width);

          // Animated Lines
          ctx.strokeStyle = 'rgba(255, 255, 255, 0.5)';
          ctx.lineWidth = 1;
          const offset = (timeRef.current * 5) % 50;
          for(let i=0; i<3; i++) {
             const yPos = -obj.width/2 + (obj.width/4) * (i+1);
             ctx.beginPath();
             ctx.moveTo(10 + offset, yPos);
             ctx.lineTo(range - 20, yPos);
             ctx.stroke();
          }

       } else if (obj.type === 'repulsor') {
          drawRepulsor(ctx, obj);
       } else if (obj.type === 'conveyor') {
          drawConveyor(ctx, obj);
       } else {
         // Sliders & Spinners
         ctx.strokeStyle = obj.type === 'spinner' ? '#ef4444' : '#f59e0b';
         ctx.lineWidth = 8;
         ctx.beginPath();
         ctx.moveTo(-obj.width/2, 0);
         ctx.lineTo(obj.width/2, 0);
         ctx.stroke();

         if (obj.type === 'spinner') {
           ctx.beginPath();
           ctx.arc(0, 0, 5, 0, Math.PI * 2);
           ctx.fillStyle = '#fff';
           ctx.fill();
         }
       }
       ctx.restore();
    });

    // Draw Pins
    pinsRef.current.forEach(p => {
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.radius, 0, Math.PI * 2);
      ctx.fillStyle = p.type === 'bumper' ? '#f472b6' : '#9ca3af';
      ctx.fill();
    });

    // Draw Finish Line
    ctx.fillStyle = '#10b981';
    ctx.fillRect(0, finishLineY.current, COURSE_WIDTH, 10);
    for(let i=0; i<20; i++) {
        ctx.fillStyle = i%2===0 ? '#fff' : '#000';
        ctx.fillRect(i * (COURSE_WIDTH/20), finishLineY.current, COURSE_WIDTH/20, 10);
    }

    // Draw Marbles
    marblesRef.current.forEach(m => {
      ctx.save();
      ctx.translate(m.x, m.y);
      ctx.rotate(-m.angle); 

      ctx.beginPath();
      ctx.arc(0, 0, m.radius, 0, Math.PI * 2);
      ctx.fillStyle = m.color;
      ctx.shadowColor = 'rgba(0,0,0,0.5)';
      ctx.shadowBlur = 5;
      ctx.fill();
      ctx.shadowBlur = 0;

      ctx.beginPath();
      ctx.moveTo(-m.radius, 0);
      ctx.lineTo(m.radius, 0);
      ctx.strokeStyle = 'rgba(255,255,255,0.5)';
      ctx.lineWidth = 3;
      ctx.stroke();

      ctx.beginPath();
      ctx.moveTo(0, -m.radius);
      ctx.lineTo(0, m.radius);
      ctx.strokeStyle = 'rgba(0,0,0,0.3)';
      ctx.lineWidth = 2;
      ctx.stroke();

      ctx.beginPath();
      ctx.arc(-4, -4, 3, 0, Math.PI * 2);
      ctx.fillStyle = 'rgba(255,255,255,0.7)';
      ctx.fill();

      ctx.restore(); 

      if (m.id === betMarbleId) {
        ctx.strokeStyle = '#fbbf24';
        ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.arc(m.x, m.y, m.radius + 5, 0, Math.PI * 2);
        ctx.stroke();
      }

      if (!m.finished) {
        // Name only, rank badge removed
        ctx.fillStyle = '#fff';
        ctx.font = '10px Arial';
        ctx.textAlign = 'center';
        ctx.fillText(m.name, m.x, m.y - 18);
      }
    });

    ctx.restore(); // Restore from camera transform

    // Draw UI Overlay (Leaderboard) - in screen space (not camera space)
    drawLeaderboard(ctx, canvas.width, canvas.height);
  };

  useEffect(() => {
    const loop = () => {
      update();
      draw();
      requestRef.current = requestAnimationFrame(loop);
    };
    requestRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(requestRef.current!);
  });

  return (
    <canvas ref={canvasRef} className="w-full h-full block" />
  );
};

export default RaceEngine;

import React, { useRef, useEffect } from 'react';
import { Marble, PhysicsConfig, LineSegment, CircleObstacle, DynamicObstacle } from '../types';
import { audio } from '../services/audioService';

interface RaceEngineProps {
  activeMarbles: Marble[];
  config: PhysicsConfig;
  onRaceFinish: (results: Marble[]) => void;
  betMarbleId: number | null;
}

const RaceEngine: React.FC<RaceEngineProps> = ({ activeMarbles, config, onRaceFinish, betMarbleId }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();

  // Physics State (Mutable refs for performance)
  const marblesRef = useRef<Marble[]>([]);
  const linesRef = useRef<LineSegment[]>([]);
  const pinsRef = useRef<CircleObstacle[]>([]);
  const dynamicRef = useRef<DynamicObstacle[]>([]);

  const cameraY = useRef(0);
  const raceFinished = useRef(false);
  const finishLineY = useRef(0);
  const startTime = useRef(0);
  const timeRef = useRef(0);

  // Constants
  const COURSE_WIDTH = 600;

  // --- Level Generation ---
  const generateLevel = () => {
    const lines: LineSegment[] = [];
    const pins: CircleObstacle[] = [];
    const dynamics: DynamicObstacle[] = [];

    // Config
    const segments = 8 + Math.floor(Math.random() * 3);
    const segmentHeight = 450;
    let currentY = 0;

    // 1. Start Funnel
    lines.push({ x1: 0, y1: 0, x2: COURSE_WIDTH * 0.4, y2: 150, type: 'wall' });
    lines.push({ x1: COURSE_WIDTH, y1: 0, x2: COURSE_WIDTH * 0.6, y2: 150, type: 'wall' });
    lines.push({ x1: COURSE_WIDTH * 0.4, y1: 150, x2: COURSE_WIDTH * 0.4, y2: 180, type: 'wall' });
    lines.push({ x1: COURSE_WIDTH * 0.6, y1: 150, x2: COURSE_WIDTH * 0.6, y2: 180, type: 'wall' });

    currentY = 220;

    // 2. Procedural Segments
    for (let i = 0; i < segments; i++) {
      const type = Math.random();

      // Outer Walls
      lines.push({ x1: 0, y1: currentY - 50, x2: 0, y2: currentY + segmentHeight, type: 'wall' });
      lines.push({ x1: COURSE_WIDTH, y1: currentY - 50, x2: COURSE_WIDTH, y2: currentY + segmentHeight, type: 'wall' });

      if (type < 0.15) {
        // --- PROPELLERS (Spinners) ---
        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 100, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 100, type: 'floor' });

        dynamics.push({
          id: `spin_${i}_1`,
          type: 'spinner',
          x: COURSE_WIDTH * 0.35,
          y: currentY + 250,
          width: 140,
          angle: 0,
          speed: 0.1,
        });
        dynamics.push({
          id: `spin_${i}_2`,
          type: 'spinner',
          x: COURSE_WIDTH * 0.65,
          y: currentY + 350,
          width: 140,
          angle: Math.PI / 2,
          speed: -0.1,
        });

      } else if (type < 0.3) {
        // --- REPULSORS (New) ---
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.3, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.7, y2: currentY + 150, type: 'floor' });

        // Central Repulsor
        dynamics.push({
          id: `repulse_${i}`,
          type: 'repulsor',
          x: COURSE_WIDTH / 2,
          y: currentY + 300,
          width: 50, // core radius
          range: 120, // pulse max radius
          angle: 0,
          speed: 0.1, // pulse speed
          force: 2.5
        });

      } else if (type < 0.45) {
        // --- CONVEYOR BELTS (New) ---
        // Funnel into a fast conveyor
        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.4, y2: currentY + 100, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.6, y2: currentY + 100, type: 'wall' });

        // Conveyor Strip
        dynamics.push({
          id: `conveyor_${i}`,
          type: 'conveyor',
          x: COURSE_WIDTH * 0.5,
          y: currentY + 250,
          width: 200, // length
          height: 100, // width of path
          angle: Math.PI / 2, // Downwards
          speed: 0.1, // Animation speed
          force: 15 // Acceleration
        });

      } else if (type < 0.6) {
        // --- MOVING ELEVATORS ---
        const isVertical = Math.random() > 0.5;

        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.2, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.8, y2: currentY + 150, type: 'floor' });

        if (isVertical) {
           dynamics.push({
             id: `slide_v_${i}`,
             type: 'slider_v',
             x: COURSE_WIDTH / 2,
             y: currentY + 200,
             width: 200,
             angle: 0,
             speed: 1, 
             range: 100,
             initialX: COURSE_WIDTH / 2,
             initialY: currentY + 250
           });
        } else {
           dynamics.push({
            id: `slide_h_${i}`,
            type: 'slider_h',
            x: COURSE_WIDTH / 2,
            y: currentY + 250,
            width: 250,
            angle: 0,
            speed: 2,
            range: 150,
            initialX: COURSE_WIDTH / 2,
            initialY: currentY + 250
          });
        }

      } else if (type < 0.75) {
        // --- WIND CANNONS ---
        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 100, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 100, type: 'floor' });

        dynamics.push({
          id: `fan_${i}_1`,
          type: 'fan',
          x: 20, 
          y: currentY + 250,
          width: 40,
          height: 300, 
          angle: 0, 
          speed: 0,
          force: 0.6
        });

        pins.push({ x: COURSE_WIDTH * 0.6, y: currentY + 250, radius: 20, type: 'bumper' });

      } else {
         // --- CLASSIC SLALOM ---
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.6, y2: currentY + 180, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 250, x2: COURSE_WIDTH * 0.4, y2: currentY + 380, type: 'floor' });
        pins.push({ x: COURSE_WIDTH * 0.8, y: currentY + 200, radius: 15, type: 'bumper' });
        pins.push({ x: COURSE_WIDTH * 0.2, y: currentY + 400, radius: 15, type: 'bumper' });
      }

      currentY += segmentHeight;
    }

    // 3. Finish Area
    lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 200, type: 'floor' });
    lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 200, type: 'floor' });

    finishLineY.current = currentY + 250;

    linesRef.current = lines;
    pinsRef.current = pins;
    dynamicRef.current = dynamics;
  };

  // --- Physics Logic ---
  const update = () => {
    if (raceFinished.current) {
        audio.updateRolling(0); 
        return;
    }

    const STEPS = 4;
    const dt = 1 / STEPS;
    timeRef.current += 1;

    const marbles = marblesRef.current;
    const dynamicObjs = dynamicRef.current;

    let totalSpeed = 0;

    // Separate dynamic types for optimized loops
    const fans: DynamicObstacle[] = [];
    const repulsors: DynamicObstacle[] = [];
    const conveyors: DynamicObstacle[] = [];
    const solidDynamics: DynamicObstacle[] = [];

    dynamicObjs.forEach(obj => {
      if (obj.type === 'fan') {
        fans.push(obj);
        return;
      }
      if (obj.type === 'repulsor') {
        repulsors.push(obj);
        return;
      }
      if (obj.type === 'conveyor') {
        conveyors.push(obj);
        return;
      }

      solidDynamics.push(obj);

      // Animation updates for solids
      if (obj.type === 'spinner') {
        obj.angle += obj.speed;
      } else if (obj.type === 'slider_h') {
        obj.x = obj.initialX! + Math.sin(timeRef.current * 0.02) * (obj.range || 100);
      } else if (obj.type === 'slider_v') {
        obj.y = obj.initialY! + Math.sin(timeRef.current * 0.015) * (obj.range || 80);
      }
    });

    // Generate collision lines for solids
    const dynamicLines: LineSegment[] = [];
    solidDynamics.forEach(obj => {
      const halfW = obj.width / 2;
      const dx = Math.cos(obj.angle) * halfW;
      const dy = Math.sin(obj.angle) * halfW;
      dynamicLines.push({
        x1: obj.x - dx, y1: obj.y - dy,
        x2: obj.x + dx, y2: obj.y + dy,
        type: obj.type === 'spinner' ? 'bouncer' : 'floor'
      });
    });

    for (let step = 0; step < STEPS; step++) {
      for (let i = 0; i < marbles.length; i++) {
        const m = marbles[i];
        if (m.finished) continue;

        // 1. Gravity & Movement
        m.vy += config.gravity * dt;
        m.x += m.vx * dt;
        m.y += m.vy * dt;

        // -- Force Fields & Zones --

        // Fan Physics
        for (const fan of fans) {
          const dx = m.x - fan.x;
          const dy = m.y - fan.y;
          const localX = dx * Math.cos(-fan.angle) - dy * Math.sin(-fan.angle);
          const localY = dx * Math.sin(-fan.angle) + dy * Math.cos(-fan.angle);
          const halfWidth = fan.width / 2; 
          const range = fan.height || 200;

          if (localX > 0 && localX < range && Math.abs(localY) < halfWidth) {
             const force = fan.force || 0.5;
             const forceX = Math.cos(fan.angle) * force;
             const forceY = Math.sin(fan.angle) * force;
             m.vx += forceX * dt;
             m.vy += forceY * dt;
          }
        }

        // Repulsor Physics
        for (const rep of repulsors) {
          const dx = m.x - rep.x;
          const dy = m.y - rep.y;
          const distSq = dx*dx + dy*dy;
          const range = rep.range || 100;

          if (distSq < range * range) {
             const dist = Math.sqrt(distSq);
             const nx = dx / dist;
             const ny = dy / dist;

             // Pulse effect logic: Stronger at center, varies with time
             const pulse = (Math.sin(timeRef.current * rep.speed) + 1) * 0.5;
             const force = (rep.force || 1) * (1 - dist/range) * (0.5 + pulse);

             m.vx += nx * force * dt * 50;
             m.vy += ny * force * dt * 50;
          }
        }

        // Conveyor Physics
        for (const conv of conveyors) {
           // Define conveyor box (center x,y, width=length, height=width)
           const dx = m.x - conv.x;
           const dy = m.y - conv.y;

           // Rotate to align with conveyor axis
           // Conveyor runs along Angle. Width is along perpendicular.
           // Let's assume Angle is direction of flow.
           // Axis parallel to flow:
           const localParallel = dx * Math.cos(-conv.angle) - dy * Math.sin(-conv.angle); // Distance along belt
           const localPerp = dx * Math.sin(-conv.angle) + dy * Math.cos(-conv.angle); // Distance from center line

           const halfLength = conv.width / 2;
           const halfWidth = (conv.height || 50) / 2;

           if (Math.abs(localParallel) < halfWidth && Math.abs(localPerp) < halfLength) {
              const force = conv.force || 10;
              const forceX = Math.cos(conv.angle) * force;
              const forceY = Math.sin(conv.angle) * force;

              m.vx += forceX * dt;
              m.vy += forceY * dt;
           }
        }

        // -- Rotation Damping --
        m.angle += m.omega * dt;
        m.omega *= 0.999; 

        m.vx *= Math.pow(config.friction, dt);
        m.vy *= Math.pow(config.friction, dt);

        if (m.vx*m.vx + m.vy*m.vy < 0.2) {
             m.vx += (Math.random() - 0.5); 
             m.vy += 0.5; 
        }

        // 2. Collisions
        for (const line of linesRef.current) checkLineCollision(m, line);
        for (const dLine of dynamicLines) checkLineCollision(m, dLine, true);
        for (const pin of pinsRef.current) checkPinCollision(m, pin);

        for (let j = i + 1; j < marbles.length; j++) {
           if (!marbles[j].finished) checkMarbleCollision(m, marbles[j]);
        }

        // 3. Finish Line
        if (m.y > finishLineY.current) {
          m.finished = true;
          m.finishTime = Date.now() - startTime.current;
          const finishedSoFar = marbles.filter(b => b.finished).length;
          m.rank = finishedSoFar;
          audio.playPinHit(10);
        }

        if (!m.finished) {
            totalSpeed += Math.sqrt(m.vx*m.vx + m.vy*m.vy + m.omega*m.radius*m.omega*m.radius);
        }
      }
    }

    audio.updateRolling(totalSpeed);

    const activeMarblesList = marbles.filter(m => !m.finished);
    if (activeMarblesList.length > 0) {
      activeMarblesList.sort((a, b) => b.y - a.y);
      const leaders = activeMarblesList.slice(0, 3); 
      const avgY = leaders.reduce((a, b) => a + b.y, 0) / leaders.length;
      cameraY.current += (avgY - cameraY.current - 300) * 0.08;
    } else {
      if (!raceFinished.current) {
        raceFinished.current = true;
        const sorted = [...marbles].sort((a, b) => a.rank - b.rank);
        audio.playFinish(); 
        setTimeout(() => onRaceFinish(sorted), 1000);
      }
    }
  };

  const resolveCollisionPhysics = (ball: Marble, nx: number, ny: number, isBouncy: boolean) => {
    const vDotN = ball.vx * nx + ball.vy * ny;
    if (vDotN > 0) return; 

    const intensity = Math.abs(vDotN);
    if (intensity > 1.0) {
        audio.playBump(intensity);
    }

    const restitution = isBouncy ? 1.5 : config.restitution;
    const jN = -(1 + restitution) * vDotN;
    ball.vx += jN * nx;
    ball.vy += jN * ny;

    const tx = -ny;
    const ty = nx;
    const vDotT = ball.vx * tx + ball.vy * ty;
    const vSurf = vDotT + ball.omega * ball.radius;

    const mass = 1.0;
    const jT_ideal = -vSurf / (3.5 / mass);
    const mu = 0.5;
    const maxJt = mu * Math.abs(jN);

    let jT = jT_ideal;
    if (Math.abs(jT) > maxJt) {
       jT = Math.sign(jT) * maxJt;
    }

    ball.vx += jT * tx;
    ball.vy += jT * ty;
    ball.omega += (2.5 * jT) / (mass * ball.radius);
  };

  const checkLineCollision = (ball: Marble, line: LineSegment, isDynamic = false) => {
    const dx = line.x2 - line.x1;
    const dy = line.y2 - line.y1;
    const lenSq = dx*dx + dy*dy;
    const t = Math.max(0, Math.min(1, ((ball.x - line.x1) * dx + (ball.y - line.y1) * dy) / lenSq));
    const closeX = line.x1 + t * dx;
    const closeY = line.y1 + t * dy;

    const distX = ball.x - closeX;
    const distY = ball.y - closeY;
    const distSq = distX*distX + distY*distY;

    if (distSq < ball.radius * ball.radius) {
      const dist = Math.sqrt(distSq);
      const nx = distX / dist;
      const ny = distY / dist;

      const overlap = ball.radius - dist;
      ball.x += nx * overlap;
      ball.y += ny * overlap;

      const isBouncy = isDynamic && line.type === 'bouncer';
      resolveCollisionPhysics(ball, nx, ny, isBouncy);

      if (isDynamic) {
        ball.vx += (Math.random() - 0.5) * 2;
        ball.vy += (Math.random() - 0.5) * 2;
      }
    }
  };

  const checkPinCollision = (ball: Marble, pin: CircleObstacle) => {
    const dx = ball.x - pin.x;
    const dy = ball.y - pin.y;
    const distSq = dx*dx + dy*dy;
    const minDist = ball.radius + pin.radius;

    if (distSq < minDist * minDist) {
      const dist = Math.sqrt(distSq);
      const nx = dx / dist;
      const ny = dy / dist;

      const overlap = minDist - dist;
      ball.x += nx * overlap;
      ball.y += ny * overlap;

      const isBumper = pin.type === 'bumper';

      const intensity = Math.sqrt(ball.vx*ball.vx + ball.vy*ball.vy);
      if (intensity > 1) {
          audio.playPinHit(intensity);
      }

      resolveCollisionPhysics(ball, nx, ny, isBumper);
    }
  };

  const checkMarbleCollision = (m1: Marble, m2: Marble) => {
    const dx = m2.x - m1.x;
    const dy = m2.y - m1.y;
    const distSq = dx*dx + dy*dy;
    const minDist = m1.radius + m2.radius;

    if (distSq < minDist * minDist) {
      const dist = Math.sqrt(distSq);
      const nx = dx / dist;
      const ny = dy / dist;
      const overlap = (minDist - dist) * 0.5;

      m1.x -= nx * overlap;
      m1.y -= ny * overlap;
      m2.x += nx * overlap;
      m2.y += ny * overlap;

      const dvx = m1.vx - m2.vx;
      const dvy = m1.vy - m2.vy;
      const dot = dvx * nx + dvy * ny;

      if (dot > 0) {
         if (dot > 2) audio.playPinHit(dot * 0.5);

         const impulse = dot * 0.9; 
         m1.vx -= impulse * nx;
         m1.vy -= impulse * ny;
         m2.vx += impulse * nx;
         m2.vy += impulse * ny;
      }
    }
  };

  // --- Initialization ---
  useEffect(() => {
    generateLevel();
    raceFinished.current = false;
    startTime.current = Date.now();
    cameraY.current = 0;
    timeRef.current = 0;

    marblesRef.current = activeMarbles.map((m, index) => ({
      ...m,
      x: COURSE_WIDTH * 0.4 + (Math.random() * COURSE_WIDTH * 0.2),
      y: -50 - (index * 40),
      vx: (Math.random() - 0.5) * 5,
      vy: 0,
      angle: 0,
      omega: 0,
      finished: false,
      rank: 0
    }));

    audio.resume();

  }, [activeMarbles]); 

  // --- Drawing Subroutines ---

  const drawRepulsor = (ctx: CanvasRenderingContext2D, obj: DynamicObstacle) => {
    const pulse = (Math.sin(timeRef.current * obj.speed) + 1) * 0.5;
    const currentRadius = obj.width/2 + pulse * (obj.range! - obj.width/2);

    // Core
    ctx.beginPath();
    ctx.arc(0, 0, obj.width/2, 0, Math.PI * 2);
    ctx.fillStyle = '#8b5cf6'; // Violet
    ctx.fill();

    // Pulse Ring
    ctx.beginPath();
    ctx.arc(0, 0, currentRadius, 0, Math.PI * 2);
    ctx.strokeStyle = `rgba(139, 92, 246, ${1 - pulse})`;
    ctx.lineWidth = 2;
    ctx.stroke();
  };

  const drawConveyor = (ctx: CanvasRenderingContext2D, obj: DynamicObstacle) => {
    const w = obj.width; // length along X (rotated)
    const h = obj.height || 50; // width across Y

    // Rotate 90 deg because logic defined width as length but visual rectangle
    // draws width along X.
    // If angle is flow direction (e.g. down = 90deg), and we want a rect:

    // Draw Base
    ctx.fillStyle = '#334155';
    // Draw centered rect. W is length of path (vertical if 90deg), H is width of path
    // We are in rotated context where X axis is direction of flow.
    // So Rect should be from (-W/2, -H/2) to (W/2, H/2)?
    // My physics logic: Parallel (along flow) < HalfWidth (which was mapped to height in drawing?)
    // Physics: parallel < halfWidth (obj.height). perp < halfLength (obj.width).
    // Let's stick to the visual: X axis is flow. 
    // Rect: x: -obj.height/2, y: -obj.width/2, w: obj.height, h: obj.width.

    // Let's re-align for simplicity: Draw along X axis.
    // Rect from 0, -h/2 to w, h/2 ? No center is x,y.
    // Rect from -w/2, -h/2 to w/2, h/2. (Where w is length of belt)

    ctx.beginPath();
    ctx.rect(-h/2, -w/2, h, w); // Swapped because conveyor angle usually down
    ctx.fillStyle = '#334155';
    ctx.fill();
    ctx.strokeStyle = '#475569';
    ctx.stroke();

    // Arrows
    const offset = (timeRef.current * obj.speed * 50) % 40;
    ctx.fillStyle = 'rgba(255, 255, 255, 0.3)';
    for(let i = -w/2; i < w/2; i+=40) {
        const y = i + offset;
        if (y > w/2) continue;

        ctx.save();
        ctx.translate(0, y); 
        ctx.beginPath();
        ctx.moveTo(-10, -5);
        ctx.lineTo(0, 5);
        ctx.lineTo(10, -5);
        ctx.fill();
        ctx.restore();
    }
  };

  const drawLeaderboard = (ctx: CanvasRenderingContext2D, canvasWidth: number, canvasHeight: number) => {
    // Sort marbles
    const sorted = [...marblesRef.current].sort((a, b) => {
      if (a.finished && b.finished) return a.rank - b.rank;
      if (a.finished) return -1;
      if (b.finished) return 1;
      return b.y - a.y;
    });

    const boxWidth = 110; // Reduced width
    const itemHeight = 18; // Reduced height
    const startX = canvasWidth - boxWidth - 10;
    const startY = 110; // Moved down to avoid top overlap

    // Background
    ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
    ctx.roundRect(startX, startY, boxWidth, sorted.length * itemHeight + 10, 6);
    ctx.fill();
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.1)';
    ctx.lineWidth = 1;
    ctx.stroke();

    ctx.font = 'bold 10px "Roboto Mono"'; // Smaller font
    ctx.textAlign = 'left';
    ctx.textBaseline = 'middle';

    sorted.forEach((m, index) => {
       const y = startY + 12 + index * itemHeight;

       // Rank
       ctx.fillStyle = index === 0 ? '#fbbf24' : index === 1 ? '#9ca3af' : index === 2 ? '#b45309' : '#6b7280';
       ctx.fillText(`${index + 1}.`, startX + 8, y);

       // Color Dot
       ctx.fillStyle = m.color;
       ctx.beginPath();
       ctx.arc(startX + 30, y, 4, 0, Math.PI * 2);
       ctx.fill();

       // Name
       ctx.fillStyle = m.finished ? '#10b981' : '#e5e7eb';
       ctx.fillText(m.name, startX + 42, y);

       // Highlight Bet
       if (m.id === betMarbleId) {
          ctx.strokeStyle = '#fbbf24';
          ctx.lineWidth = 1;
          ctx.strokeRect(startX + 2, y - 9, boxWidth - 4, 18);
       }
    });
  };

  // --- Render Loop ---
  const draw = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const { offsetWidth, offsetHeight } = canvas;
    if (canvas.width !== offsetWidth || canvas.height !== offsetHeight) {
      canvas.width = offsetWidth;
      canvas.height = offsetHeight;
    }

    ctx.fillStyle = '#1f2937';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.save();
    const scale = canvas.width / COURSE_WIDTH;
    ctx.scale(scale, scale);
    const camY = Math.max(0, Math.min(cameraY.current, finishLineY.current - canvas.height/scale + 100));
    ctx.translate(0, -camY);

    // Draw Static Lines
    ctx.lineWidth = 4;
    ctx.lineCap = 'round';
    linesRef.current.forEach(l => {
      ctx.strokeStyle = l.type === 'wall' ? '#4b5563' : '#60a5fa';
      if (l.type === 'wall') ctx.lineWidth = 6;
      else ctx.lineWidth = 4;
      ctx.beginPath();
      ctx.moveTo(l.x1, l.y1);
      ctx.lineTo(l.x2, l.y2);
      ctx.stroke();
    });

    // Draw Dynamic Obstacles
    dynamicRef.current.forEach(obj => {
       ctx.save();
       ctx.translate(obj.x, obj.y);
       ctx.rotate(obj.angle);

       if (obj.type === 'fan') {
          // Draw Fan Base
          ctx.fillStyle = '#64748b';
          ctx.fillRect(-10, -obj.width/2, 20, obj.width);

          // Draw Air Flow
          const range = obj.height || 200;
          const gradient = ctx.createLinearGradient(0, 0, range, 0);
          gradient.addColorStop(0, 'rgba(255, 255, 255, 0.4)');
          gradient.addColorStop(1, 'rgba(255, 255, 255, 0)');

          ctx.fillStyle = gradient;
          ctx.fillRect(0, -obj.width/2, range, obj.width);

          // Animated Lines
          ctx.strokeStyle = 'rgba(255, 255, 255, 0.5)';
          ctx.lineWidth = 1;
          const offset = (timeRef.current * 5) % 50;
          for(let i=0; i<3; i++) {
             const yPos = -obj.width/2 + (obj.width/4) * (i+1);
             ctx.beginPath();
             ctx.moveTo(10 + offset, yPos);
             ctx.lineTo(range - 20, yPos);
             ctx.stroke();
          }

       } else if (obj.type === 'repulsor') {
          drawRepulsor(ctx, obj);
       } else if (obj.type === 'conveyor') {
          drawConveyor(ctx, obj);
       } else {
         // Sliders & Spinners
         ctx.strokeStyle = obj.type === 'spinner' ? '#ef4444' : '#f59e0b';
         ctx.lineWidth = 8;
         ctx.beginPath();
         ctx.moveTo(-obj.width/2, 0);
         ctx.lineTo(obj.width/2, 0);
         ctx.stroke();

         if (obj.type === 'spinner') {
           ctx.beginPath();
           ctx.arc(0, 0, 5, 0, Math.PI * 2);
           ctx.fillStyle = '#fff';
           ctx.fill();
         }
       }
       ctx.restore();
    });

    // Draw Pins
    pinsRef.current.forEach(p => {
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.radius, 0, Math.PI * 2);
      ctx.fillStyle = p.type === 'bumper' ? '#f472b6' : '#9ca3af';
      ctx.fill();
    });

    // Draw Finish Line
    ctx.fillStyle = '#10b981';
    ctx.fillRect(0, finishLineY.current, COURSE_WIDTH, 10);
    for(let i=0; i<20; i++) {
        ctx.fillStyle = i%2===0 ? '#fff' : '#000';
        ctx.fillRect(i * (COURSE_WIDTH/20), finishLineY.current, COURSE_WIDTH/20, 10);
    }

    // Draw Marbles
    marblesRef.current.forEach(m => {
      ctx.save();
      ctx.translate(m.x, m.y);
      ctx.rotate(-m.angle); 

      ctx.beginPath();
      ctx.arc(0, 0, m.radius, 0, Math.PI * 2);
      ctx.fillStyle = m.color;
      ctx.shadowColor = 'rgba(0,0,0,0.5)';
      ctx.shadowBlur = 5;
      ctx.fill();
      ctx.shadowBlur = 0;

      ctx.beginPath();
      ctx.moveTo(-m.radius, 0);
      ctx.lineTo(m.radius, 0);
      ctx.strokeStyle = 'rgba(255,255,255,0.5)';
      ctx.lineWidth = 3;
      ctx.stroke();

      ctx.beginPath();
      ctx.moveTo(0, -m.radius);
      ctx.lineTo(0, m.radius);
      ctx.strokeStyle = 'rgba(0,0,0,0.3)';
      ctx.lineWidth = 2;
      ctx.stroke();

      ctx.beginPath();
      ctx.arc(-4, -4, 3, 0, Math.PI * 2);
      ctx.fillStyle = 'rgba(255,255,255,0.7)';
      ctx.fill();

      ctx.restore(); 

      if (m.id === betMarbleId) {
        ctx.strokeStyle = '#fbbf24';
        ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.arc(m.x, m.y, m.radius + 5, 0, Math.PI * 2);
        ctx.stroke();
      }

      if (!m.finished) {
        // Name only, rank badge removed
        ctx.fillStyle = '#fff';
        ctx.font = '10px Arial';
        ctx.textAlign = 'center';
        ctx.fillText(m.name, m.x, m.y - 18);
      }
    });

    ctx.restore(); // Restore from camera transform

    // Draw UI Overlay (Leaderboard) - in screen space (not camera space)
    drawLeaderboard(ctx, canvas.width, canvas.height);
  };

  useEffect(() => {
    const loop = () => {
      update();
      draw();
      requestRef.current = requestAnimationFrame(loop);
    };
    requestRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(requestRef.current!);
  });

  return (
    <canvas ref={canvasRef} className="w-full h-full block" />
  );
};

export default RaceEngine;

export interface Marble {
  id: number;
  color: string;
  name: string;
  x: number;
  y: number;
  vx: number;
  vy: number;
  radius: number;
  angle: number; // Rotation angle in radians
  omega: number; // Angular velocity in radians/tick
  score: number; // For Points Mode
  finished: boolean;
  finishTime: number;
  rank: number; // 0 if not finished
}

export interface LineSegment {
  x1: number;
  y1: number;
  x2: number;
  y2: number;
  type: 'wall' | 'floor' | 'bouncer';
}

export interface CircleObstacle {
  x: number;
  y: number;
  radius: number;
  type: 'pin' | 'bumper';
}

export interface DynamicObstacle {
  id: string;
  type: 'spinner' | 'slider_h' | 'slider_v' | 'fan' | 'repulsor' | 'conveyor' | 'laser' | 'teleporter';
  x: number;
  y: number;
  width: number; // Length of the line/blade, width of fan source, or portal radius
  height?: number; // Range of the fan wind or laser length
  angle: number;
  speed: number;
  range?: number; // For sliders or repulsor pulse radius
  initialX?: number;
  initialY?: number;
  force?: number; // Wind strength, Repulsor force, or Laser push
  destX?: number; // For teleporter exit
  destY?: number; // For teleporter exit
  active?: boolean; // For laser toggle state
  timer?: number; // Internal timer for laser switching
}

export interface PhysicsConfig {
  gravity: number;
  restitution: number; // Bounciness 0.1 to 0.9
  friction: number;
}

export type GameMode = 'elimination' | 'points';

export interface GameState {
  gameMode: GameMode;
  phase: 'betting' | 'racing' | 'round_result' | 'champion';
  round: number; // Starts at 1
  totalRounds: number; // 9 for elimination, 5 for points
  marbles: Marble[]; // All marbles
  activeMarbleIds: number[]; // IDs of marbles still in tournament
  betMarbleId: number | null;
  lastEliminatedId: number | null;
  roundPoints: Record<number, number>; // Points earned in the current round (marbleId -> points)
}

import React, { useRef, useEffect } from 'react';
import { Marble, PhysicsConfig, LineSegment, CircleObstacle, DynamicObstacle } from '../types';
import { audio } from '../services/audioService';

interface RaceEngineProps {
  activeMarbles: Marble[];
  config: PhysicsConfig;
  onRaceFinish: (results: Marble[]) => void;
  betMarbleId: number | null;
}

const RaceEngine: React.FC<RaceEngineProps> = ({ activeMarbles, config, onRaceFinish, betMarbleId }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();

  // Physics State (Mutable refs for performance)
  const marblesRef = useRef<Marble[]>([]);
  const linesRef = useRef<LineSegment[]>([]);
  const pinsRef = useRef<CircleObstacle[]>([]);
  const dynamicRef = useRef<DynamicObstacle[]>([]);
  const teleportCooldowns = useRef<Record<number, number>>({}); // marbleId -> timestamp

  const cameraY = useRef(0);
  const raceFinished = useRef(false);
  const finishLineY = useRef(0);
  const startTime = useRef(0);
  const timeRef = useRef(0);

  // Constants
  const COURSE_WIDTH = 600;

  // --- Level Generation ---
  const generateLevel = () => {
    const lines: LineSegment[] = [];
    const pins: CircleObstacle[] = [];
    const dynamics: DynamicObstacle[] = [];

    // Config
    const segments = 10 + Math.floor(Math.random() * 3);
    const segmentHeight = 450;
    let currentY = 0;

    // 1. Start Funnel
    lines.push({ x1: 0, y1: 0, x2: COURSE_WIDTH * 0.4, y2: 150, type: 'wall' });
    lines.push({ x1: COURSE_WIDTH, y1: 0, x2: COURSE_WIDTH * 0.6, y2: 150, type: 'wall' });
    lines.push({ x1: COURSE_WIDTH * 0.4, y1: 150, x2: COURSE_WIDTH * 0.4, y2: 180, type: 'wall' });
    lines.push({ x1: COURSE_WIDTH * 0.6, y1: 150, x2: COURSE_WIDTH * 0.6, y2: 180, type: 'wall' });

    currentY = 220;

    // 2. Procedural Segments
    for (let i = 0; i < segments; i++) {
      const type = Math.random();

      // Outer Walls
      lines.push({ x1: 0, y1: currentY - 50, x2: 0, y2: currentY + segmentHeight, type: 'wall' });
      lines.push({ x1: COURSE_WIDTH, y1: currentY - 50, x2: COURSE_WIDTH, y2: currentY + segmentHeight, type: 'wall' });

      if (type < 0.12) {
        // --- PROPELLERS (Spinners) ---
        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 100, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 100, type: 'floor' });

        dynamics.push({
          id: `spin_${i}_1`,
          type: 'spinner',
          x: COURSE_WIDTH * 0.35,
          y: currentY + 250,
          width: 140,
          angle: 0,
          speed: 0.1,
        });
        dynamics.push({
          id: `spin_${i}_2`,
          type: 'spinner',
          x: COURSE_WIDTH * 0.65,
          y: currentY + 350,
          width: 140,
          angle: Math.PI / 2,
          speed: -0.1,
        });

      } else if (type < 0.24) {
        // --- REPULSORS ---
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.3, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.7, y2: currentY + 150, type: 'floor' });

        dynamics.push({
          id: `repulse_${i}`,
          type: 'repulsor',
          x: COURSE_WIDTH / 2,
          y: currentY + 300,
          width: 50, 
          range: 120, 
          angle: 0,
          speed: 0.1, 
          force: 2.5
        });

      } else if (type < 0.36) {
        // --- CONVEYOR BELTS ---
        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.4, y2: currentY + 100, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.6, y2: currentY + 100, type: 'wall' });

        dynamics.push({
          id: `conveyor_${i}`,
          type: 'conveyor',
          x: COURSE_WIDTH * 0.5,
          y: currentY + 250,
          width: 200, 
          height: 100, 
          angle: Math.PI / 2, // Downwards
          speed: 0.1, 
          force: 15 
        });

      } else if (type < 0.48) {
        // --- LASER CANNONS (New) ---
        // Narrow path with a laser across it
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.3, y2: currentY + 150, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.7, y2: currentY + 150, type: 'wall' });

        dynamics.push({
          id: `laser_${i}`,
          type: 'laser',
          x: COURSE_WIDTH * 0.1, // Source on left
          y: currentY + 300,
          width: 0, 
          height: COURSE_WIDTH * 0.8, // Length of beam
          angle: 0, // Horizontal
          speed: 0,
          force: 20, // Strong push
          active: true,
          timer: 0
        });

        // Laser source visual box (wall)
        lines.push({ x1: 0, y1: currentY + 280, x2: COURSE_WIDTH * 0.15, y2: currentY + 320, type: 'wall' });

      } else if (type < 0.6) {
        // --- TELEPORTERS (New) ---
        // Entrance top, Exit bottom
        const entranceX = COURSE_WIDTH * (0.2 + Math.random() * 0.6);
        const exitX = COURSE_WIDTH * (0.2 + Math.random() * 0.6);

        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.2, y2: currentY + 100, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.8, y2: currentY + 100, type: 'floor' });

        dynamics.push({
          id: `teleport_${i}`,
          type: 'teleporter',
          x: entranceX,
          y: currentY + 150,
          width: 40, // Radius
          destX: exitX,
          destY: currentY + 350,
          angle: 0,
          speed: 0.05
        });

        // Add some obstacles around the exit to make it interesting
        pins.push({ x: exitX + 60, y: currentY + 350, radius: 15, type: 'bumper' });
        pins.push({ x: exitX - 60, y: currentY + 350, radius: 15, type: 'bumper' });

      } else if (type < 0.75) {
        // --- MOVING ELEVATORS ---
        const isVertical = Math.random() > 0.5;

        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.2, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.8, y2: currentY + 150, type: 'floor' });

        if (isVertical) {
           dynamics.push({
             id: `slide_v_${i}`,
             type: 'slider_v',
             x: COURSE_WIDTH / 2,
             y: currentY + 200,
             width: 200,
             angle: 0,
             speed: 1, 
             range: 100,
             initialX: COURSE_WIDTH / 2,
             initialY: currentY + 250
           });
        } else {
           dynamics.push({
            id: `slide_h_${i}`,
            type: 'slider_h',
            x: COURSE_WIDTH / 2,
            y: currentY + 250,
            width: 250,
            angle: 0,
            speed: 2,
            range: 150,
            initialX: COURSE_WIDTH / 2,
            initialY: currentY + 250
          });
        }

      } else if (type < 0.85) {
        // --- WIND CANNONS ---
        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 100, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 100, type: 'floor' });

        dynamics.push({
          id: `fan_${i}_1`,
          type: 'fan',
          x: 20, 
          y: currentY + 250,
          width: 40,
          height: 300, 
          angle: 0, 
          speed: 0,
          force: 0.6
        });

        pins.push({ x: COURSE_WIDTH * 0.6, y: currentY + 250, radius: 20, type: 'bumper' });

      } else {
         // --- CLASSIC SLALOM ---
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.6, y2: currentY + 180, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 250, x2: COURSE_WIDTH * 0.4, y2: currentY + 380, type: 'floor' });
        pins.push({ x: COURSE_WIDTH * 0.8, y: currentY + 200, radius: 15, type: 'bumper' });
        pins.push({ x: COURSE_WIDTH * 0.2, y: currentY + 400, radius: 15, type: 'bumper' });
      }

      currentY += segmentHeight;
    }

    // 3. Finish Area
    lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 200, type: 'floor' });
    lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 200, type: 'floor' });

    finishLineY.current = currentY + 250;

    linesRef.current = lines;
    pinsRef.current = pins;
    dynamicRef.current = dynamics;
  };

  // --- Physics Logic ---
  const update = () => {
    if (raceFinished.current) {
        audio.updateRolling(0); 
        return;
    }

    const STEPS = 4;
    const dt = 1 / STEPS;
    timeRef.current += 1;
    const now = Date.now();

    const marbles = marblesRef.current;
    const dynamicObjs = dynamicRef.current;

    let totalSpeed = 0;

    // --- MERCY RULE CHECK ---
    // If n-1 marbles have finished, end the race immediately.
    const activeMarblesCount = marbles.filter(m => !m.finished).length;
    const totalMarbles = marbles.length;

    if (totalMarbles > 1 && activeMarblesCount === 1) {
        // Find the last straggler
        const loser = marbles.find(m => !m.finished);
        if (loser) {
            loser.finished = true;
            loser.rank = totalMarbles; // Last place
            loser.finishTime = now - startTime.current + 99999; // Penalty time
        }

        // Trigger finish logic immediately
        if (!raceFinished.current) {
            raceFinished.current = true;
            const sorted = [...marbles].sort((a, b) => a.rank - b.rank);
            audio.playFinish(); 
            setTimeout(() => onRaceFinish(sorted), 1000);
            return;
        }
    }
    // ------------------------

    // Separate dynamic types
    const fans: DynamicObstacle[] = [];
    const repulsors: DynamicObstacle[] = [];
    const conveyors: DynamicObstacle[] = [];
    const lasers: DynamicObstacle[] = [];
    const teleporters: DynamicObstacle[] = [];
    const solidDynamics: DynamicObstacle[] = [];

    dynamicObjs.forEach(obj => {
      if (obj.type === 'fan') { fans.push(obj); return; }
      if (obj.type === 'repulsor') { repulsors.push(obj); return; }
      if (obj.type === 'conveyor') { conveyors.push(obj); return; }
      if (obj.type === 'laser') { lasers.push(obj); return; }
      if (obj.type === 'teleporter') { teleporters.push(obj); return; }

      solidDynamics.push(obj);

      // Animation updates for solids
      if (obj.type === 'spinner') {
        obj.angle += obj.speed;
      } else if (obj.type === 'slider_h') {
        obj.x = obj.initialX! + Math.sin(timeRef.current * 0.02) * (obj.range || 100);
      } else if (obj.type === 'slider_v') {
        obj.y = obj.initialY! + Math.sin(timeRef.current * 0.015) * (obj.range || 80);
      }
    });

    // Update Laser States (Toggle every 180 ticks approx 3 sec)
    lasers.forEach(l => {
       l.timer = (l.timer || 0) + 1;
       if (l.timer > 180) {
           l.active = !l.active;
           l.timer = 0;
       }
    });

    // Generate collision lines for solids
    const dynamicLines: LineSegment[] = [];
    solidDynamics.forEach(obj => {
      const halfW = obj.width / 2;
      const dx = Math.cos(obj.angle) * halfW;
      const dy = Math.sin(obj.angle) * halfW;
      dynamicLines.push({
        x1: obj.x - dx, y1: obj.y - dy,
        x2: obj.x + dx, y2: obj.y + dy,
        type: obj.type === 'spinner' ? 'bouncer' : 'floor'
      });
    });

    for (let step = 0; step < STEPS; step++) {
      for (let i = 0; i < marbles.length; i++) {
        const m = marbles[i];
        if (m.finished) continue;

        // 1. Gravity & Movement
        m.vy += config.gravity * dt;
        m.x += m.vx * dt;
        m.y += m.vy * dt;

        // -- Force Fields & Zones --

        // Fan Physics
        for (const fan of fans) {
          const dx = m.x - fan.x;
          const dy = m.y - fan.y;
          const localX = dx * Math.cos(-fan.angle) - dy * Math.sin(-fan.angle);
          const localY = dx * Math.sin(-fan.angle) + dy * Math.cos(-fan.angle);
          const halfWidth = fan.width / 2; 
          const range = fan.height || 200;

          if (localX > 0 && localX < range && Math.abs(localY) < halfWidth) {
             const force = fan.force || 0.5;
             const forceX = Math.cos(fan.angle) * force;
             const forceY = Math.sin(fan.angle) * force;
             m.vx += forceX * dt;
             m.vy += forceY * dt;
          }
        }

        // Repulsor Physics
        for (const rep of repulsors) {
          const dx = m.x - rep.x;
          const dy = m.y - rep.y;
          const distSq = dx*dx + dy*dy;
          const range = rep.range || 100;

          if (distSq < range * range) {
             const dist = Math.sqrt(distSq);
             const nx = dx / dist;
             const ny = dy / dist;
             const pulse = (Math.sin(timeRef.current * rep.speed) + 1) * 0.5;
             const force = (rep.force || 1) * (1 - dist/range) * (0.5 + pulse);
             m.vx += nx * force * dt * 50;
             m.vy += ny * force * dt * 50;
          }
        }

        // Conveyor Physics
        for (const conv of conveyors) {
           const dx = m.x - conv.x;
           const dy = m.y - conv.y;
           const localParallel = dx * Math.cos(-conv.angle) - dy * Math.sin(-conv.angle); 
           const localPerp = dx * Math.sin(-conv.angle) + dy * Math.cos(-conv.angle); 

           const halfLength = conv.width / 2;
           const halfWidth = (conv.height || 50) / 2;

           if (Math.abs(localParallel) < halfWidth && Math.abs(localPerp) < halfLength) {
              const force = conv.force || 10;
              const forceX = Math.cos(conv.angle) * force;
              const forceY = Math.sin(conv.angle) * force;
              m.vx += forceX * dt;
              m.vy += forceY * dt;
           }
        }

        // Laser Physics
        for (const laser of lasers) {
            if (!laser.active) continue;
            // Laser is a line segment from x,y extending 'height' length at 'angle'
            const len = laser.height || 300;
            const lx1 = laser.x;
            const ly1 = laser.y;
            const lx2 = lx1 + Math.cos(laser.angle) * len;
            const ly2 = ly1 + Math.sin(laser.angle) * len;

            // Distance from point to line segment
            const A = m.x - lx1;
            const B = m.y - ly1;
            const C = lx2 - lx1;
            const D = ly2 - ly1;

            const dot = A * C + B * D;
            const lenSq = C * C + D * D;
            let param = -1;
            if (lenSq !== 0) param = dot / lenSq;

            let xx, yy;

            if (param < 0) {
                xx = lx1; yy = ly1;
            } else if (param > 1) {
                xx = lx2; yy = ly2;
            } else {
                xx = lx1 + param * C;
                yy = ly1 + param * D;
            }

            const dx = m.x - xx;
            const dy = m.y - yy;
            const dist = Math.sqrt(dx * dx + dy * dy);

            if (dist < m.radius + 5) { // 5px laser width
                // Push perpendicular to laser
                const force = laser.force || 20;
                // Simple push away from line center logic, or just generic "burn" kick
                // Let's push in the direction of the normal (-dy, dx) normalized
                // Or just purely vertical if horizontal laser?
                // Let's push AWAY from the beam origin for chaos
                m.vx += (dx/dist) * force * dt * 10;
                m.vy += (dy/dist) * force * dt * 10;

                // Add jitter
                m.vx += (Math.random() - 0.5) * 10;
                m.vy += (Math.random() - 0.5) * 10;
            }
        }

        // Teleporter Physics
        for (const tele of teleporters) {
            // Check Entrance
            const dx = m.x - tele.x;
            const dy = m.y - tele.y;
            const dist = Math.sqrt(dx*dx + dy*dy);

            // Teleport if close and not on cooldown
            if (dist < (tele.width/2) && (!teleportCooldowns.current[m.id] || now > teleportCooldowns.current[m.id])) {
                 m.x = tele.destX || m.x;
                 m.y = tele.destY || m.y;
                 m.vx *= 0.5; // Dampen velocity
                 m.vy = Math.abs(m.vy) + 2; // Pop out downwards
                 teleportCooldowns.current[m.id] = now + 1000; // 1 second cooldown
                 audio.playPinHit(5); // Sound effect
            }
        }

        // -- Rotation Damping --
        m.angle += m.omega * dt;
        m.omega *= 0.999; 

        m.vx *= Math.pow(config.friction, dt);
        m.vy *= Math.pow(config.friction, dt);

        if (m.vx*m.vx + m.vy*m.vy < 0.2) {
             m.vx += (Math.random() - 0.5); 
             m.vy += 0.5; 
        }

        // 2. Collisions
        for (const line of linesRef.current) checkLineCollision(m, line);
        for (const dLine of dynamicLines) checkLineCollision(m, dLine, true);
        for (const pin of pinsRef.current) checkPinCollision(m, pin);

        for (let j = i + 1; j < marbles.length; j++) {
           if (!marbles[j].finished) checkMarbleCollision(m, marbles[j]);
        }

        // 3. Finish Line
        if (m.y > finishLineY.current) {
          m.finished = true;
          m.finishTime = Date.now() - startTime.current;
          const finishedSoFar = marbles.filter(b => b.finished).length;
          m.rank = finishedSoFar;
          audio.playPinHit(10);
        }

        if (!m.finished) {
            totalSpeed += Math.sqrt(m.vx*m.vx + m.vy*m.vy + m.omega*m.radius*m.omega*m.radius);
        }
      }
    }

    audio.updateRolling(totalSpeed);

    const activeMarblesList = marbles.filter(m => !m.finished);
    if (activeMarblesList.length > 0) {
      activeMarblesList.sort((a, b) => b.y - a.y);
      const leaders = activeMarblesList.slice(0, 3); 
      const avgY = leaders.reduce((a, b) => a + b.y, 0) / leaders.length;
      cameraY.current += (avgY - cameraY.current - 300) * 0.08;
    } else {
      if (!raceFinished.current) {
        raceFinished.current = true;
        const sorted = [...marbles].sort((a, b) => a.rank - b.rank);
        audio.playFinish(); 
        setTimeout(() => onRaceFinish(sorted), 1000);
      }
    }
  };

  const resolveCollisionPhysics = (ball: Marble, nx: number, ny: number, isBouncy: boolean) => {
    const vDotN = ball.vx * nx + ball.vy * ny;
    if (vDotN > 0) return; 

    const intensity = Math.abs(vDotN);
    if (intensity > 1.0) {
        audio.playBump(intensity);
    }

    const restitution = isBouncy ? 1.5 : config.restitution;
    const jN = -(1 + restitution) * vDotN;
    ball.vx += jN * nx;
    ball.vy += jN * ny;

    const tx = -ny;
    const ty = nx;
    const vDotT = ball.vx * tx + ball.vy * ty;
    const vSurf = vDotT + ball.omega * ball.radius;

    const mass = 1.0;
    const jT_ideal = -vSurf / (3.5 / mass);
    const mu = 0.5;
    const maxJt = mu * Math.abs(jN);

    let jT = jT_ideal;
    if (Math.abs(jT) > maxJt) {
       jT = Math.sign(jT) * maxJt;
    }

    ball.vx += jT * tx;
    ball.vy += jT * ty;
    ball.omega += (2.5 * jT) / (mass * ball.radius);
  };

  const checkLineCollision = (ball: Marble, line: LineSegment, isDynamic = false) => {
    const dx = line.x2 - line.x1;
    const dy = line.y2 - line.y1;
    const lenSq = dx*dx + dy*dy;
    const t = Math.max(0, Math.min(1, ((ball.x - line.x1) * dx + (ball.y - line.y1) * dy) / lenSq));
    const closeX = line.x1 + t * dx;
    const closeY = line.y1 + t * dy;

    const distX = ball.x - closeX;
    const distY = ball.y - closeY;
    const distSq = distX*distX + distY*distY;

    if (distSq < ball.radius * ball.radius) {
      const dist = Math.sqrt(distSq);
      const nx = distX / dist;
      const ny = distY / dist;

      const overlap = ball.radius - dist;
      ball.x += nx * overlap;
      ball.y += ny * overlap;

      const isBouncy = isDynamic && line.type === 'bouncer';
      resolveCollisionPhysics(ball, nx, ny, isBouncy);

      if (isDynamic) {
        ball.vx += (Math.random() - 0.5) * 2;
        ball.vy += (Math.random() - 0.5) * 2;
      }
    }
  };

  const checkPinCollision = (ball: Marble, pin: CircleObstacle) => {
    const dx = ball.x - pin.x;
    const dy = ball.y - pin.y;
    const distSq = dx*dx + dy*dy;
    const minDist = ball.radius + pin.radius;

    if (distSq < minDist * minDist) {
      const dist = Math.sqrt(distSq);
      const nx = dx / dist;
      const ny = dy / dist;

      const overlap = minDist - dist;
      ball.x += nx * overlap;
      ball.y += ny * overlap;

      const isBumper = pin.type === 'bumper';

      const intensity = Math.sqrt(ball.vx*ball.vx + ball.vy*ball.vy);
      if (intensity > 1) {
          audio.playPinHit(intensity);
      }

      resolveCollisionPhysics(ball, nx, ny, isBumper);
    }
  };

  const checkMarbleCollision = (m1: Marble, m2: Marble) => {
    const dx = m2.x - m1.x;
    const dy = m2.y - m1.y;
    const distSq = dx*dx + dy*dy;
    const minDist = m1.radius + m2.radius;

    if (distSq < minDist * minDist) {
      const dist = Math.sqrt(distSq);
      const nx = dx / dist;
      const ny = dy / dist;
      const overlap = (minDist - dist) * 0.5;

      m1.x -= nx * overlap;
      m1.y -= ny * overlap;
      m2.x += nx * overlap;
      m2.y += ny * overlap;

      const dvx = m1.vx - m2.vx;
      const dvy = m1.vy - m2.vy;
      const dot = dvx * nx + dvy * ny;

      if (dot > 0) {
         if (dot > 2) audio.playPinHit(dot * 0.5);

         const impulse = dot * 0.9; 
         m1.vx -= impulse * nx;
         m1.vy -= impulse * ny;
         m2.vx += impulse * nx;
         m2.vy += impulse * ny;
      }
    }
  };

  // --- Initialization ---
  useEffect(() => {
    generateLevel();
    raceFinished.current = false;
    startTime.current = Date.now();
    cameraY.current = 0;
    timeRef.current = 0;
    teleportCooldowns.current = {};

    marblesRef.current = activeMarbles.map((m, index) => ({
      ...m,
      x: COURSE_WIDTH * 0.4 + (Math.random() * COURSE_WIDTH * 0.2),
      y: -50 - (index * 40),
      vx: (Math.random() - 0.5) * 5,
      vy: 0,
      angle: 0,
      omega: 0,
      finished: false,
      rank: 0
    }));

    audio.resume();

  }, [activeMarbles]); 

  // --- Drawing Subroutines ---

  const drawRepulsor = (ctx: CanvasRenderingContext2D, obj: DynamicObstacle) => {
    const pulse = (Math.sin(timeRef.current * obj.speed) + 1) * 0.5;
    const currentRadius = obj.width/2 + pulse * (obj.range! - obj.width/2);

    // Core
    ctx.beginPath();
    ctx.arc(0, 0, obj.width/2, 0, Math.PI * 2);
    ctx.fillStyle = '#8b5cf6'; // Violet
    ctx.fill();

    // Pulse Ring
    ctx.beginPath();
    ctx.arc(0, 0, currentRadius, 0, Math.PI * 2);
    ctx.strokeStyle = `rgba(139, 92, 246, ${1 - pulse})`;
    ctx.lineWidth = 2;
    ctx.stroke();
  };

  const drawConveyor = (ctx: CanvasRenderingContext2D, obj: DynamicObstacle) => {
    const w = obj.width; // length along X (rotated)
    const h = obj.height || 50; // width across Y

    ctx.beginPath();
    ctx.rect(-h/2, -w/2, h, w); // Swapped because conveyor angle usually down
    ctx.fillStyle = '#334155';
    ctx.fill();
    ctx.strokeStyle = '#475569';
    ctx.stroke();

    // Arrows
    const offset = (timeRef.current * obj.speed * 50) % 40;
    ctx.fillStyle = 'rgba(255, 255, 255, 0.3)';
    for(let i = -w/2; i < w/2; i+=40) {
        const y = i + offset;
        if (y > w/2) continue;

        ctx.save();
        ctx.translate(0, y); 
        ctx.beginPath();
        ctx.moveTo(-10, -5);
        ctx.lineTo(0, 5);
        ctx.lineTo(10, -5);
        ctx.fill();
        ctx.restore();
    }
  };

  const drawLaser = (ctx: CanvasRenderingContext2D, obj: DynamicObstacle) => {
     // Draw source
     ctx.fillStyle = '#111';
     ctx.beginPath();
     ctx.arc(0, 0, 10, 0, Math.PI * 2);
     ctx.fill();
     ctx.strokeStyle = '#ef4444';
     ctx.lineWidth = 2;
     ctx.stroke();

     if (obj.active) {
         const len = obj.height || 300;
         ctx.beginPath();
         ctx.moveTo(0, 0);
         ctx.lineTo(len, 0); // Local space, already rotated

         // Glow
         ctx.shadowColor = '#ef4444';
         ctx.shadowBlur = 15;
         ctx.strokeStyle = '#fca5a5';
         ctx.lineWidth = 4;
         ctx.stroke();

         // Inner Core
         ctx.shadowBlur = 0;
         ctx.strokeStyle = '#fff';
         ctx.lineWidth = 1;
         ctx.stroke();
     } else {
         // Warning LED
         ctx.fillStyle = timeRef.current % 30 < 15 ? '#ef4444' : '#550000';
         ctx.beginPath();
         ctx.arc(0, 0, 4, 0, Math.PI * 2);
         ctx.fill();
     }
  };

  const drawTeleporter = (ctx: CanvasRenderingContext2D, obj: DynamicObstacle, isExit = false) => {
      // Swirling portal effect
      const radius = obj.width / 2;
      const angleOffset = timeRef.current * (isExit ? -0.1 : 0.1);

      // Outer ring
      ctx.beginPath();
      ctx.arc(0, 0, radius, 0, Math.PI * 2);
      ctx.strokeStyle = isExit ? '#06b6d4' : '#d946ef'; // Cyan exit, Magenta entry
      ctx.lineWidth = 3;
      ctx.stroke();

      // Inner spirals
      ctx.save();
      ctx.rotate(angleOffset);
      for(let i=0; i<3; i++) {
          ctx.rotate((Math.PI * 2) / 3);
          ctx.beginPath();
          ctx.moveTo(0, 0);
          ctx.quadraticCurveTo(radius/2, 0, radius, radius/2);
          ctx.strokeStyle = isExit ? 'rgba(6,182,212,0.5)' : 'rgba(217,70,239,0.5)';
          ctx.lineWidth = 2;
          ctx.stroke();
      }
      ctx.restore();

      // Label
      ctx.fillStyle = '#fff';
      ctx.font = '10px Arial';
      ctx.textAlign = 'center';
      ctx.fillText(isExit ? 'OUT' : 'IN', 0, 4);
  };

  const drawLeaderboard = (ctx: CanvasRenderingContext2D, canvasWidth: number, canvasHeight: number) => {
    // Sort marbles
    const sorted = [...marblesRef.current].sort((a, b) => {
      if (a.finished && b.finished) return a.rank - b.rank;
      if (a.finished) return -1;
      if (b.finished) return 1;
      return b.y - a.y;
    });

    const boxWidth = 110; // Reduced width
    const itemHeight = 18; // Reduced height
    const startX = canvasWidth - boxWidth - 10;
    const startY = 110; // Moved down to avoid top overlap

    // Background
    ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
    ctx.roundRect(startX, startY, boxWidth, sorted.length * itemHeight + 10, 6);
    ctx.fill();
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.1)';
    ctx.lineWidth = 1;
    ctx.stroke();

    ctx.font = 'bold 10px "Roboto Mono"'; // Smaller font
    ctx.textAlign = 'left';
    ctx.textBaseline = 'middle';

    sorted.forEach((m, index) => {
       const y = startY + 12 + index * itemHeight;

       // Rank
       ctx.fillStyle = index === 0 ? '#fbbf24' : index === 1 ? '#9ca3af' : index === 2 ? '#b45309' : '#6b7280';
       ctx.fillText(`${index + 1}.`, startX + 8, y);

       // Color Dot
       ctx.fillStyle = m.color;
       ctx.beginPath();
       ctx.arc(startX + 30, y, 4, 0, Math.PI * 2);
       ctx.fill();

       // Name
       ctx.fillStyle = m.finished ? '#10b981' : '#e5e7eb';
       ctx.fillText(m.name, startX + 42, y);

       // Highlight Bet
       if (m.id === betMarbleId) {
          ctx.strokeStyle = '#fbbf24';
          ctx.lineWidth = 1;
          ctx.strokeRect(startX + 2, y - 9, boxWidth - 4, 18);
       }
    });
  };

  // --- Render Loop ---
  const draw = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const { offsetWidth, offsetHeight } = canvas;
    if (canvas.width !== offsetWidth || canvas.height !== offsetHeight) {
      canvas.width = offsetWidth;
      canvas.height = offsetHeight;
    }

    ctx.fillStyle = '#1f2937';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.save();
    const scale = canvas.width / COURSE_WIDTH;
    ctx.scale(scale, scale);
    const camY = Math.max(0, Math.min(cameraY.current, finishLineY.current - canvas.height/scale + 100));
    ctx.translate(0, -camY);

    // Draw Static Lines
    ctx.lineWidth = 4;
    ctx.lineCap = 'round';
    linesRef.current.forEach(l => {
      ctx.strokeStyle = l.type === 'wall' ? '#4b5563' : '#60a5fa';
      if (l.type === 'wall') ctx.lineWidth = 6;
      else ctx.lineWidth = 4;
      ctx.beginPath();
      ctx.moveTo(l.x1, l.y1);
      ctx.lineTo(l.x2, l.y2);
      ctx.stroke();
    });

    // Draw Dynamic Obstacles
    dynamicRef.current.forEach(obj => {
       ctx.save();

       if (obj.type === 'teleporter') {
           // Draw Entrance
           ctx.save();
           ctx.translate(obj.x, obj.y);
           drawTeleporter(ctx, obj, false);
           ctx.restore();

           // Draw Exit
           if (obj.destX !== undefined && obj.destY !== undefined) {
               ctx.save();
               ctx.translate(obj.destX, obj.destY);
               drawTeleporter(ctx, obj, true);
               ctx.restore();
           }
           return;
       }

       ctx.translate(obj.x, obj.y);
       ctx.rotate(obj.angle);

       if (obj.type === 'fan') {
          // Draw Fan Base
          ctx.fillStyle = '#64748b';
          ctx.fillRect(-10, -obj.width/2, 20, obj.width);

          // Draw Air Flow
          const range = obj.height || 200;
          const gradient = ctx.createLinearGradient(0, 0, range, 0);
          gradient.addColorStop(0, 'rgba(255, 255, 255, 0.4)');
          gradient.addColorStop(1, 'rgba(255, 255, 255, 0)');

          ctx.fillStyle = gradient;
          ctx.fillRect(0, -obj.width/2, range, obj.width);

          // Animated Lines
          ctx.strokeStyle = 'rgba(255, 255, 255, 0.5)';
          ctx.lineWidth = 1;
          const offset = (timeRef.current * 5) % 50;
          for(let i=0; i<3; i++) {
             const yPos = -obj.width/2 + (obj.width/4) * (i+1);
             ctx.beginPath();
             ctx.moveTo(10 + offset, yPos);
             ctx.lineTo(range - 20, yPos);
             ctx.stroke();
          }

       } else if (obj.type === 'repulsor') {
          drawRepulsor(ctx, obj);
       } else if (obj.type === 'conveyor') {
          drawConveyor(ctx, obj);
       } else if (obj.type === 'laser') {
          drawLaser(ctx, obj);
       } else {
         // Sliders & Spinners
         ctx.strokeStyle = obj.type === 'spinner' ? '#ef4444' : '#f59e0b';
         ctx.lineWidth = 8;
         ctx.beginPath();
         ctx.moveTo(-obj.width/2, 0);
         ctx.lineTo(obj.width/2, 0);
         ctx.stroke();

         if (obj.type === 'spinner') {
           ctx.beginPath();
           ctx.arc(0, 0, 5, 0, Math.PI * 2);
           ctx.fillStyle = '#fff';
           ctx.fill();
         }
       }
       ctx.restore();
    });

    // Draw Pins
    pinsRef.current.forEach(p => {
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.radius, 0, Math.PI * 2);
      ctx.fillStyle = p.type === 'bumper' ? '#f472b6' : '#9ca3af';
      ctx.fill();
    });

    // Draw Finish Line
    ctx.fillStyle = '#10b981';
    ctx.fillRect(0, finishLineY.current, COURSE_WIDTH, 10);
    for(let i=0; i<20; i++) {
        ctx.fillStyle = i%2===0 ? '#fff' : '#000';
        ctx.fillRect(i * (COURSE_WIDTH/20), finishLineY.current, COURSE_WIDTH/20, 10);
    }

    // Draw Marbles
    marblesRef.current.forEach(m => {
      ctx.save();
      ctx.translate(m.x, m.y);
      ctx.rotate(-m.angle); 

      ctx.beginPath();
      ctx.arc(0, 0, m.radius, 0, Math.PI * 2);
      ctx.fillStyle = m.color;
      ctx.shadowColor = 'rgba(0,0,0,0.5)';
      ctx.shadowBlur = 5;
      ctx.fill();
      ctx.shadowBlur = 0;

      ctx.beginPath();
      ctx.moveTo(-m.radius, 0);
      ctx.lineTo(m.radius, 0);
      ctx.strokeStyle = 'rgba(255,255,255,0.5)';
      ctx.lineWidth = 3;
      ctx.stroke();

      ctx.beginPath();
      ctx.moveTo(0, -m.radius);
      ctx.lineTo(0, m.radius);
      ctx.strokeStyle = 'rgba(0,0,0,0.3)';
      ctx.lineWidth = 2;
      ctx.stroke();

      ctx.beginPath();
      ctx.arc(-4, -4, 3, 0, Math.PI * 2);
      ctx.fillStyle = 'rgba(255,255,255,0.7)';
      ctx.fill();

      ctx.restore(); 

      if (m.id === betMarbleId) {
        ctx.strokeStyle = '#fbbf24';
        ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.arc(m.x, m.y, m.radius + 5, 0, Math.PI * 2);
        ctx.stroke();
      }

      if (!m.finished) {
        // Name only, rank badge removed
        ctx.fillStyle = '#fff';
        ctx.font = '10px Arial';
        ctx.textAlign = 'center';
        ctx.fillText(m.name, m.x, m.y - 18);
      }
    });

    ctx.restore(); // Restore from camera transform

    // Draw UI Overlay (Leaderboard) - in screen space (not camera space)
    drawLeaderboard(ctx, canvas.width, canvas.height);
  };

  useEffect(() => {
    const loop = () => {
      update();
      draw();
      requestRef.current = requestAnimationFrame(loop);
    };
    requestRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(requestRef.current!);
  });

  return (
    <canvas ref={canvasRef} className="w-full h-full block" />
  );
};

export default RaceEngine;

import React, { useRef, useEffect } from 'react';
import { Marble, PhysicsConfig, LineSegment, CircleObstacle, DynamicObstacle } from '../types';
import { audio } from '../services/audioService';

interface RaceEngineProps {
  activeMarbles: Marble[];
  config: PhysicsConfig;
  onRaceFinish: (results: Marble[]) => void;
  betMarbleId: number | null;
}

const RaceEngine: React.FC<RaceEngineProps> = ({ activeMarbles, config, onRaceFinish, betMarbleId }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();

  // Physics State (Mutable refs for performance)
  const marblesRef = useRef<Marble[]>([]);
  const linesRef = useRef<LineSegment[]>([]);
  const pinsRef = useRef<CircleObstacle[]>([]);
  const dynamicRef = useRef<DynamicObstacle[]>([]);
  const teleportCooldowns = useRef<Record<number, number>>({}); // marbleId -> timestamp

  const cameraY = useRef(0);
  const raceFinished = useRef(false);
  const finishLineY = useRef(0);
  const startTime = useRef(0);
  const timeRef = useRef(0);

  // Constants
  const COURSE_WIDTH = 600;

  // --- Level Generation ---
  const generateLevel = () => {
    const lines: LineSegment[] = [];
    const pins: CircleObstacle[] = [];
    const dynamics: DynamicObstacle[] = [];

    // Config
    const segments = 10 + Math.floor(Math.random() * 3);
    const segmentHeight = 450;
    let currentY = 0;

    // 1. Start Funnel
    lines.push({ x1: 0, y1: 0, x2: COURSE_WIDTH * 0.4, y2: 150, type: 'wall' });
    lines.push({ x1: COURSE_WIDTH, y1: 0, x2: COURSE_WIDTH * 0.6, y2: 150, type: 'wall' });
    lines.push({ x1: COURSE_WIDTH * 0.4, y1: 150, x2: COURSE_WIDTH * 0.4, y2: 180, type: 'wall' });
    lines.push({ x1: COURSE_WIDTH * 0.6, y1: 150, x2: COURSE_WIDTH * 0.6, y2: 180, type: 'wall' });

    currentY = 220;

    // 2. Procedural Segments
    for (let i = 0; i < segments; i++) {
      const type = Math.random();

      // Outer Walls
      lines.push({ x1: 0, y1: currentY - 50, x2: 0, y2: currentY + segmentHeight, type: 'wall' });
      lines.push({ x1: COURSE_WIDTH, y1: currentY - 50, x2: COURSE_WIDTH, y2: currentY + segmentHeight, type: 'wall' });

      if (type < 0.12) {
        // --- PROPELLERS (Spinners) ---
        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 100, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 100, type: 'floor' });

        dynamics.push({
          id: `spin_${i}_1`,
          type: 'spinner',
          x: COURSE_WIDTH * 0.35,
          y: currentY + 250,
          width: 140,
          angle: 0,
          speed: 0.1,
        });
        dynamics.push({
          id: `spin_${i}_2`,
          type: 'spinner',
          x: COURSE_WIDTH * 0.65,
          y: currentY + 350,
          width: 140,
          angle: Math.PI / 2,
          speed: -0.1,
        });

      } else if (type < 0.24) {
        // --- REPULSORS ---
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.3, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.7, y2: currentY + 150, type: 'floor' });

        dynamics.push({
          id: `repulse_${i}`,
          type: 'repulsor',
          x: COURSE_WIDTH / 2,
          y: currentY + 300,
          width: 50, 
          range: 120, 
          angle: 0,
          speed: 0.1, 
          force: 2.5
        });

      } else if (type < 0.36) {
        // --- CONVEYOR BELTS ---
        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.4, y2: currentY + 100, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.6, y2: currentY + 100, type: 'wall' });

        dynamics.push({
          id: `conveyor_${i}`,
          type: 'conveyor',
          x: COURSE_WIDTH * 0.5,
          y: currentY + 250,
          width: 200, 
          height: 100, 
          angle: Math.PI / 2, // Downwards
          speed: 0.1, 
          force: 15 
        });

      } else if (type < 0.48) {
        // --- LASER CANNONS (New) ---
        // Narrow path with a laser across it
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.3, y2: currentY + 150, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.7, y2: currentY + 150, type: 'wall' });

        dynamics.push({
          id: `laser_${i}`,
          type: 'laser',
          x: COURSE_WIDTH * 0.1, // Source on left
          y: currentY + 300,
          width: 0, 
          height: COURSE_WIDTH * 0.8, // Length of beam
          angle: 0, // Horizontal
          speed: 0,
          force: 20, // Strong push
          active: true,
          timer: 0
        });

        // Laser source visual box (wall)
        lines.push({ x1: 0, y1: currentY + 280, x2: COURSE_WIDTH * 0.15, y2: currentY + 320, type: 'wall' });

      } else if (type < 0.6) {
        // --- TELEPORTERS (New) ---
        // Entrance top, Exit bottom
        const entranceX = COURSE_WIDTH * (0.2 + Math.random() * 0.6);
        const exitX = COURSE_WIDTH * (0.2 + Math.random() * 0.6);

        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.2, y2: currentY + 100, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.8, y2: currentY + 100, type: 'floor' });

        dynamics.push({
          id: `teleport_${i}`,
          type: 'teleporter',
          x: entranceX,
          y: currentY + 150,
          width: 40, // Radius
          destX: exitX,
          destY: currentY + 350,
          angle: 0,
          speed: 0.05
        });

        // Add some obstacles around the exit to make it interesting
        pins.push({ x: exitX + 60, y: currentY + 350, radius: 15, type: 'bumper' });
        pins.push({ x: exitX - 60, y: currentY + 350, radius: 15, type: 'bumper' });

      } else if (type < 0.75) {
        // --- MOVING ELEVATORS ---
        const isVertical = Math.random() > 0.5;

        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.2, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.8, y2: currentY + 150, type: 'floor' });

        if (isVertical) {
           dynamics.push({
             id: `slide_v_${i}`,
             type: 'slider_v',
             x: COURSE_WIDTH / 2,
             y: currentY + 200,
             width: 200,
             angle: 0,
             speed: 1, 
             range: 100,
             initialX: COURSE_WIDTH / 2,
             initialY: currentY + 250
           });
        } else {
           dynamics.push({
            id: `slide_h_${i}`,
            type: 'slider_h',
            x: COURSE_WIDTH / 2,
            y: currentY + 250,
            width: 250,
            angle: 0,
            speed: 2,
            range: 150,
            initialX: COURSE_WIDTH / 2,
            initialY: currentY + 250
          });
        }

      } else if (type < 0.85) {
        // --- WIND CANNONS ---
        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 100, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 100, type: 'floor' });

        dynamics.push({
          id: `fan_${i}_1`,
          type: 'fan',
          x: 20, 
          y: currentY + 250,
          width: 40,
          height: 300, 
          angle: 0, 
          speed: 0,
          force: 0.6
        });

        pins.push({ x: COURSE_WIDTH * 0.6, y: currentY + 250, radius: 20, type: 'bumper' });

      } else {
         // --- CLASSIC SLALOM ---
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.6, y2: currentY + 180, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 250, x2: COURSE_WIDTH * 0.4, y2: currentY + 380, type: 'floor' });
        pins.push({ x: COURSE_WIDTH * 0.8, y: currentY + 200, radius: 15, type: 'bumper' });
        pins.push({ x: COURSE_WIDTH * 0.2, y: currentY + 400, radius: 15, type: 'bumper' });
      }

      currentY += segmentHeight;
    }

    // 3. Finish Area
    lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 200, type: 'floor' });
    lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 200, type: 'floor' });

    finishLineY.current = currentY + 250;

    linesRef.current = lines;
    pinsRef.current = pins;
    dynamicRef.current = dynamics;
  };

  // --- Physics Logic ---
  const update = () => {
    if (raceFinished.current) {
        audio.updateRolling(0); 
        return;
    }

    const STEPS = 4;
    const dt = 1 / STEPS;
    timeRef.current += 1;
    const now = Date.now();

    const marbles = marblesRef.current;
    const dynamicObjs = dynamicRef.current;

    let totalSpeed = 0;

    // --- MERCY RULE CHECK ---
    const activeMarblesCount = marbles.filter(m => !m.finished).length;
    const totalMarbles = marbles.length;

    if (totalMarbles > 1 && activeMarblesCount === 1) {
        const loser = marbles.find(m => !m.finished);
        if (loser) {
            loser.finished = true;
            loser.rank = totalMarbles; 
            loser.finishTime = now - startTime.current + 99999; 
        }

        if (!raceFinished.current) {
            raceFinished.current = true;
            const sorted = [...marbles].sort((a, b) => a.rank - b.rank);
            audio.playFinish(); 
            setTimeout(() => onRaceFinish(sorted), 1000);
            return;
        }
    }

    // Separate dynamic types
    const fans: DynamicObstacle[] = [];
    const repulsors: DynamicObstacle[] = [];
    const conveyors: DynamicObstacle[] = [];
    const lasers: DynamicObstacle[] = [];
    const teleporters: DynamicObstacle[] = [];
    const solidDynamics: DynamicObstacle[] = [];

    dynamicObjs.forEach(obj => {
      if (obj.type === 'fan') { fans.push(obj); return; }
      if (obj.type === 'repulsor') { repulsors.push(obj); return; }
      if (obj.type === 'conveyor') { conveyors.push(obj); return; }
      if (obj.type === 'laser') { lasers.push(obj); return; }
      if (obj.type === 'teleporter') { teleporters.push(obj); return; }

      solidDynamics.push(obj);

      if (obj.type === 'spinner') {
        obj.angle += obj.speed;
      } else if (obj.type === 'slider_h') {
        obj.x = obj.initialX! + Math.sin(timeRef.current * 0.02) * (obj.range || 100);
      } else if (obj.type === 'slider_v') {
        obj.y = obj.initialY! + Math.sin(timeRef.current * 0.015) * (obj.range || 80);
      }
    });

    lasers.forEach(l => {
       l.timer = (l.timer || 0) + 1;
       if (l.timer > 180) {
           l.active = !l.active;
           l.timer = 0;
       }
    });

    const dynamicLines: LineSegment[] = [];
    solidDynamics.forEach(obj => {
      const halfW = obj.width / 2;
      const dx = Math.cos(obj.angle) * halfW;
      const dy = Math.sin(obj.angle) * halfW;
      dynamicLines.push({
        x1: obj.x - dx, y1: obj.y - dy,
        x2: obj.x + dx, y2: obj.y + dy,
        type: obj.type === 'spinner' ? 'bouncer' : 'floor'
      });
    });

    for (let step = 0; step < STEPS; step++) {
      for (let i = 0; i < marbles.length; i++) {
        const m = marbles[i];
        if (m.finished) continue;

        m.vy += config.gravity * dt;
        m.x += m.vx * dt;
        m.y += m.vy * dt;

        // Fan Physics
        for (const fan of fans) {
          const dx = m.x - fan.x;
          const dy = m.y - fan.y;
          const localX = dx * Math.cos(-fan.angle) - dy * Math.sin(-fan.angle);
          const localY = dx * Math.sin(-fan.angle) + dy * Math.cos(-fan.angle);
          const halfWidth = fan.width / 2; 
          const range = fan.height || 200;

          if (localX > 0 && localX < range && Math.abs(localY) < halfWidth) {
             const force = fan.force || 0.5;
             const forceX = Math.cos(fan.angle) * force;
             const forceY = Math.sin(fan.angle) * force;
             m.vx += forceX * dt;
             m.vy += forceY * dt;
          }
        }

        // Repulsor Physics
        for (const rep of repulsors) {
          const dx = m.x - rep.x;
          const dy = m.y - rep.y;
          const distSq = dx*dx + dy*dy;
          const range = rep.range || 100;

          if (distSq < range * range) {
             const dist = Math.sqrt(distSq);
             const nx = dx / dist;
             const ny = dy / dist;
             const pulse = (Math.sin(timeRef.current * rep.speed) + 1) * 0.5;
             const force = (rep.force || 1) * (1 - dist/range) * (0.5 + pulse);
             m.vx += nx * force * dt * 50;
             m.vy += ny * force * dt * 50;
          }
        }

        // Conveyor Physics
        for (const conv of conveyors) {
           const dx = m.x - conv.x;
           const dy = m.y - conv.y;
           const localParallel = dx * Math.cos(-conv.angle) - dy * Math.sin(-conv.angle); 
           const localPerp = dx * Math.sin(-conv.angle) + dy * Math.cos(-conv.angle); 

           const halfLength = conv.width / 2;
           const halfWidth = (conv.height || 50) / 2;

           if (Math.abs(localParallel) < halfWidth && Math.abs(localPerp) < halfLength) {
              const force = conv.force || 10;
              const forceX = Math.cos(conv.angle) * force;
              const forceY = Math.sin(conv.angle) * force;
              m.vx += forceX * dt;
              m.vy += forceY * dt;
           }
        }

        // Laser Physics
        for (const laser of lasers) {
            if (!laser.active) continue;
            const len = laser.height || 300;
            const lx1 = laser.x;
            const ly1 = laser.y;
            const lx2 = lx1 + Math.cos(laser.angle) * len;
            const ly2 = ly1 + Math.sin(laser.angle) * len;

            const A = m.x - lx1;
            const B = m.y - ly1;
            const C = lx2 - lx1;
            const D = ly2 - ly1;

            const dot = A * C + B * D;
            const lenSq = C * C + D * D;
            let param = -1;
            if (lenSq !== 0) param = dot / lenSq;

            let xx, yy;

            if (param < 0) {
                xx = lx1; yy = ly1;
            } else if (param > 1) {
                xx = lx2; yy = ly2;
            } else {
                xx = lx1 + param * C;
                yy = ly1 + param * D;
            }

            const dx = m.x - xx;
            const dy = m.y - yy;
            const dist = Math.sqrt(dx * dx + dy * dy);

            if (dist < m.radius + 5) { 
                const force = laser.force || 20;
                m.vx += (dx/dist) * force * dt * 10;
                m.vy += (dy/dist) * force * dt * 10;
                m.vx += (Math.random() - 0.5) * 10;
                m.vy += (Math.random() - 0.5) * 10;
            }
        }

        // Teleporter Physics
        for (const tele of teleporters) {
            const dx = m.x - tele.x;
            const dy = m.y - tele.y;
            const dist = Math.sqrt(dx*dx + dy*dy);

            if (dist < (tele.width/2) && (!teleportCooldowns.current[m.id] || now > teleportCooldowns.current[m.id])) {
                 m.x = tele.destX || m.x;
                 m.y = tele.destY || m.y;
                 m.vx *= 0.5; 
                 m.vy = Math.abs(m.vy) + 2; 
                 teleportCooldowns.current[m.id] = now + 1000; 
                 audio.playPinHit(5); 
            }
        }

        m.angle += m.omega * dt;
        m.omega *= 0.999; 

        m.vx *= Math.pow(config.friction, dt);
        m.vy *= Math.pow(config.friction, dt);

        if (m.vx*m.vx + m.vy*m.vy < 0.2) {
             m.vx += (Math.random() - 0.5); 
             m.vy += 0.5; 
        }

        for (const line of linesRef.current) checkLineCollision(m, line);
        for (const dLine of dynamicLines) checkLineCollision(m, dLine, true);
        for (const pin of pinsRef.current) checkPinCollision(m, pin);

        for (let j = i + 1; j < marbles.length; j++) {
           if (!marbles[j].finished) checkMarbleCollision(m, marbles[j]);
        }

        if (m.y > finishLineY.current) {
          m.finished = true;
          m.finishTime = Date.now() - startTime.current;
          const finishedSoFar = marbles.filter(b => b.finished).length;
          m.rank = finishedSoFar;
          audio.playPinHit(10);
        }

        if (!m.finished) {
            totalSpeed += Math.sqrt(m.vx*m.vx + m.vy*m.vy + m.omega*m.radius*m.omega*m.radius);
        }
      }
    }

    audio.updateRolling(totalSpeed);

    const activeMarblesList = marbles.filter(m => !m.finished);
    if (activeMarblesList.length > 0) {
      activeMarblesList.sort((a, b) => b.y - a.y);
      const leaders = activeMarblesList.slice(0, 3); 
      const avgY = leaders.reduce((a, b) => a + b.y, 0) / leaders.length;
      cameraY.current += (avgY - cameraY.current - 300) * 0.08;
    } else {
      if (!raceFinished.current) {
        raceFinished.current = true;
        const sorted = [...marbles].sort((a, b) => a.rank - b.rank);
        audio.playFinish(); 
        setTimeout(() => onRaceFinish(sorted), 1000);
      }
    }
  };

  const resolveCollisionPhysics = (ball: Marble, nx: number, ny: number, isBouncy: boolean) => {
    const vDotN = ball.vx * nx + ball.vy * ny;
    if (vDotN > 0) return; 

    const intensity = Math.abs(vDotN);
    if (intensity > 1.0) {
        audio.playBump(intensity);
    }

    const restitution = isBouncy ? 1.5 : config.restitution;
    const jN = -(1 + restitution) * vDotN;
    ball.vx += jN * nx;
    ball.vy += jN * ny;

    const tx = -ny;
    const ty = nx;
    const vDotT = ball.vx * tx + ball.vy * ty;
    const vSurf = vDotT + ball.omega * ball.radius;

    const mass = 1.0;
    const jT_ideal = -vSurf / (3.5 / mass);
    const mu = 0.5;
    const maxJt = mu * Math.abs(jN);

    let jT = jT_ideal;
    if (Math.abs(jT) > maxJt) {
       jT = Math.sign(jT) * maxJt;
    }

    ball.vx += jT * tx;
    ball.vy += jT * ty;
    ball.omega += (2.5 * jT) / (mass * ball.radius);
  };

  const checkLineCollision = (ball: Marble, line: LineSegment, isDynamic = false) => {
    const dx = line.x2 - line.x1;
    const dy = line.y2 - line.y1;
    const lenSq = dx*dx + dy*dy;
    const t = Math.max(0, Math.min(1, ((ball.x - line.x1) * dx + (ball.y - line.y1) * dy) / lenSq));
    const closeX = line.x1 + t * dx;
    const closeY = line.y1 + t * dy;

    const distX = ball.x - closeX;
    const distY = ball.y - closeY;
    const distSq = distX*distX + distY*distY;

    if (distSq < ball.radius * ball.radius) {
      const dist = Math.sqrt(distSq);
      const nx = distX / dist;
      const ny = distY / dist;

      const overlap = ball.radius - dist;
      ball.x += nx * overlap;
      ball.y += ny * overlap;

      const isBouncy = isDynamic && line.type === 'bouncer';
      resolveCollisionPhysics(ball, nx, ny, isBouncy);

      if (isDynamic) {
        ball.vx += (Math.random() - 0.5) * 2;
        ball.vy += (Math.random() - 0.5) * 2;
      }
    }
  };

  const checkPinCollision = (ball: Marble, pin: CircleObstacle) => {
    const dx = ball.x - pin.x;
    const dy = ball.y - pin.y;
    const distSq = dx*dx + dy*dy;
    const minDist = ball.radius + pin.radius;

    if (distSq < minDist * minDist) {
      const dist = Math.sqrt(distSq);
      const nx = dx / dist;
      const ny = dy / dist;

      const overlap = minDist - dist;
      ball.x += nx * overlap;
      ball.y += ny * overlap;

      const isBumper = pin.type === 'bumper';

      const intensity = Math.sqrt(ball.vx*ball.vx + ball.vy*ball.vy);
      if (intensity > 1) {
          audio.playPinHit(intensity);
      }

      resolveCollisionPhysics(ball, nx, ny, isBumper);
    }
  };

  const checkMarbleCollision = (m1: Marble, m2: Marble) => {
    const dx = m2.x - m1.x;
    const dy = m2.y - m1.y;
    const distSq = dx*dx + dy*dy;
    const minDist = m1.radius + m2.radius;

    if (distSq < minDist * minDist) {
      const dist = Math.sqrt(distSq);
      const nx = dx / dist;
      const ny = dy / dist;
      const overlap = (minDist - dist) * 0.5;

      m1.x -= nx * overlap;
      m1.y -= ny * overlap;
      m2.x += nx * overlap;
      m2.y += ny * overlap;

      const dvx = m1.vx - m2.vx;
      const dvy = m1.vy - m2.vy;
      const dot = dvx * nx + dvy * ny;

      if (dot > 0) {
         if (dot > 2) audio.playPinHit(dot * 0.5);

         const impulse = dot * 0.9; 
         m1.vx -= impulse * nx;
         m1.vy -= impulse * ny;
         m2.vx += impulse * nx;
         m2.vy += impulse * ny;
      }
    }
  };

  // --- Initialization ---
  useEffect(() => {
    generateLevel();
    raceFinished.current = false;
    startTime.current = Date.now();
    cameraY.current = 0;
    timeRef.current = 0;
    teleportCooldowns.current = {};

    marblesRef.current = activeMarbles.map((m, index) => ({
      ...m,
      x: COURSE_WIDTH * 0.4 + (Math.random() * COURSE_WIDTH * 0.2),
      y: -50 - (index * 40),
      vx: (Math.random() - 0.5) * 5,
      vy: 0,
      angle: 0,
      omega: 0,
      finished: false,
      rank: 0
    }));

    audio.resume();

  }, [activeMarbles]); 

  // --- Drawing Subroutines ---

  const drawRepulsor = (ctx: CanvasRenderingContext2D, obj: DynamicObstacle) => {
    const pulse = (Math.sin(timeRef.current * obj.speed) + 1) * 0.5;
    const currentRadius = obj.width/2 + pulse * (obj.range! - obj.width/2);

    // Core
    ctx.beginPath();
    ctx.arc(0, 0, obj.width/2, 0, Math.PI * 2);
    ctx.fillStyle = '#8b5cf6'; // Violet
    ctx.fill();

    // Pulse Ring
    ctx.beginPath();
    ctx.arc(0, 0, currentRadius, 0, Math.PI * 2);
    ctx.strokeStyle = `rgba(139, 92, 246, ${1 - pulse})`;
    ctx.lineWidth = 2;
    ctx.stroke();
  };

  const drawConveyor = (ctx: CanvasRenderingContext2D, obj: DynamicObstacle) => {
    const w = obj.width; // length along X (rotated)
    const h = obj.height || 50; // width across Y

    ctx.beginPath();
    ctx.rect(-h/2, -w/2, h, w); // Swapped because conveyor angle usually down
    ctx.fillStyle = '#334155';
    ctx.fill();
    ctx.strokeStyle = '#475569';
    ctx.stroke();

    // Arrows
    const offset = (timeRef.current * obj.speed * 50) % 40;
    ctx.fillStyle = 'rgba(255, 255, 255, 0.3)';
    for(let i = -w/2; i < w/2; i+=40) {
        const y = i + offset;
        if (y > w/2) continue;

        ctx.save();
        ctx.translate(0, y); 
        ctx.beginPath();
        ctx.moveTo(-10, -5);
        ctx.lineTo(0, 5);
        ctx.lineTo(10, -5);
        ctx.fill();
        ctx.restore();
    }
  };

  const drawLaser = (ctx: CanvasRenderingContext2D, obj: DynamicObstacle) => {
     // Draw source
     ctx.fillStyle = '#111';
     ctx.beginPath();
     ctx.arc(0, 0, 10, 0, Math.PI * 2);
     ctx.fill();
     ctx.strokeStyle = '#ef4444';
     ctx.lineWidth = 2;
     ctx.stroke();

     if (obj.active) {
         const len = obj.height || 300;
         ctx.beginPath();
         ctx.moveTo(0, 0);
         ctx.lineTo(len, 0); // Local space, already rotated

         // Glow
         ctx.shadowColor = '#ef4444';
         ctx.shadowBlur = 15;
         ctx.strokeStyle = '#fca5a5';
         ctx.lineWidth = 4;
         ctx.stroke();

         // Inner Core
         ctx.shadowBlur = 0;
         ctx.strokeStyle = '#fff';
         ctx.lineWidth = 1;
         ctx.stroke();
     } else {
         // Warning LED
         ctx.fillStyle = timeRef.current % 30 < 15 ? '#ef4444' : '#550000';
         ctx.beginPath();
         ctx.arc(0, 0, 4, 0, Math.PI * 2);
         ctx.fill();
     }
  };

  const drawTeleporter = (ctx: CanvasRenderingContext2D, obj: DynamicObstacle, isExit = false) => {
      // Swirling portal effect
      const radius = obj.width / 2;
      const angleOffset = timeRef.current * (isExit ? -0.1 : 0.1);

      // Outer ring
      ctx.beginPath();
      ctx.arc(0, 0, radius, 0, Math.PI * 2);
      ctx.strokeStyle = isExit ? '#06b6d4' : '#d946ef'; // Cyan exit, Magenta entry
      ctx.lineWidth = 3;
      ctx.stroke();

      // Inner spirals
      ctx.save();
      ctx.rotate(angleOffset);
      for(let i=0; i<3; i++) {
          ctx.rotate((Math.PI * 2) / 3);
          ctx.beginPath();
          ctx.moveTo(0, 0);
          ctx.quadraticCurveTo(radius/2, 0, radius, radius/2);
          ctx.strokeStyle = isExit ? 'rgba(6,182,212,0.5)' : 'rgba(217,70,239,0.5)';
          ctx.lineWidth = 2;
          ctx.stroke();
      }
      ctx.restore();

      // Label
      ctx.fillStyle = '#fff';
      ctx.font = '10px Arial';
      ctx.textAlign = 'center';
      ctx.fillText(isExit ? 'OUT' : 'IN', 0, 4);
  };

  const drawLeaderboard = (ctx: CanvasRenderingContext2D, canvasWidth: number, canvasHeight: number) => {
    // Sort marbles
    const sorted = [...marblesRef.current].sort((a, b) => {
      if (a.finished && b.finished) return a.rank - b.rank;
      if (a.finished) return -1;
      if (b.finished) return 1;
      return b.y - a.y;
    });

    const boxWidth = 110; // Reduced width
    const itemHeight = 18; // Reduced height
    const startX = canvasWidth - boxWidth - 10;
    const startY = 110; // Moved down to avoid top overlap

    // Background
    ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
    ctx.roundRect(startX, startY, boxWidth, sorted.length * itemHeight + 10, 6);
    ctx.fill();
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.1)';
    ctx.lineWidth = 1;
    ctx.stroke();

    ctx.font = 'bold 10px "Roboto Mono"'; // Smaller font
    ctx.textAlign = 'left';
    ctx.textBaseline = 'middle';

    sorted.forEach((m, index) => {
       const y = startY + 12 + index * itemHeight;

       // Rank
       ctx.fillStyle = index === 0 ? '#fbbf24' : index === 1 ? '#9ca3af' : index === 2 ? '#b45309' : '#6b7280';
       ctx.fillText(`${index + 1}.`, startX + 8, y);

       // Color Dot
       ctx.fillStyle = m.color;
       ctx.beginPath();
       ctx.arc(startX + 30, y, 4, 0, Math.PI * 2);
       ctx.fill();

       // Name
       ctx.fillStyle = m.finished ? '#10b981' : '#e5e7eb';
       ctx.fillText(m.name, startX + 42, y);

       // Highlight Bet
       if (m.id === betMarbleId) {
          ctx.strokeStyle = '#fbbf24';
          ctx.lineWidth = 1;
          ctx.strokeRect(startX + 2, y - 9, boxWidth - 4, 18);
       }
    });
  };

  // --- Render Loop ---
  const draw = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const { offsetWidth, offsetHeight } = canvas;
    if (canvas.width !== offsetWidth || canvas.height !== offsetHeight) {
      canvas.width = offsetWidth;
      canvas.height = offsetHeight;
    }

    ctx.fillStyle = '#1f2937';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.save();
    const scale = canvas.width / COURSE_WIDTH;
    ctx.scale(scale, scale);
    const camY = Math.max(0, Math.min(cameraY.current, finishLineY.current - canvas.height/scale + 100));
    ctx.translate(0, -camY);

    // Draw Static Lines
    ctx.lineWidth = 4;
    ctx.lineCap = 'round';
    linesRef.current.forEach(l => {
      ctx.strokeStyle = l.type === 'wall' ? '#4b5563' : '#60a5fa';
      if (l.type === 'wall') ctx.lineWidth = 6;
      else ctx.lineWidth = 4;
      ctx.beginPath();
      ctx.moveTo(l.x1, l.y1);
      ctx.lineTo(l.x2, l.y2);
      ctx.stroke();
    });

    // Draw Dynamic Obstacles
    dynamicRef.current.forEach(obj => {

       if (obj.type === 'teleporter') {
           // Draw Entrance
           ctx.save();
           ctx.translate(obj.x, obj.y);
           drawTeleporter(ctx, obj, false);
           ctx.restore();

           // Draw Exit
           if (obj.destX !== undefined && obj.destY !== undefined) {
               ctx.save();
               ctx.translate(obj.destX, obj.destY);
               drawTeleporter(ctx, obj, true);
               ctx.restore();
           }
           return;
       }

       // For standard objects, save/rotate/draw/restore
       ctx.save();
       ctx.translate(obj.x, obj.y);
       ctx.rotate(obj.angle);

       if (obj.type === 'fan') {
          // Draw Fan Base
          ctx.fillStyle = '#64748b';
          ctx.fillRect(-10, -obj.width/2, 20, obj.width);

          // Draw Air Flow
          const range = obj.height || 200;
          const gradient = ctx.createLinearGradient(0, 0, range, 0);
          gradient.addColorStop(0, 'rgba(255, 255, 255, 0.4)');
          gradient.addColorStop(1, 'rgba(255, 255, 255, 0)');

          ctx.fillStyle = gradient;
          ctx.fillRect(0, -obj.width/2, range, obj.width);

          // Animated Lines
          ctx.strokeStyle = 'rgba(255, 255, 255, 0.5)';
          ctx.lineWidth = 1;
          const offset = (timeRef.current * 5) % 50;
          for(let i=0; i<3; i++) {
             const yPos = -obj.width/2 + (obj.width/4) * (i+1);
             ctx.beginPath();
             ctx.moveTo(10 + offset, yPos);
             ctx.lineTo(range - 20, yPos);
             ctx.stroke();
          }

       } else if (obj.type === 'repulsor') {
          drawRepulsor(ctx, obj);
       } else if (obj.type === 'conveyor') {
          drawConveyor(ctx, obj);
       } else if (obj.type === 'laser') {
          drawLaser(ctx, obj);
       } else {
         // Sliders & Spinners
         ctx.strokeStyle = obj.type === 'spinner' ? '#ef4444' : '#f59e0b';
         ctx.lineWidth = 8;
         ctx.beginPath();
         ctx.moveTo(-obj.width/2, 0);
         ctx.lineTo(obj.width/2, 0);
         ctx.stroke();

         if (obj.type === 'spinner') {
           ctx.beginPath();
           ctx.arc(0, 0, 5, 0, Math.PI * 2);
           ctx.fillStyle = '#fff';
           ctx.fill();
         }
       }
       ctx.restore();
    });

    // Draw Pins
    pinsRef.current.forEach(p => {
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.radius, 0, Math.PI * 2);
      ctx.fillStyle = p.type === 'bumper' ? '#f472b6' : '#9ca3af';
      ctx.fill();
    });

    // Draw Finish Line
    ctx.fillStyle = '#10b981';
    ctx.fillRect(0, finishLineY.current, COURSE_WIDTH, 10);
    for(let i=0; i<20; i++) {
        ctx.fillStyle = i%2===0 ? '#fff' : '#000';
        ctx.fillRect(i * (COURSE_WIDTH/20), finishLineY.current, COURSE_WIDTH/20, 10);
    }

    // Draw Marbles
    marblesRef.current.forEach(m => {
      ctx.save();
      ctx.translate(m.x, m.y);
      ctx.rotate(-m.angle); 

      ctx.beginPath();
      ctx.arc(0, 0, m.radius, 0, Math.PI * 2);
      ctx.fillStyle = m.color;
      ctx.shadowColor = 'rgba(0,0,0,0.5)';
      ctx.shadowBlur = 5;
      ctx.fill();
      ctx.shadowBlur = 0;

      ctx.beginPath();
      ctx.moveTo(-m.radius, 0);
      ctx.lineTo(m.radius, 0);
      ctx.strokeStyle = 'rgba(255,255,255,0.5)';
      ctx.lineWidth = 3;
      ctx.stroke();

      ctx.beginPath();
      ctx.moveTo(0, -m.radius);
      ctx.lineTo(0, m.radius);
      ctx.strokeStyle = 'rgba(0,0,0,0.3)';
      ctx.lineWidth = 2;
      ctx.stroke();

      ctx.beginPath();
      ctx.arc(-4, -4, 3, 0, Math.PI * 2);
      ctx.fillStyle = 'rgba(255,255,255,0.7)';
      ctx.fill();

      ctx.restore(); 

      if (m.id === betMarbleId) {
        ctx.strokeStyle = '#fbbf24';
        ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.arc(m.x, m.y, m.radius + 5, 0, Math.PI * 2);
        ctx.stroke();
      }

      if (!m.finished) {
        // Name only, rank badge removed
        ctx.fillStyle = '#fff';
        ctx.font = '10px Arial';
        ctx.textAlign = 'center';
        ctx.fillText(m.name, m.x, m.y - 18);
      }
    });

    ctx.restore(); // Restore from camera transform

    // Draw UI Overlay (Leaderboard) - in screen space (not camera space)
    drawLeaderboard(ctx, canvas.width, canvas.height);
  };

  useEffect(() => {
    const loop = () => {
      update();
      draw();
      requestRef.current = requestAnimationFrame(loop);
    };
    requestRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(requestRef.current!);
  });

  return (
    <canvas ref={canvasRef} className="w-full h-full block" />
  );
};

export default RaceEngine;

import React, { useRef, useEffect } from 'react';
import { Marble, PhysicsConfig, LineSegment, CircleObstacle, DynamicObstacle } from '../types';
import { audio } from '../services/audioService';

interface RaceEngineProps {
  activeMarbles: Marble[];
  config: PhysicsConfig;
  onRaceFinish: (results: Marble[]) => void;
  betMarbleId: number | null;
}

const RaceEngine: React.FC<RaceEngineProps> = ({ activeMarbles, config, onRaceFinish, betMarbleId }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();

  // Physics State (Mutable refs for performance)
  const marblesRef = useRef<Marble[]>([]);
  const linesRef = useRef<LineSegment[]>([]);
  const pinsRef = useRef<CircleObstacle[]>([]);
  const dynamicRef = useRef<DynamicObstacle[]>([]);
  const teleportCooldowns = useRef<Record<number, number>>({}); // marbleId -> timestamp

  const cameraY = useRef(0);
  const raceFinished = useRef(false);
  const finishLineY = useRef(0);
  const startTime = useRef(0);
  const timeRef = useRef(0);

  // Constants
  const COURSE_WIDTH = 600;

  // --- Level Generation ---
  const generateLevel = () => {
    const lines: LineSegment[] = [];
    const pins: CircleObstacle[] = [];
    const dynamics: DynamicObstacle[] = [];

    // Config
    const segments = 10 + Math.floor(Math.random() * 3);
    const segmentHeight = 450;
    let currentY = 0;

    // 1. Start Funnel
    lines.push({ x1: 0, y1: 0, x2: COURSE_WIDTH * 0.4, y2: 150, type: 'wall' });
    lines.push({ x1: COURSE_WIDTH, y1: 0, x2: COURSE_WIDTH * 0.6, y2: 150, type: 'wall' });
    lines.push({ x1: COURSE_WIDTH * 0.4, y1: 150, x2: COURSE_WIDTH * 0.4, y2: 180, type: 'wall' });
    lines.push({ x1: COURSE_WIDTH * 0.6, y1: 150, x2: COURSE_WIDTH * 0.6, y2: 180, type: 'wall' });

    currentY = 220;

    // 2. Procedural Segments
    for (let i = 0; i < segments; i++) {
      const type = Math.random();

      // Outer Walls
      lines.push({ x1: 0, y1: currentY - 50, x2: 0, y2: currentY + segmentHeight, type: 'wall' });
      lines.push({ x1: COURSE_WIDTH, y1: currentY - 50, x2: COURSE_WIDTH, y2: currentY + segmentHeight, type: 'wall' });

      if (type < 0.12) {
        // --- PROPELLERS (Spinners) ---
        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 100, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 100, type: 'floor' });

        dynamics.push({
          id: `spin_${i}_1`,
          type: 'spinner',
          x: COURSE_WIDTH * 0.35,
          y: currentY + 250,
          width: 140,
          angle: 0,
          speed: 0.1,
        });
        dynamics.push({
          id: `spin_${i}_2`,
          type: 'spinner',
          x: COURSE_WIDTH * 0.65,
          y: currentY + 350,
          width: 140,
          angle: Math.PI / 2,
          speed: -0.1,
        });

      } else if (type < 0.24) {
        // --- REPULSORS ---
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.3, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.7, y2: currentY + 150, type: 'floor' });

        dynamics.push({
          id: `repulse_${i}`,
          type: 'repulsor',
          x: COURSE_WIDTH / 2,
          y: currentY + 300,
          width: 50, 
          range: 120, 
          angle: 0,
          speed: 0.1, 
          force: 2.5
        });

      } else if (type < 0.36) {
        // --- CONVEYOR BELTS ---
        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.4, y2: currentY + 100, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.6, y2: currentY + 100, type: 'wall' });

        dynamics.push({
          id: `conveyor_${i}`,
          type: 'conveyor',
          x: COURSE_WIDTH * 0.5,
          y: currentY + 250,
          width: 200, // This acts as length along flow
          height: 100, // This acts as width of the path
          angle: Math.PI / 2, // Downwards
          speed: 0.1, 
          force: 15 
        });

      } else if (type < 0.48) {
        // --- LASER CANNONS (New) ---
        // Narrow path with a laser across it
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.3, y2: currentY + 150, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.7, y2: currentY + 150, type: 'wall' });

        dynamics.push({
          id: `laser_${i}`,
          type: 'laser',
          x: COURSE_WIDTH * 0.1, // Source on left
          y: currentY + 300,
          width: 0, 
          height: COURSE_WIDTH * 0.8, // Length of beam
          angle: 0, // Horizontal
          speed: 0,
          force: 20, // Strong push
          active: true,
          timer: 0
        });

        // Laser source visual box (wall)
        lines.push({ x1: 0, y1: currentY + 280, x2: COURSE_WIDTH * 0.15, y2: currentY + 320, type: 'wall' });

      } else if (type < 0.6) {
        // --- TELEPORTERS (New) ---
        // Entrance top, Exit bottom
        const entranceX = COURSE_WIDTH * (0.2 + Math.random() * 0.6);
        const exitX = COURSE_WIDTH * (0.2 + Math.random() * 0.6);

        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.2, y2: currentY + 100, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.8, y2: currentY + 100, type: 'floor' });

        dynamics.push({
          id: `teleport_${i}`,
          type: 'teleporter',
          x: entranceX,
          y: currentY + 150,
          width: 40, // Radius
          destX: exitX,
          destY: currentY + 350,
          angle: 0,
          speed: 0.05
        });

        // Add some obstacles around the exit to make it interesting
        pins.push({ x: exitX + 60, y: currentY + 350, radius: 15, type: 'bumper' });
        pins.push({ x: exitX - 60, y: currentY + 350, radius: 15, type: 'bumper' });

      } else if (type < 0.75) {
        // --- MOVING ELEVATORS ---
        const isVertical = Math.random() > 0.5;

        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.2, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.8, y2: currentY + 150, type: 'floor' });

        if (isVertical) {
           dynamics.push({
             id: `slide_v_${i}`,
             type: 'slider_v',
             x: COURSE_WIDTH / 2,
             y: currentY + 200,
             width: 200,
             angle: 0,
             speed: 1, 
             range: 100,
             initialX: COURSE_WIDTH / 2,
             initialY: currentY + 250
           });
        } else {
           dynamics.push({
            id: `slide_h_${i}`,
            type: 'slider_h',
            x: COURSE_WIDTH / 2,
            y: currentY + 250,
            width: 250,
            angle: 0,
            speed: 2,
            range: 150,
            initialX: COURSE_WIDTH / 2,
            initialY: currentY + 250
          });
        }

      } else if (type < 0.85) {
        // --- WIND CANNONS ---
        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 100, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 100, type: 'floor' });

        dynamics.push({
          id: `fan_${i}_1`,
          type: 'fan',
          x: 20, 
          y: currentY + 250,
          width: 40,
          height: 300, 
          angle: 0, 
          speed: 0,
          force: 0.6
        });

        pins.push({ x: COURSE_WIDTH * 0.6, y: currentY + 250, radius: 20, type: 'bumper' });

      } else {
         // --- CLASSIC SLALOM ---
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.6, y2: currentY + 180, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 250, x2: COURSE_WIDTH * 0.4, y2: currentY + 380, type: 'floor' });
        pins.push({ x: COURSE_WIDTH * 0.8, y: currentY + 200, radius: 15, type: 'bumper' });
        pins.push({ x: COURSE_WIDTH * 0.2, y: currentY + 400, radius: 15, type: 'bumper' });
      }

      currentY += segmentHeight;
    }

    // 3. Finish Area
    lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 200, type: 'floor' });
    lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 200, type: 'floor' });

    finishLineY.current = currentY + 250;

    linesRef.current = lines;
    pinsRef.current = pins;
    dynamicRef.current = dynamics;
  };

  // --- Physics Logic ---
  const update = () => {
    if (raceFinished.current) {
        audio.updateRolling(0); 
        return;
    }

    const STEPS = 4;
    const dt = 1 / STEPS;
    timeRef.current += 1;
    const now = Date.now();

    const marbles = marblesRef.current;
    const dynamicObjs = dynamicRef.current;

    let totalSpeed = 0;

    // --- MERCY RULE CHECK ---
    const activeMarblesCount = marbles.filter(m => !m.finished).length;
    const totalMarbles = marbles.length;

    if (totalMarbles > 1 && activeMarblesCount === 1) {
        const loser = marbles.find(m => !m.finished);
        if (loser) {
            loser.finished = true;
            loser.rank = totalMarbles; 
            loser.finishTime = now - startTime.current + 99999; 
        }

        if (!raceFinished.current) {
            raceFinished.current = true;
            const sorted = [...marbles].sort((a, b) => a.rank - b.rank);
            audio.playFinish(); 
            setTimeout(() => onRaceFinish(sorted), 1000);
            return;
        }
    }

    // Separate dynamic types
    const fans: DynamicObstacle[] = [];
    const repulsors: DynamicObstacle[] = [];
    const conveyors: DynamicObstacle[] = [];
    const lasers: DynamicObstacle[] = [];
    const teleporters: DynamicObstacle[] = [];
    const solidDynamics: DynamicObstacle[] = [];

    dynamicObjs.forEach(obj => {
      if (obj.type === 'fan') { fans.push(obj); return; }
      if (obj.type === 'repulsor') { repulsors.push(obj); return; }
      if (obj.type === 'conveyor') { conveyors.push(obj); return; }
      if (obj.type === 'laser') { lasers.push(obj); return; }
      if (obj.type === 'teleporter') { teleporters.push(obj); return; }

      solidDynamics.push(obj);

      if (obj.type === 'spinner') {
        obj.angle += obj.speed;
      } else if (obj.type === 'slider_h') {
        obj.x = obj.initialX! + Math.sin(timeRef.current * 0.02) * (obj.range || 100);
      } else if (obj.type === 'slider_v') {
        obj.y = obj.initialY! + Math.sin(timeRef.current * 0.015) * (obj.range || 80);
      }
    });

    lasers.forEach(l => {
       l.timer = (l.timer || 0) + 1;
       if (l.timer > 180) {
           l.active = !l.active;
           l.timer = 0;
       }
    });

    const dynamicLines: LineSegment[] = [];
    solidDynamics.forEach(obj => {
      const halfW = obj.width / 2;
      const dx = Math.cos(obj.angle) * halfW;
      const dy = Math.sin(obj.angle) * halfW;
      dynamicLines.push({
        x1: obj.x - dx, y1: obj.y - dy,
        x2: obj.x + dx, y2: obj.y + dy,
        type: obj.type === 'spinner' ? 'bouncer' : 'floor'
      });
    });

    for (let step = 0; step < STEPS; step++) {
      for (let i = 0; i < marbles.length; i++) {
        const m = marbles[i];
        if (m.finished) continue;

        m.vy += config.gravity * dt;
        m.x += m.vx * dt;
        m.y += m.vy * dt;

        // Fan Physics
        for (const fan of fans) {
          const dx = m.x - fan.x;
          const dy = m.y - fan.y;
          const localX = dx * Math.cos(-fan.angle) - dy * Math.sin(-fan.angle);
          const localY = dx * Math.sin(-fan.angle) + dy * Math.cos(-fan.angle);
          const halfWidth = fan.width / 2; 
          const range = fan.height || 200;

          if (localX > 0 && localX < range && Math.abs(localY) < halfWidth) {
             const force = fan.force || 0.5;
             const forceX = Math.cos(fan.angle) * force;
             const forceY = Math.sin(fan.angle) * force;
             m.vx += forceX * dt;
             m.vy += forceY * dt;
          }
        }

        // Repulsor Physics
        for (const rep of repulsors) {
          const dx = m.x - rep.x;
          const dy = m.y - rep.y;
          const distSq = dx*dx + dy*dy;
          const range = rep.range || 100;

          if (distSq < range * range) {
             const dist = Math.sqrt(distSq);
             const nx = dx / dist;
             const ny = dy / dist;
             const pulse = (Math.sin(timeRef.current * rep.speed) + 1) * 0.5;
             const force = (rep.force || 1) * (1 - dist/range) * (0.5 + pulse);
             m.vx += nx * force * dt * 50;
             m.vy += ny * force * dt * 50;
          }
        }

        // Conveyor Physics
        for (const conv of conveyors) {
           const dx = m.x - conv.x;
           const dy = m.y - conv.y;

           // Calculate position relative to conveyor center, aligned with rotation
           const localParallel = dx * Math.cos(-conv.angle) - dy * Math.sin(-conv.angle); // Along the belt (length)
           const localPerp = dx * Math.sin(-conv.angle) + dy * Math.cos(-conv.angle); // Across the belt (width)

           // In generateLevel: width is length (200), height is width of path (100)
           const halfLength = conv.width / 2;
           const halfWidth = (conv.height || 50) / 2;

           if (Math.abs(localParallel) < halfLength && Math.abs(localPerp) < halfWidth) {
              const force = conv.force || 10;
              const forceX = Math.cos(conv.angle) * force;
              const forceY = Math.sin(conv.angle) * force;
              m.vx += forceX * dt;
              m.vy += forceY * dt;
           }
        }

        // Laser Physics
        for (const laser of lasers) {
            if (!laser.active) continue;
            const len = laser.height || 300;
            const lx1 = laser.x;
            const ly1 = laser.y;
            const lx2 = lx1 + Math.cos(laser.angle) * len;
            const ly2 = ly1 + Math.sin(laser.angle) * len;

            const A = m.x - lx1;
            const B = m.y - ly1;
            const C = lx2 - lx1;
            const D = ly2 - ly1;

            const dot = A * C + B * D;
            const lenSq = C * C + D * D;
            let param = -1;
            if (lenSq !== 0) param = dot / lenSq;

            let xx, yy;

            if (param < 0) {
                xx = lx1; yy = ly1;
            } else if (param > 1) {
                xx = lx2; yy = ly2;
            } else {
                xx = lx1 + param * C;
                yy = ly1 + param * D;
            }

            const dx = m.x - xx;
            const dy = m.y - yy;
            const dist = Math.sqrt(dx * dx + dy * dy);

            if (dist < m.radius + 5) { 
                const force = laser.force || 20;
                m.vx += (dx/dist) * force * dt * 10;
                m.vy += (dy/dist) * force * dt * 10;
                m.vx += (Math.random() - 0.5) * 10;
                m.vy += (Math.random() - 0.5) * 10;
            }
        }

        // Teleporter Physics
        for (const tele of teleporters) {
            const dx = m.x - tele.x;
            const dy = m.y - tele.y;
            const dist = Math.sqrt(dx*dx + dy*dy);

            if (dist < (tele.width/2) && (!teleportCooldowns.current[m.id] || now > teleportCooldowns.current[m.id])) {
                 m.x = tele.destX || m.x;
                 m.y = tele.destY || m.y;
                 m.vx *= 0.5; 
                 m.vy = Math.abs(m.vy) + 2; 
                 teleportCooldowns.current[m.id] = now + 1000; 
                 audio.playPinHit(5); 
            }
        }

        m.angle += m.omega * dt;
        m.omega *= 0.999; 

        m.vx *= Math.pow(config.friction, dt);
        m.vy *= Math.pow(config.friction, dt);

        if (m.vx*m.vx + m.vy*m.vy < 0.2) {
             m.vx += (Math.random() - 0.5); 
             m.vy += 0.5; 
        }

        for (const line of linesRef.current) checkLineCollision(m, line);
        for (const dLine of dynamicLines) checkLineCollision(m, dLine, true);
        for (const pin of pinsRef.current) checkPinCollision(m, pin);

        for (let j = i + 1; j < marbles.length; j++) {
           if (!marbles[j].finished) checkMarbleCollision(m, marbles[j]);
        }

        if (m.y > finishLineY.current) {
          m.finished = true;
          m.finishTime = Date.now() - startTime.current;
          const finishedSoFar = marbles.filter(b => b.finished).length;
          m.rank = finishedSoFar;
          audio.playPinHit(10);
        }

        if (!m.finished) {
            totalSpeed += Math.sqrt(m.vx*m.vx + m.vy*m.vy + m.omega*m.radius*m.omega*m.radius);
        }
      }
    }

    audio.updateRolling(totalSpeed);

    const activeMarblesList = marbles.filter(m => !m.finished);
    if (activeMarblesList.length > 0) {
      activeMarblesList.sort((a, b) => b.y - a.y);
      const leaders = activeMarblesList.slice(0, 3); 
      const avgY = leaders.reduce((a, b) => a + b.y, 0) / leaders.length;
      cameraY.current += (avgY - cameraY.current - 300) * 0.08;
    } else {
      if (!raceFinished.current) {
        raceFinished.current = true;
        const sorted = [...marbles].sort((a, b) => a.rank - b.rank);
        audio.playFinish(); 
        setTimeout(() => onRaceFinish(sorted), 1000);
      }
    }
  };

  const resolveCollisionPhysics = (ball: Marble, nx: number, ny: number, isBouncy: boolean) => {
    const vDotN = ball.vx * nx + ball.vy * ny;
    if (vDotN > 0) return; 

    const intensity = Math.abs(vDotN);
    if (intensity > 1.0) {
        audio.playBump(intensity);
    }

    const restitution = isBouncy ? 1.5 : config.restitution;
    const jN = -(1 + restitution) * vDotN;
    ball.vx += jN * nx;
    ball.vy += jN * ny;

    const tx = -ny;
    const ty = nx;
    const vDotT = ball.vx * tx + ball.vy * ty;
    const vSurf = vDotT + ball.omega * ball.radius;

    const mass = 1.0;
    const jT_ideal = -vSurf / (3.5 / mass);
    const mu = 0.5;
    const maxJt = mu * Math.abs(jN);

    let jT = jT_ideal;
    if (Math.abs(jT) > maxJt) {
       jT = Math.sign(jT) * maxJt;
    }

    ball.vx += jT * tx;
    ball.vy += jT * ty;
    ball.omega += (2.5 * jT) / (mass * ball.radius);
  };

  const checkLineCollision = (ball: Marble, line: LineSegment, isDynamic = false) => {
    const dx = line.x2 - line.x1;
    const dy = line.y2 - line.y1;
    const lenSq = dx*dx + dy*dy;
    const t = Math.max(0, Math.min(1, ((ball.x - line.x1) * dx + (ball.y - line.y1) * dy) / lenSq));
    const closeX = line.x1 + t * dx;
    const closeY = line.y1 + t * dy;

    const distX = ball.x - closeX;
    const distY = ball.y - closeY;
    const distSq = distX*distX + distY*distY;

    if (distSq < ball.radius * ball.radius) {
      const dist = Math.sqrt(distSq);
      const nx = distX / dist;
      const ny = distY / dist;

      const overlap = ball.radius - dist;
      ball.x += nx * overlap;
      ball.y += ny * overlap;

      const isBouncy = isDynamic && line.type === 'bouncer';
      resolveCollisionPhysics(ball, nx, ny, isBouncy);

      if (isDynamic) {
        ball.vx += (Math.random() - 0.5) * 2;
        ball.vy += (Math.random() - 0.5) * 2;
      }
    }
  };

  const checkPinCollision = (ball: Marble, pin: CircleObstacle) => {
    const dx = ball.x - pin.x;
    const dy = ball.y - pin.y;
    const distSq = dx*dx + dy*dy;
    const minDist = ball.radius + pin.radius;

    if (distSq < minDist * minDist) {
      const dist = Math.sqrt(distSq);
      const nx = dx / dist;
      const ny = dy / dist;

      const overlap = minDist - dist;
      ball.x += nx * overlap;
      ball.y += ny * overlap;

      const isBumper = pin.type === 'bumper';

      const intensity = Math.sqrt(ball.vx*ball.vx + ball.vy*ball.vy);
      if (intensity > 1) {
          audio.playPinHit(intensity);
      }

      resolveCollisionPhysics(ball, nx, ny, isBumper);
    }
  };

  const checkMarbleCollision = (m1: Marble, m2: Marble) => {
    const dx = m2.x - m1.x;
    const dy = m2.y - m1.y;
    const distSq = dx*dx + dy*dy;
    const minDist = m1.radius + m2.radius;

    if (distSq < minDist * minDist) {
      const dist = Math.sqrt(distSq);
      const nx = dx / dist;
      const ny = dy / dist;
      const overlap = (minDist - dist) * 0.5;

      m1.x -= nx * overlap;
      m1.y -= ny * overlap;
      m2.x += nx * overlap;
      m2.y += ny * overlap;

      const dvx = m1.vx - m2.vx;
      const dvy = m1.vy - m2.vy;
      const dot = dvx * nx + dvy * ny;

      if (dot > 0) {
         if (dot > 2) audio.playPinHit(dot * 0.5);

         const impulse = dot * 0.9; 
         m1.vx -= impulse * nx;
         m1.vy -= impulse * ny;
         m2.vx += impulse * nx;
         m2.vy += impulse * ny;
      }
    }
  };

  // --- Initialization ---
  useEffect(() => {
    generateLevel();
    raceFinished.current = false;
    startTime.current = Date.now();
    cameraY.current = 0;
    timeRef.current = 0;
    teleportCooldowns.current = {};

    marblesRef.current = activeMarbles.map((m, index) => ({
      ...m,
      x: COURSE_WIDTH * 0.4 + (Math.random() * COURSE_WIDTH * 0.2),
      y: -50 - (index * 40),
      vx: (Math.random() - 0.5) * 5,
      vy: 0,
      angle: 0,
      omega: 0,
      finished: false,
      rank: 0
    }));

    audio.resume();

  }, [activeMarbles]); 

  // --- Drawing Subroutines ---

  const drawRepulsor = (ctx: CanvasRenderingContext2D, obj: DynamicObstacle) => {
    const pulse = (Math.sin(timeRef.current * obj.speed) + 1) * 0.5;
    const currentRadius = obj.width/2 + pulse * (obj.range! - obj.width/2);

    // Core
    ctx.beginPath();
    ctx.arc(0, 0, obj.width/2, 0, Math.PI * 2);
    ctx.fillStyle = '#8b5cf6'; // Violet
    ctx.fill();

    // Pulse Ring
    ctx.beginPath();
    ctx.arc(0, 0, currentRadius, 0, Math.PI * 2);
    ctx.strokeStyle = `rgba(139, 92, 246, ${1 - pulse})`;
    ctx.lineWidth = 2;
    ctx.stroke();
  };

  const drawConveyor = (ctx: CanvasRenderingContext2D, obj: DynamicObstacle) => {
    // Corrected logic: Draw aligned with the angle of rotation.
    // Physics pushes towards `angle`.
    // Canvas is rotated by `angle`.
    // Therefore, "Down stream" is positive X in local space.

    const length = obj.width;  // 200 (Length along flow)
    const thickness = obj.height || 50; // 100 (Width of path)

    // Draw Base Rectangle
    // Aligned with X axis (flow direction)
    ctx.beginPath();
    ctx.rect(-length/2, -thickness/2, length, thickness);
    ctx.fillStyle = '#334155';
    ctx.fill();
    ctx.strokeStyle = '#475569';
    ctx.stroke();

    // Draw Arrows
    // Iterate along the X axis (flow direction)
    const spacing = 40;
    const offset = (timeRef.current * obj.speed * 50) % spacing;

    ctx.fillStyle = 'rgba(255, 255, 255, 0.4)';

    // Loop from left (-length/2) to right (length/2)
    for(let x = -length/2; x < length/2; x += spacing) {
        const currentX = x + offset;
        if (currentX > length/2) continue;

        ctx.save();
        ctx.translate(currentX, 0); // Move along local X (flow)

        // Draw Arrow pointing to +X (Right in local space, Down/Direction of flow in world space)
        ctx.beginPath();
        ctx.moveTo(-5, -8);
        ctx.lineTo(5, 0);
        ctx.lineTo(-5, 8);
        ctx.fill();

        ctx.restore();
    }
  };

  const drawLaser = (ctx: CanvasRenderingContext2D, obj: DynamicObstacle) => {
     // Draw source
     ctx.fillStyle = '#111';
     ctx.beginPath();
     ctx.arc(0, 0, 10, 0, Math.PI * 2);
     ctx.fill();
     ctx.strokeStyle = '#ef4444';
     ctx.lineWidth = 2;
     ctx.stroke();

     if (obj.active) {
         const len = obj.height || 300;
         ctx.beginPath();
         ctx.moveTo(0, 0);
         ctx.lineTo(len, 0); // Local space, already rotated

         // Glow
         ctx.shadowColor = '#ef4444';
         ctx.shadowBlur = 15;
         ctx.strokeStyle = '#fca5a5';
         ctx.lineWidth = 4;
         ctx.stroke();

         // Inner Core
         ctx.shadowBlur = 0;
         ctx.strokeStyle = '#fff';
         ctx.lineWidth = 1;
         ctx.stroke();
     } else {
         // Warning LED
         ctx.fillStyle = timeRef.current % 30 < 15 ? '#ef4444' : '#550000';
         ctx.beginPath();
         ctx.arc(0, 0, 4, 0, Math.PI * 2);
         ctx.fill();
     }
  };

  const drawTeleporter = (ctx: CanvasRenderingContext2D, obj: DynamicObstacle, isExit = false) => {
      // Swirling portal effect
      const radius = obj.width / 2;
      const angleOffset = timeRef.current * (isExit ? -0.1 : 0.1);

      // Outer ring
      ctx.beginPath();
      ctx.arc(0, 0, radius, 0, Math.PI * 2);
      ctx.strokeStyle = isExit ? '#06b6d4' : '#d946ef'; // Cyan exit, Magenta entry
      ctx.lineWidth = 3;
      ctx.stroke();

      // Inner spirals
      ctx.save();
      ctx.rotate(angleOffset);
      for(let i=0; i<3; i++) {
          ctx.rotate((Math.PI * 2) / 3);
          ctx.beginPath();
          ctx.moveTo(0, 0);
          ctx.quadraticCurveTo(radius/2, 0, radius, radius/2);
          ctx.strokeStyle = isExit ? 'rgba(6,182,212,0.5)' : 'rgba(217,70,239,0.5)';
          ctx.lineWidth = 2;
          ctx.stroke();
      }
      ctx.restore();

      // Label
      ctx.fillStyle = '#fff';
      ctx.font = '10px Arial';
      ctx.textAlign = 'center';
      ctx.fillText(isExit ? 'OUT' : 'IN', 0, 4);
  };

  const drawLeaderboard = (ctx: CanvasRenderingContext2D, canvasWidth: number, canvasHeight: number) => {
    // Sort marbles
    const sorted = [...marblesRef.current].sort((a, b) => {
      if (a.finished && b.finished) return a.rank - b.rank;
      if (a.finished) return -1;
      if (b.finished) return 1;
      return b.y - a.y;
    });

    const boxWidth = 110; // Reduced width
    const itemHeight = 18; // Reduced height
    const startX = canvasWidth - boxWidth - 10;
    const startY = 110; // Moved down to avoid top overlap

    // Background
    ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
    ctx.roundRect(startX, startY, boxWidth, sorted.length * itemHeight + 10, 6);
    ctx.fill();
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.1)';
    ctx.lineWidth = 1;
    ctx.stroke();

    ctx.font = 'bold 10px "Roboto Mono"'; // Smaller font
    ctx.textAlign = 'left';
    ctx.textBaseline = 'middle';

    sorted.forEach((m, index) => {
       const y = startY + 12 + index * itemHeight;

       // Rank
       ctx.fillStyle = index === 0 ? '#fbbf24' : index === 1 ? '#9ca3af' : index === 2 ? '#b45309' : '#6b7280';
       ctx.fillText(`${index + 1}.`, startX + 8, y);

       // Color Dot
       ctx.fillStyle = m.color;
       ctx.beginPath();
       ctx.arc(startX + 30, y, 4, 0, Math.PI * 2);
       ctx.fill();

       // Name
       ctx.fillStyle = m.finished ? '#10b981' : '#e5e7eb';
       ctx.fillText(m.name, startX + 42, y);

       // Highlight Bet
       if (m.id === betMarbleId) {
          ctx.strokeStyle = '#fbbf24';
          ctx.lineWidth = 1;
          ctx.strokeRect(startX + 2, y - 9, boxWidth - 4, 18);
       }
    });
  };

  // --- Render Loop ---
  const draw = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const { offsetWidth, offsetHeight } = canvas;
    if (canvas.width !== offsetWidth || canvas.height !== offsetHeight) {
      canvas.width = offsetWidth;
      canvas.height = offsetHeight;
    }

    ctx.fillStyle = '#1f2937';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.save();
    const scale = canvas.width / COURSE_WIDTH;
    ctx.scale(scale, scale);
    const camY = Math.max(0, Math.min(cameraY.current, finishLineY.current - canvas.height/scale + 100));
    ctx.translate(0, -camY);

    // Draw Static Lines
    ctx.lineWidth = 4;
    ctx.lineCap = 'round';
    linesRef.current.forEach(l => {
      ctx.strokeStyle = l.type === 'wall' ? '#4b5563' : '#60a5fa';
      if (l.type === 'wall') ctx.lineWidth = 6;
      else ctx.lineWidth = 4;
      ctx.beginPath();
      ctx.moveTo(l.x1, l.y1);
      ctx.lineTo(l.x2, l.y2);
      ctx.stroke();
    });

    // Draw Dynamic Obstacles
    dynamicRef.current.forEach(obj => {

       if (obj.type === 'teleporter') {
           // Draw Entrance
           ctx.save();
           ctx.translate(obj.x, obj.y);
           drawTeleporter(ctx, obj, false);
           ctx.restore();

           // Draw Exit
           if (obj.destX !== undefined && obj.destY !== undefined) {
               ctx.save();
               ctx.translate(obj.destX, obj.destY);
               drawTeleporter(ctx, obj, true);
               ctx.restore();
           }
           return;
       }

       // For standard objects, save/rotate/draw/restore
       ctx.save();
       ctx.translate(obj.x, obj.y);
       ctx.rotate(obj.angle);

       if (obj.type === 'fan') {
          // Draw Fan Base
          ctx.fillStyle = '#64748b';
          ctx.fillRect(-10, -obj.width/2, 20, obj.width);

          // Draw Air Flow
          const range = obj.height || 200;
          const gradient = ctx.createLinearGradient(0, 0, range, 0);
          gradient.addColorStop(0, 'rgba(255, 255, 255, 0.4)');
          gradient.addColorStop(1, 'rgba(255, 255, 255, 0)');

          ctx.fillStyle = gradient;
          ctx.fillRect(0, -obj.width/2, range, obj.width);

          // Animated Lines
          ctx.strokeStyle = 'rgba(255, 255, 255, 0.5)';
          ctx.lineWidth = 1;
          const offset = (timeRef.current * 5) % 50;
          for(let i=0; i<3; i++) {
             const yPos = -obj.width/2 + (obj.width/4) * (i+1);
             ctx.beginPath();
             ctx.moveTo(10 + offset, yPos);
             ctx.lineTo(range - 20, yPos);
             ctx.stroke();
          }

       } else if (obj.type === 'repulsor') {
          drawRepulsor(ctx, obj);
       } else if (obj.type === 'conveyor') {
          drawConveyor(ctx, obj);
       } else if (obj.type === 'laser') {
          drawLaser(ctx, obj);
       } else {
         // Sliders & Spinners
         ctx.strokeStyle = obj.type === 'spinner' ? '#ef4444' : '#f59e0b';
         ctx.lineWidth = 8;
         ctx.beginPath();
         ctx.moveTo(-obj.width/2, 0);
         ctx.lineTo(obj.width/2, 0);
         ctx.stroke();

         if (obj.type === 'spinner') {
           ctx.beginPath();
           ctx.arc(0, 0, 5, 0, Math.PI * 2);
           ctx.fillStyle = '#fff';
           ctx.fill();
         }
       }
       ctx.restore();
    });

    // Draw Pins
    pinsRef.current.forEach(p => {
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.radius, 0, Math.PI * 2);
      ctx.fillStyle = p.type === 'bumper' ? '#f472b6' : '#9ca3af';
      ctx.fill();
    });

    // Draw Finish Line
    ctx.fillStyle = '#10b981';
    ctx.fillRect(0, finishLineY.current, COURSE_WIDTH, 10);
    for(let i=0; i<20; i++) {
        ctx.fillStyle = i%2===0 ? '#fff' : '#000';
        ctx.fillRect(i * (COURSE_WIDTH/20), finishLineY.current, COURSE_WIDTH/20, 10);
    }

    // Draw Marbles
    marblesRef.current.forEach(m => {
      ctx.save();
      ctx.translate(m.x, m.y);
      ctx.rotate(-m.angle); 

      ctx.beginPath();
      ctx.arc(0, 0, m.radius, 0, Math.PI * 2);
      ctx.fillStyle = m.color;
      ctx.shadowColor = 'rgba(0,0,0,0.5)';
      ctx.shadowBlur = 5;
      ctx.fill();
      ctx.shadowBlur = 0;

      ctx.beginPath();
      ctx.moveTo(-m.radius, 0);
      ctx.lineTo(m.radius, 0);
      ctx.strokeStyle = 'rgba(255,255,255,0.5)';
      ctx.lineWidth = 3;
      ctx.stroke();

      ctx.beginPath();
      ctx.moveTo(0, -m.radius);
      ctx.lineTo(0, m.radius);
      ctx.strokeStyle = 'rgba(0,0,0,0.3)';
      ctx.lineWidth = 2;
      ctx.stroke();

      ctx.beginPath();
      ctx.arc(-4, -4, 3, 0, Math.PI * 2);
      ctx.fillStyle = 'rgba(255,255,255,0.7)';
      ctx.fill();

      ctx.restore(); 

      if (m.id === betMarbleId) {
        ctx.strokeStyle = '#fbbf24';
        ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.arc(m.x, m.y, m.radius + 5, 0, Math.PI * 2);
        ctx.stroke();
      }

      if (!m.finished) {
        // Name only, rank badge removed
        ctx.fillStyle = '#fff';
        ctx.font = '10px Arial';
        ctx.textAlign = 'center';
        ctx.fillText(m.name, m.x, m.y - 18);
      }
    });

    ctx.restore(); // Restore from camera transform

    // Draw UI Overlay (Leaderboard) - in screen space (not camera space)
    drawLeaderboard(ctx, canvas.width, canvas.height);
  };

  useEffect(() => {
    const loop = () => {
      update();
      draw();
      requestRef.current = requestAnimationFrame(loop);
    };
    requestRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(requestRef.current!);
  });

  return (
    <canvas ref={canvasRef} className="w-full h-full block" />
  );
};

